/// The largest request a connection takes; `parse_buf` holds one whole.
pub const MAX_REQUEST_SIZE = proto.MAX_REQUEST_BYTES;
/// How much `readFromClient` reads from a socket at once.
const READ_CHUNK: usize = 64 * 1024;
/// The largest answer or payload a handler builds in `scratch`: an answer
/// frame of up to MAX_REQUEST_SIZE bytes, header included (a whole kv.get
/// answer, or one `deliverDeferredOk` frames for another shard or node), or
/// a single-key KV entry's payload.
pub const SCRATCH_SIZE: usize = @max(@sizeOf(proto.ResponseHeader) + MAX_REQUEST_SIZE, @sizeOf(proto.ResponseHeader) + table_run.op("kv.get").response.max_size, kv_handler_mod.MAX_KEY_ENTRY_PAYLOAD, kv_entries.Reap.max_size);
comptime {
    // An answer frame is sized from the request limit.
    std.debug.assert(MAX_REQUEST_SIZE >= proto.MAX_ANSWER_BYTES);
    // `deliverDeferredOk` frames an answer of up to MAX_REQUEST_SIZE bytes
    // in scratch for a client on another shard or node.
    std.debug.assert(SCRATCH_SIZE >= @sizeOf(proto.ResponseHeader) + MAX_REQUEST_SIZE);
}
/// A read buffer grows to hold one whole request (and the start of the next).
const MAX_READ_BUFFER = 2 * MAX_REQUEST_SIZE;

