    return .{ .ns = ns_table.DEFAULT.int(), .action = name, .run = run_id, .input = "{}", .labels = null, .source = .direct, .caller_run = null, .caller_workflow = null };
}

test "Shard: init and deinit" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    // Its mapped buffers bypass the testing allocator's leak check: they
    // are counted, and every one comes back at deinit.
    const mapped = large_buffer.mapped_bytes.load(.monotonic);
    var shard = try Shard.init(std.testing.allocator, 0, 4, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer std.testing.expectEqual(mapped, large_buffer.mapped_bytes.load(.monotonic)) catch @panic("a shard's mapped buffer was not freed");
    defer shard.deinit();
    try std.testing.expect(large_buffer.mapped_bytes.load(.monotonic) > mapped);

    try std.testing.expectEqual(@as(u16, 0), shard.id);
    try std.testing.expectEqual(@as(u32, 0), shard.connectionCount());
    try std.testing.expect(!shard.stop_requested.load(.acquire));
}

test "Shard: add and remove connections" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);

    var shard = try Shard.init(std.testing.allocator, 0, 4, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();

    // Create test pipes to use as fake connection fds
    const conn_pipe = try @import("stdx").io.pipe();
    defer _ = std.c.close(conn_pipe[0]);
    defer _ = std.c.close(conn_pipe[1]);

    const conn = try shard.addConnection(conn_pipe[0]);
    try std.testing.expectEqual(@as(u32, 1), shard.connectionCount());
    try std.testing.expectEqual(@as(u32, 1), conn.id);

    shard.removeConnection(conn_pipe[0]);
    try std.testing.expectEqual(@as(u32, 0), shard.connectionCount());
}

/// Build a fresh shard-0 replica (node `node_id`, alone), apply the genesis
/// pool-share and this node's memory row, and return the budget it derived.
fn deriveBudgetOnFreshShard(node_id: u32, ram_bytes: u64, reserve_bytes: u64) !memory_budget.Observation {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, node_id, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    const base = r.last_applied;

    var share_buf: [settings_machine.SetShare.max_size]u8 = undefined;
    const share_bytes = try settings_machine.SetShare.encodeInto(&share_buf, .{ .share_permille = 700 });
    const share_entry = entry_mod.buildEntry(.settings_pool_share, entry_mod.Flags.NONE, r.current_term, base + 1, 0, share_bytes);
    var out = persistence_mod.Result.start(&share_entry);
    try std.testing.expect(shard.applyEntry(&share_entry, &out));

    var row_buf: [settings_machine.SetNodeMem.max_size]u8 = undefined;
    const row_bytes = try settings_machine.SetNodeMem.encodeInto(&row_buf, .{ .node_id = node_id, .ram_bytes = ram_bytes, .reserve = reserve_bytes });
    const row_entry = entry_mod.buildEntry(.settings_node_mem, entry_mod.Flags.NONE, r.current_term, base + 2, 0, row_bytes);
    out = persistence_mod.Result.start(&row_entry);
    try std.testing.expect(shard.applyEntry(&row_entry, &out));

    return shard.budget;
}

test "memory budget: a settings row applies and every replica derives the same budget" {
    const ram: u64 = 2 * 1024 * 1024 * 1024;
    const reserve: u64 = 100 * 1024 * 1024;
    const expected = (ram - reserve) * 700 / 1000;

    const a = try deriveBudgetOnFreshShard(1, ram, reserve);
    try std.testing.expectEqual(expected, a.budget_bytes);
    try std.testing.expectEqual(@as(?u32, 1), a.governing_node);
    try std.testing.expectEqual(@as(?u32, null), a.provisional_node);

    // A second replica built independently applies the same entries and lands
    // on the same budget: the derive reads only committed state, so every
    // replica agrees.
    const b = try deriveBudgetOnFreshShard(1, ram, reserve);
    try std.testing.expectEqual(a.budget_bytes, b.budget_bytes);
    try std.testing.expectEqual(a.governing_node, b.governing_node);
}

test "memory budget: a lagging replica derives over the applied config, not the committed one" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;

    // Node 1 has reported its row.
    const ram: u64 = 2 * 1024 * 1024 * 1024;
    const reserve: u64 = 100 * 1024 * 1024;
    var row_buf: [settings_machine.SetNodeMem.max_size]u8 = undefined;
    const row_bytes = try settings_machine.SetNodeMem.encodeInto(&row_buf, .{ .node_id = 1, .ram_bytes = ram, .reserve = reserve });
    const row_entry = entry_mod.buildEntry(.settings_node_mem, entry_mod.Flags.NONE, r.current_term, r.last_applied + 1, 0, row_bytes);
    var out = persistence_mod.Result.start(&row_entry);
    try std.testing.expect(shard.applyEntry(&row_entry, &out));

    // A lagging replica: commit already names {1,2}, but only {1} has applied.
    // Deriving over the committed set would call the budget provisional for the
    // unreported node 2; deriving over the applied set (the fix) does not.
    r.applied_config = membership.Config.ofVoters(&.{1});
    r.committed_config = membership.Config.ofVoters(&.{ 1, 2 });
    shard.refreshBudgetOnBoot();

    try std.testing.expectEqual(@as(?u32, null), shard.budget.provisional_node);
    try std.testing.expectEqual(@as(?u32, 1), shard.budget.governing_node);
    try std.testing.expectEqual((ram - reserve) * 700 / 1000, shard.budget.budget_bytes);
}

test "memory budget: the leader proposes once and nothing while a proposal is in flight" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    try std.testing.expect(r.role == .leader);

    // No policy row yet: the first call appends the genesis share and marks it in flight.
    const base = r.log.lastIndex();
    shard.proposeBudgetRows();
    try std.testing.expect(shard.budget_propose_pending != null);
    try std.testing.expectEqual(base + 1, r.log.lastIndex());

    // While it hasn't applied, a second call proposes nothing — no pile-up.
    shard.proposeBudgetRows();
    try std.testing.expectEqual(base + 1, r.log.lastIndex());

    // Once it applies, the marker clears and the next call proposes this node's row.
    _ = shard.applyCommitted();
    shard.proposeBudgetRows();
    try std.testing.expectEqual(base + 2, r.log.lastIndex());
}

test "memory budget: the leader deletes a row whose node left the membership" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    try std.testing.expect(r.role == .leader);

    // The policy, and a row for node 2 — proposed into the log and applied, so
    // the log and store stay in step with the leader's own proposals.
    var share_buf: [settings_machine.SetShare.max_size]u8 = undefined;
    const share_bytes = try settings_machine.SetShare.encodeInto(&share_buf, .{ .share_permille = 700 });
    _ = try r.propose(.settings_pool_share, entry_mod.Flags.NONE, share_bytes);
    var row_buf: [settings_machine.SetNodeMem.max_size]u8 = undefined;
    const row_bytes = try settings_machine.SetNodeMem.encodeInto(&row_buf, .{ .node_id = 2, .ram_bytes = 2 * 1024 * 1024 * 1024, .reserve = 100 * 1024 * 1024 });
    _ = try r.propose(.settings_node_mem, entry_mod.Flags.NONE, row_bytes);
    _ = shard.applyCommitted();

    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var kb: [1 + 4]u8 = undefined;
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 2)) catch null) != null); // node 2's row is there

    // The applied membership no longer names node 2: the leader proposes a
    // delete for its row, and applying it removes the row.
    r.applied_config = membership.Config.ofVoters(&.{1});
    const before = r.log.lastIndex();
    shard.proposeBudgetRows();
    try std.testing.expectEqual(before + 1, r.log.lastIndex());
    _ = shard.applyCommitted();

    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 2)) catch null) == null); // and gone
}

test "memory budget: the leader proposes a committed data-holder's row from its advertised figure, not a joiner's" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    try std.testing.expect(r.role == .leader);

    // A real host figure booted the node (detect, not the fallback), so its own
    // budget is positive — the refuse-to-start path did not fire.
    try std.testing.expect(shard.self_ram_bytes > shard.self_reserve_bytes);

    // Node 2 is a committed data-holder and has advertised its figure; node 3 is
    // only a joiner in the latest config (its add hasn't committed) and has also
    // advertised. advertisedMem answers only for the committed config.
    const settled = membership.Config.ofVoters(&.{ 1, 2 });
    r.applied_config = settled;
    r.committed_config = settled;
    r.latest_config = membership.Config.ofVoters(&.{ 1, 2 }).withJoiner(3, true);
    const adv2: memory_budget.Holder.NodeMem = .{ .ram_bytes = 3 * 1024 * 1024 * 1024, .reserve = 120 * 1024 * 1024 };
    const adv3: memory_budget.Holder.NodeMem = .{ .ram_bytes = 2 * 1024 * 1024 * 1024, .reserve = 100 * 1024 * 1024 };
    shard.peer_mem[0] = .{ .id = 2, .mem = adv2 };
    shard.peer_mem[1] = .{ .id = 3, .mem = adv3 };

    // Drive the leader to steady state: genesis share, own row, then node 2's.
    var i: usize = 0;
    while (i < 8) : (i += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }

    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var kb: [1 + 4]u8 = undefined;
    // Node 2's row carries exactly what it advertised.
    const row2 = (read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 2)) catch null) orelse return error.NoRowForCommittedMember;
    try std.testing.expectEqual(adv2.ram_bytes, row2.v.ram_bytes);
    try std.testing.expectEqual(adv2.reserve, row2.v.reserve);
    // The joiner earns no row until its add commits, though it advertised.
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 3)) catch null) == null);
}

test "memory budget: advertisedMem's committed check alone gates a row — an applied-but-uncommitted node earns none" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    try std.testing.expect(r.role == .leader);

    // Node 3 is in the applied config — so the propose loop reaches it and the
    // data-holder filter admits it — but NOT in the committed config, and it has
    // advertised. ONLY advertisedMem's committed check keeps it from a row:
    // delete that check and this test fails (node 3 would get a row).
    r.applied_config = membership.Config.ofVoters(&.{ 1, 2, 3 });
    r.committed_config = membership.Config.ofVoters(&.{ 1, 2 });
    const adv: memory_budget.Holder.NodeMem = .{ .ram_bytes = 2 * 1024 * 1024 * 1024, .reserve = 100 * 1024 * 1024 };
    shard.peer_mem[0] = .{ .id = 2, .mem = adv };
    shard.peer_mem[1] = .{ .id = 3, .mem = adv };

    var i: usize = 0;
    while (i < 8) : (i += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }
    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var kb: [1 + 4]u8 = undefined;
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 2)) catch null) != null); // committed member got a row
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 3)) catch null) == null); // uncommitted did not

    // Steady: another pass proposes nothing — node 3 is skipped, and the budget
    // is provisional on its missing row, so even the clean record isn't written.
    try std.testing.expect(shard.budget_propose_pending == null);
    const idx = r.log.lastIndex();
    shard.proposeBudgetRows();
    try std.testing.expectEqual(idx, r.log.lastIndex());
}

test "memory budget: two data-holders report and the smaller governs; removing one drops its row for good" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    try std.testing.expect(r.role == .leader);
    // Fix this node's own figure so it is clearly the largest, whatever the host.
    shard.self_ram_bytes = 64 * 1024 * 1024 * 1024;

    // Nodes 2 and 3 are committed data-holders that have reported; node 3 is the
    // smaller after its reserve, so it governs the budget.
    const cfg3 = membership.Config.ofVoters(&.{ 1, 2, 3 });
    r.applied_config = cfg3;
    r.committed_config = cfg3;
    const big: memory_budget.Holder.NodeMem = .{ .ram_bytes = 4 * 1024 * 1024 * 1024, .reserve = 100 * 1024 * 1024 };
    const small: memory_budget.Holder.NodeMem = .{ .ram_bytes = 1 * 1024 * 1024 * 1024, .reserve = 100 * 1024 * 1024 };
    shard.peer_mem[0] = .{ .id = 2, .mem = big };
    shard.peer_mem[1] = .{ .id = 3, .mem = small };

    var i: usize = 0;
    while (i < 12) : (i += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }
    // All three reported: the budget is no longer provisional and node 3 governs.
    try std.testing.expectEqual(@as(?u32, null), shard.budget.provisional_node);
    try std.testing.expectEqual(@as(?u32, 3), shard.budget.governing_node);
    try std.testing.expectEqual((small.ram_bytes - small.reserve) * memory_budget.DEFAULT_SHARE_PERMILLE / 1000, shard.budget.budget_bytes);

    // Remove node 3: its row is deleted, node 2 governs, and node 3 is not re-proposed.
    const cfg2 = membership.Config.ofVoters(&.{ 1, 2 });
    r.applied_config = cfg2;
    r.committed_config = cfg2;
    i = 0;
    while (i < 12) : (i += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }
    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var kb: [1 + 4]u8 = undefined;
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 3)) catch null) == null); // gone
    try std.testing.expectEqual(@as(?u32, 2), shard.budget.governing_node); // node 2 now governs
    shard.proposeBudgetRows(); // and stays gone — not re-proposed
    try std.testing.expect((read.get(settings_machine.NodeFam, settings_machine.nodeKey(&kb, 3)) catch null) == null);
}

test "memory budget: refuse to start when RAM leaves no budget, or no real figure was read" {
    const reserve: u64 = 200 * 1024 * 1024;
    // A real figure with room to spare: may start.
    try std.testing.expect(Shard.startupRefusal(2 * 1024 * 1024 * 1024, false, reserve) == null);
    // RAM at or below the reserve: refuse — no budget would be left.
    try std.testing.expect(Shard.startupRefusal(reserve, false, reserve) != null);
    try std.testing.expect(Shard.startupRefusal(reserve - 1, false, reserve) != null);
    // Only the assumed fallback could be read: refuse even though 8 GiB > reserve.
    try std.testing.expect(Shard.startupRefusal(8 * 1024 * 1024 * 1024, true, reserve) != null);
    // A real figure read through a non-cgroup path (sysctl/meminfo on a dev host): boots.
    try std.testing.expect(Shard.startupRefusal(16 * 1024 * 1024 * 1024, false, reserve) == null);
}

test "memory budget: the leader records the clean budget once it has moved, and not again" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    try std.testing.expect(shard.raft_node.role == .leader);
    var slots = [_]health_mod.ShardSlot{.{}};
    shard.node_health = &slots;

    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var bk: [1 + settings_machine.BUDGET_KEY.len]u8 = undefined;
    const bkey = try contract_view.key(&bk, "", settings_machine.BUDGET_KEY);

    // The leader settles the genesis share and its own row, then records the
    // clean budget; each proposal applies at once on a single node.
    var guard: usize = 0;
    while ((read.get(settings_machine.BudgetFam, bkey) catch null) == null and guard < 8) : (guard += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }
    const rec = (read.get(settings_machine.BudgetFam, bkey) catch null) orelse return error.TestNoCleanRecord;
    try std.testing.expect(shard.budget.seen);
    try std.testing.expectEqual(shard.budget.budget_bytes, rec.v.budget_bytes); // the record is the derived budget
    try std.testing.expectEqual(@as(u32, 1), rec.v.governing_node); // node 1 governs, and names itself
    // Published for every shard's leader to bind from.
    try std.testing.expectEqual(rec.v.budget_bytes, slots[0].clean_budget_bytes.load(.acquire));

    // Steady state: the record matches the budget, so nothing more is proposed.
    const before = shard.raft_node.log.lastIndex();
    shard.proposeBudgetRows();
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());
}

test "memory budget: a node that restarts mid-freeze shows the same budget as one that stayed up" {
    // The window the review named: a clean budget is recorded (X), a clean
    // change derives a new value (Y) the leader hasn't recorded yet, and then a
    // join freezes the budget. A node that stayed up must not keep showing its
    // in-memory Y while a restarted node — which only has the committed record —
    // shows X. Both show the record, so the budget is a pure function of the log.
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var bk: [1 + settings_machine.BUDGET_KEY.len]u8 = undefined;
    const bkey = try contract_view.key(&bk, "", settings_machine.BUDGET_KEY);

    // Drive everything through the leader's own proposer with a controlled RAM.
    const reserve: u64 = 100 * 1024 * 1024;
    shard.self_reserve_bytes = reserve;
    shard.self_ram_bytes = 2 * 1024 * 1024 * 1024; // R1
    const x: u64 = (shard.self_ram_bytes - reserve) * 700 / 1000;

    // Settle the share and node 1's row, and record the clean budget X.
    var guard: usize = 0;
    while ((read.get(settings_machine.BudgetFam, bkey) catch null) == null and guard < 8) : (guard += 1) {
        shard.proposeBudgetRows();
        _ = shard.applyCommitted();
    }
    const rec_x = (read.get(settings_machine.BudgetFam, bkey) catch null) orelse return error.TestNoCleanRecord;
    try std.testing.expectEqual(x, rec_x.v.budget_bytes);

    // A clean change: node 1's RAM grows to R2, so the budget derives Y. Propose
    // just the row (one entry per call) and apply it — the leader has NOT recorded
    // Y, so the committed record still says X.
    shard.self_ram_bytes = 4 * 1024 * 1024 * 1024; // R2
    const y: u64 = (shard.self_ram_bytes - reserve) * 700 / 1000;
    shard.proposeBudgetRows();
    _ = shard.applyCommitted();
    try std.testing.expectEqual(y, shard.budget.budget_bytes); // the node that stays up derived Y
    const rec_still = (read.get(settings_machine.BudgetFam, bkey) catch null) orelse return error.TestNoCleanRecord;
    try std.testing.expectEqual(x, rec_still.v.budget_bytes); // record still X

    // A join freezes the budget before Y is recorded.
    r.applied_config = membership.Config.ofVoters(&.{ 1, 2 });
    shard.refreshBudget();
    const stayed_up = shard.budget.budget_bytes;
    try std.testing.expectEqual(@as(?u32, 2), shard.budget.provisional_node);
    try std.testing.expectEqual(x, stayed_up); // not the unrecorded Y
    try std.testing.expect(stayed_up != y);

    // A node restarting here boots from the same committed state: a fresh
    // Observation, then the boot-time derive. It shows the record too.
    shard.budget = .{};
    shard.refreshBudgetOnBoot();
    try std.testing.expectEqual(stayed_up, shard.budget.budget_bytes); // they agree across the restart
    try std.testing.expectEqual(x, shard.budget.budget_bytes);
    try std.testing.expectEqual(@as(?u32, 2), shard.budget.provisional_node);
}

test "memory budget: the leader records no clean budget while it is provisional" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;
    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    var bk: [1 + settings_machine.BUDGET_KEY.len]u8 = undefined;
    const bkey = try contract_view.key(&bk, "", settings_machine.BUDGET_KEY);

    // Settle the share and node 1's row, but FREEZE before the clean budget is
    // recorded: the first two proposer calls append the share and the row; the
    // third would record the budget. Stop after two and freeze, so no record
    // exists yet and the budget is derived clean (`seen`) but then shows 0.
    shard.proposeBudgetRows(); // share
    _ = shard.applyCommitted();
    shard.proposeBudgetRows(); // node 1's row
    _ = shard.applyCommitted();
    try std.testing.expect(shard.budget.seen);
    try std.testing.expect((read.get(settings_machine.BudgetFam, bkey) catch null) == null); // nothing recorded yet

    // A join freezes the budget with no record to show: the shown value is 0.
    r.applied_config = membership.Config.ofVoters(&.{ 1, 2 });
    shard.refreshBudget();
    try std.testing.expectEqual(@as(?u32, 2), shard.budget.provisional_node);
    try std.testing.expectEqual(@as(u64, 0), shard.budget.budget_bytes);

    // The provisional gate is what stops a record here: without it the leader
    // would record {0, 0} off the held-at-0 budget. Nothing is proposed, and no
    // record is written.
    const before = r.log.lastIndex();
    shard.proposeBudgetRows();
    try std.testing.expectEqual(before, r.log.lastIndex());
    try std.testing.expect((read.get(settings_machine.BudgetFam, bkey) catch null) == null);
}

test "memory budget: a shard's leader binds its share from shard 0's clean budget, once, and again when it moves" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 1, 4, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    var slots = [_]health_mod.ShardSlot{ .{}, .{}, .{}, .{} };
    shard.node_health = &slots;
    const read: contract_view.ReadView = .{ .store = &shard.defaultPartition().store };
    const log_ = &shard.raft_node.log;

    // Nothing published: nothing bound, nothing proposed.
    var before = log_.lastIndex();
    shard.proposeBudgetBind();
    try std.testing.expectEqual(before, log_.lastIndex());
    try std.testing.expect(settings_machine.boundShare(read) == null);

    // A budget too small to share among the four shards binds nothing.
    slots[0].clean_budget_bytes.store(3, .release);
    shard.proposeBudgetBind();
    try std.testing.expectEqual(before, log_.lastIndex());

    // Shard 0's clean budget: the share is a quarter of it, and binds once.
    slots[0].clean_budget_bytes.store(4000, .release);
    shard.proposeBudgetBind();
    _ = shard.applyCommitted();
    const b = settings_machine.boundShare(read) orelse return error.TestNotBound;
    try std.testing.expectEqual(@as(u64, 1000), b.share_bytes);
    try std.testing.expectEqual(@as(u64, 4000), b.budget_bytes);
    before = log_.lastIndex();
    shard.proposeBudgetBind();
    try std.testing.expectEqual(before, log_.lastIndex());

    // A lowered budget re-binds.
    slots[0].clean_budget_bytes.store(2000, .release);
    shard.proposeBudgetBind();
    _ = shard.applyCommitted();
    try std.testing.expectEqual(@as(u64, 500), settings_machine.boundShare(read).?.share_bytes);
}

test "settings: a bind of a 0 share is refused at apply, binding nothing" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    _ = shard.applyCommitted();
    const r = shard.raft_node;

    var buf: [settings_machine.SetBudgetBind.max_size]u8 = undefined;
    const bytes = try settings_machine.SetBudgetBind.encodeInto(&buf, .{ .share_bytes = 0, .budget_bytes = 0 });
    const e = entry_mod.buildEntry(.settings_budget_bind, entry_mod.Flags.NONE, r.current_term, r.last_applied + 1, 0, bytes);
    var out = persistence_mod.Result.start(&e);
    _ = shard.applyEntry(&e, &out);
    try std.testing.expect(out.refused() != null);
    try std.testing.expect(settings_machine.boundShare(.{ .store = &shard.defaultPartition().store }) == null);
