    try std.testing.expectEqual(@as(u64, 5), resp.header.request_id);
    try std.testing.expect(std.mem.indexOf(u8, resp.data, "electing a leader") != null);
}

test "Shard: a poll arm that keeps failing closes the connection instead of leaving it hung" {
    // The arm failure is injected at the io_uring poll level, so this runs on
    // Linux only; the kqueue path has no such re-arm hazard.
    if (builtin.target.os.tag == .linux) {
        const pipe_fds = try @import("stdx").io.pipe();
        defer _ = std.c.close(pipe_fds[0]);
        defer _ = std.c.close(pipe_fds[1]);
        var rn = try RaftNetwork.init(std.testing.allocator, 8, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        defer rn.deinit();
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
        defer shard.deinit();
        shard.raft_network = &rn;

        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);
        try shard.reactor.addSource(.{ .fd = conn.fd, .tag = .client_read, .interests = .{ .readable = true } });

        // Pausing reads arms a reactor interest change. With the arm forced to
        // fail the way a wedged ring would, the shard closes the connection
        // rather than swallow the error and leave the fd un-armed, so the client
        // reconnects instead of hanging.
        shard.reactor.test_arm_error = error.SubmissionQueueFull;
        shard.pauseReads(conn.fd, conn);
        try std.testing.expect(conn.closing);
        try std.testing.expectEqual(@as(u64, 1), shard.arm_failures);

        // Resuming reads arms the same interest change and must close the same
        // way if it fails. The failed pause left the interest unchanged, so move
        // it to the paused state (no injected failure) first, giving resumeReads
        // a real change to make; then fail that arm and clear the earlier mark so
        // the close is attributable here.
        conn.closing = false;
        try shard.reactor.modifyInterests(conn.fd, .{ .readable = false, .writable = true });
        shard.reactor.test_arm_error = error.SubmissionQueueFull;
        shard.resumeReads(conn.fd, conn);
        try std.testing.expect(conn.closing);
        try std.testing.expectEqual(@as(u64, 2), shard.arm_failures);
    } else return error.SkipZigTest;
}

test "Shard: closeConnection on an fd with no connection is a no-op, not a close of a possibly-reused fd" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
    defer shard.deinit();

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[0]);
    defer _ = std.c.close(pair[1]);

    // No connection was ever registered for pair[0]; a stale or duplicate close
    // must leave the fd alone (closing it could hit a client that reused the
    // number). It stays open, so a write still succeeds.
    shard.closeConnection(pair[0]);
    try std.testing.expectEqual(@as(isize, 1), std.c.write(pair[0], "x", 1));
}

test "Shard: a node with a stale config takes a promoted voter's append and vote request, and drops only a write it would forward" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 3, .join, .{}, .{});
    defer shard.deinit();
    const raft = shard.raft_node;
    // Its latest config: 1 votes, 2 and 3 are replicas. 1 has since made 2
    // a voter and died before 3 heard.
    const stale = membership.Config.ofVoters(&.{1}).withJoiner(2, true).withJoiner(3, true);
    raft.setMembership(&stale, 1);
    raft.lost_log = .none;
    const term0 = raft.current_term;

    var vbuf: [transport.VOTE_REQ_SIZE]u8 = undefined;
    const vn = transport.serializeVoteRequest(.{ .term = term0 + 5, .candidate_id = 2, .last_log_index = 10, .last_log_term = term0 + 4 }, &vbuf).?;
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .request_vote, .payload = vbuf[0..vn] });
    try std.testing.expectEqual(term0 + 5, raft.current_term);
    try std.testing.expectEqual(@as(u32, 2), raft.voted_for);

    var buf: [transport.APPEND_REQ_PREFIX + 64]u8 = undefined;
    const n = transport.serializeAppendRequest(.{ .term = term0 + 6, .leader_id = 2, .prev_log_index = 0, .prev_log_term = 0, .leader_commit = 0, .entries = &.{} }, &buf).?;
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .append_entries, .payload = buf[0..n] });
    try std.testing.expectEqual(term0 + 6, raft.current_term);
    try std.testing.expectEqual(@as(u32, 2), raft.leader_id);

    // A write a replica would carry to the leader is not its to carry.
    try std.testing.expectEqual(@as(u64, 0), shard.replica.replica_frame_warn_ms);
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .forward_write, .payload = &.{} });
    try std.testing.expect(shard.replica.replica_frame_warn_ms != 0);
}

test "Shard: node_mem from a member is stored and read back; a stranger's is dropped" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 4, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 3, .join, .{}, .{});
    defer shard.deinit();
    const raft = shard.raft_node;
    // 1 votes; 2 and 3 are replicas — data-holders that must report their memory.
    const config = membership.Config.ofVoters(&.{1}).withJoiner(2, true).withJoiner(3, true);
    raft.setMembership(&config, 1);
    raft.commitMembership(&config, 1);
    raft.lost_log = .none;

    const ram: u64 = 2 * 1024 * 1024 * 1024;
    const reserve: u64 = 100 * 1024 * 1024;
    var buf: [NODE_MEM_SIZE]u8 = undefined;
    std.mem.writeInt(u64, buf[0..8], ram, .little);
    std.mem.writeInt(u64, buf[8..16], reserve, .little);

    // A member's figures are kept and read back by node id.
    try std.testing.expect(shard.advertisedMem(2) == null);
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .node_mem, .payload = &buf });
    const got = shard.advertisedMem(2) orelse return error.NoFigures;
    try std.testing.expectEqual(ram, got.ram_bytes);
    try std.testing.expectEqual(reserve, got.reserve);

    // A stranger's figures are dropped by the membership filter, never stored.
    shard.replica.handleRaftFrame(.{ .source_node = 9, .group_id = 0, .msg_type = .node_mem, .payload = &buf });
    try std.testing.expect(shard.advertisedMem(9) == null);

    // A later advertisement from the same member replaces the earlier one.
    std.mem.writeInt(u64, buf[0..8], ram * 2, .little);
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .node_mem, .payload = &buf });
    const got2 = shard.advertisedMem(2) orelse return error.NoFigures;
    try std.testing.expectEqual(ram * 2, got2.ram_bytes);

    // A malformed (short) frame is rejected, leaving the stored figure intact.
    shard.replica.handleRaftFrame(.{ .source_node = 2, .group_id = 0, .msg_type = .node_mem, .payload = buf[0..8] });
    const got3 = shard.advertisedMem(2) orelse return error.NoFigures;
    try std.testing.expectEqual(ram * 2, got3.ram_bytes);

    // Node 3 advertises too; then 2 leaves the config. A membership change
    // forgets a departed node's figure but keeps one the config still names.
    shard.replica.handleRaftFrame(.{ .source_node = 3, .group_id = 0, .msg_type = .node_mem, .payload = &buf });
    try std.testing.expect(shard.advertisedMem(3) != null);
    const shrunk = membership.Config.ofVoters(&.{1}).withJoiner(3, true);
    raft.setMembership(&shrunk, 2);
    raft.commitMembership(&shrunk, 2);
    shard.forgetDepartedPeers();
    try std.testing.expect(shard.advertisedMem(2) == null);
    try std.testing.expect(shard.advertisedMem(3) != null);

    // A node that couldn't read its RAM sends 0: dropped, the figure kept.
    std.mem.writeInt(u64, buf[0..8], 0, .little);
    shard.replica.handleRaftFrame(.{ .source_node = 3, .group_id = 0, .msg_type = .node_mem, .payload = &buf });
    try std.testing.expectEqual(ram * 2, (shard.advertisedMem(3) orelse return error.NoFigures).ram_bytes);
}

test "Shard: node_mem from a node before this one knows a config is not kept" {
