/// A name, `prefix` and a number, that namespace `ns` puts on shard `want`.
fn nameOn(shard: *Shard, ns: ns_table.Id, want: u16, prefix: []const u8, buf: []u8) ![]const u8 {
    var i: usize = 0;
    while (true) : (i += 1) {
        const k = try std.fmt.bufPrint(buf, "{s}{d}", .{ prefix, i });
        if (shard.router.hashToShard(node_router.routeNsKey(ns, k)) == want) return k;
    }
}

/// A key that namespace `ns` puts on shard `want` of `shard`'s node.
fn keyOn(shard: *Shard, ns: ns_table.Id, want: u16, buf: []u8) ![]const u8 {
    var i: usize = 0;
    while (true) : (i += 1) {
        const k = try std.fmt.bufPrint(buf, "k{d}", .{i});
        if (shard.router.hashToShard(node_router.routeNsKey(ns, k)) == want) return k;
    }
}

/// The id shard 0 gives the next namespace it creates: a write to a new
/// namespace is routed by it once the create is published.
fn nextNamespaceId(shard0: *const Shard) ns_table.Id {
    const nh = shard0.namespace_handler;
    return .of(@max(nh.nextId(), nh.next_alloc, nh.id_floor));
}

/// The log index of the first `t` entry in `shard`'s log at or after `from`, or null.
fn entryAt(shard: *Shard, t: entry_mod.EntryType, from: u64) ?u64 {
    var i = from;
    while (i <= shard.raft_node.log.lastIndex()) : (i += 1) {
        if (shard.raft_node.log.getEntry(i)) |e| if (e.header.entry_type == @backingInt(t)) return i;
    }
    return null;
}

/// The records stream `name` in namespace `ns` holds on `s`.
/// The last payload of stream `name`, copied into `buf`, or null.
fn lastStreamPayload(s: *Shard, name: []const u8, ns: []const u8, buf: []u8) ?[]const u8 {
    var got: ?[]const u8 = null;
    var after: @import("../projection/stream.zig").StreamID = .{ .timestamp_ms = 0, .sequence = 0 };
    while (true) {
        const r = s.stream_handler.readPayloadsForStream(name, ns, after, 1000);
        defer r.deinit(s.stream_handler.allocator);
        if (r.payloads.len == 0) return got;
        const p = r.payloads[r.payloads.len - 1];
        if (p.len > buf.len) return null;
        @memcpy(buf[0..p.len], p);
        got = buf[0..p.len];
        after = r.last_id;
    }
}

fn streamRecords(s: *Shard, name: []const u8, ns: []const u8) usize {
    var n: usize = 0;
    var after: @import("../projection/stream.zig").StreamID = .{ .timestamp_ms = 0, .sequence = 0 };
    while (true) {
        const r = s.stream_handler.readPayloadsForStream(name, ns, after, 1000);
        defer r.deinit(s.stream_handler.allocator);
        if (r.payloads.len == 0) return n;
        n += r.payloads.len;
        after = r.last_id;
    }
}

fn entriesOf(shard: *Shard, t: entry_mod.EntryType, from: u64) usize {
    var n: usize = 0;
    var i = from;
    while (i <= shard.raft_node.log.lastIndex()) : (i += 1) {
        if (shard.raft_node.log.getEntry(i)) |e| if (e.header.entry_type == @backingInt(t)) {
            n += 1;
        };
    }
    return n;
}

test "Shard: a client request that names the reserved _flo namespace is refused at the edge, every op family" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    var out: [512]u8 = undefined;

    // "_flo" is the system's namespace — its name in the table (namespace/table.zig).
    // A client that addresses it by name is refused at the shared request edge
    // (runRequest's nameRefusal), before any handler runs, so the refusal holds
    // for every op whatever it would do. A silently dropped edge check is Flo's
    // usual bug shape, so this pins one op per family — reads and writes.
    const before = shard.raft_node.log.lastIndex();
    const op_families = [_]proto.OpCode{ .kv_put, .kv_get, .stream_append, .stream_read, .queue_enqueue, .ts_write, .workflow_create };
    for (op_families, 0..) |op, i| {
        const id: u64 = 40 + i;
        shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(op, id), .namespace = "_flo", .key = "k", .value = "v" }, .client);
        const r = try nextAnswer(c, &shard, &out);
        try std.testing.expectEqual(id, r.header.request_id);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), r.header.status);
        try std.testing.expect(std.mem.indexOf(u8, (try r.refused()).message, "reserved namespace name") != null);
    }
    // Refused at the edge: not one of them reached the log.
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());

    // The same edge admits the default namespace, so this pins the reserved-name
    // refusal and not a blanket one: a write to "default" is accepted and applied.
    shard.runRequest(c.conn, testReq(.kv_put, 99, "", "k", "v", ""), .client);
    _ = shard.applyCommitted();
    const ok = try nextAnswer(c, &shard, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), ok.header.status);
}

