}

// Only while the find has room: held for it instead, the start's entry goes
// with the ensure, and on resume a later request's own find may go first,
// as for a namespace that exists.
test "Shard: a chosen-id start into a namespace shard 0 is making keeps its connection's later requests behind it through the find it starts, given room" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const b = &two.shards[1];
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    // [ver_len:u16][ver][has_idem:u8][key_len:u16][key][has_rid:u8][rid_len:u16][rid][input]
    const start = "\x03\x001.0" ++ "\x01\x02\x00ik" ++ "\x01\x09\x00order-123" ++ "{}";
    const frames = try pipeline(&.{
        try ParkTest.request(.workflow_start, 1, "fresh", "wf", start, ""),
        try ParkTest.request(.kv_put, 2, "fresh", "k", "v", ""),
    });
    defer std.testing.allocator.free(frames);
    _ = feedClient(c.pair[1], b, c.conn.fd, frames);
    try std.testing.expectEqual(@as(?Connection.WaitReason, .namespace_ask), if (c.conn.waiting) |w| w.reason else null);
    shard0Answers(&two, b);
    // The start runs again, now finding which shard holds its run: the put
    // still waits behind it.
    _ = b.drainInbox();
    try std.testing.expectEqual(@as(usize, 1), b.gathers.inUse());
    try std.testing.expectEqual(@as(u8, 1), c.conn.ns_ask_count);
    b.settleConnections();
    try std.testing.expect(c.conn.waiting != null);
    for (0..8) |_| {
        two.settle();
        b.settleConnections();
    }
    var out: [2048]u8 = undefined;
    var answers: [2]proto.Response = undefined;
    try ParkTest.responses(b, c.conn, c.pair[1], &out, &answers);
    for (answers, 1..) |r, id| try std.testing.expectEqual(@as(u64, id), r.header.request_id);
    try std.testing.expectEqual(@as(u8, 0), c.conn.ns_ask_count);
}

test "Shard: a read across shards a request running again starts gives its parts the deadline of when its client sent it" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    c.conn.head_since_ms = null;
    const now = Shard.nowMs();
    var body: [64]u8 = undefined;
    const req = edgeGet(&body, 7, "unknown", "k");
    b.reentry = Shard.Reentry.of(c.conn, 7, now -| reply_pool_mod.DEADLINE_MS, .client, .rerun);
    b.askShard0(c.conn, req, "unknown", .client);
    b.reentry = null;
    var due: ?u64 = null;
    for (b.reply_pool.slots) |slot| if (slot.active and slot.request_id == 7) {
        due = slot.answer_due_ms;
    };
    // Counted from when it was sent, it is due as soon as a part may be.
    try std.testing.expect(due.? < now + reply_pool_mod.DEADLINE_MS);
    two.settle();
}

test "Shard: a client request refused before it goes to another shard says whether its share there was spent or that shard's ring was full" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const a = &two.shards[0];
    const b = &two.shards[1];
    var sm = ShardMetrics{ .shard_id = 1 };
    b.shard_metrics = &sm;
    defer b.shard_metrics = null;
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    var kbuf: [16]u8 = undefined;
    const k = try keyOn(b, .default, 0, &kbuf);
    // Its share spent: share_spent.
    spendShare(a, 1);
    b.forwardToShard(0, c.conn, try ParkTest.request(.kv_put, 1, proto.DEFAULT_NAMESPACE, k, "v", ""), run_mod.authorize(.anonymous, .client, try ParkTest.request(.kv_put, 1, proto.DEFAULT_NAMESPACE, k, "v", "")).ok);
    try std.testing.expectEqual(@as(u64, 1), sm.forward_refused[@backingInt(ShardMetrics.ForwardRefused.share_spent)].load(.monotonic));
    while (a.drainInbox() > 0) {}
    // Its share free, the ring full of what is sent on none: ring_full.
    while (a.mailbox.inbox.send(.{ .tag = .worker_report })) {}
    b.forwardToShard(0, c.conn, try ParkTest.request(.kv_put, 2, proto.DEFAULT_NAMESPACE, k, "v", ""), run_mod.authorize(.anonymous, .client, try ParkTest.request(.kv_put, 2, proto.DEFAULT_NAMESPACE, k, "v", "")).ok);
    try std.testing.expectEqual(@as(u64, 1), sm.forward_refused[@backingInt(ShardMetrics.ForwardRefused.ring_full)].load(.monotonic));
    try std.testing.expectEqual(@as(u64, 1), sm.forward_refused[@backingInt(ShardMetrics.ForwardRefused.share_spent)].load(.monotonic));
    while (a.drainInbox() > 0) {}
}

test "Shard: a write on shard 1 to a namespace nobody created is answered once, and shard 1 logs only the write" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    var kbuf: [16]u8 = undefined;
    const k = try keyOn(b, nextNamespaceId(&two.shards[0]), 1, &kbuf);
    const from = b.raft_node.log.lastIndex() + 1;
    b.runRequest(c.conn, try ParkTest.request(.kv_put, 7, "fresh", k, "v", ""), .client);
    two.settle();
    var out: [512]u8 = undefined;
    const resp = try nextAnswer(c, b, &out);
    try std.testing.expectEqual(@as(u64, 7), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    // Shard 0 created it and the node's table has it; shard 1 logged the
    // write alone, under the table's id, and keeps no name of its own.
    const id = two.namespaces.lookup("fresh").?;
    try std.testing.expect(two.shards[0].namespace_handler.known("fresh"));
    try std.testing.expect(!b.namespace_handler.known("fresh"));
    try std.testing.expectEqual(from, entryAt(b, .kv_put, from).?);
    try std.testing.expectEqual(b.raft_node.log.lastIndex(), from);
    try std.testing.expectEqual(id.int(), highestNamespaceIn(&b.defaultPartition().store));
    // Answered once: nothing more on the socket, no slot or gather left.
    try std.testing.expectError(error.IncompleteResponse, nextAnswer(c, b, &out));
    try std.testing.expectEqual(@as(usize, 0), b.gathers.inUse());
    try std.testing.expectEqual(@as(usize, 0), b.reply_pool.taken());
}

