test "Shard: a submit into a namespace it creates is homed on its source's shard by the namespace's real id, from either shard" {
    for ([_]u16{ 0, 1 }) |edge| {
        var two: TwoShards = undefined;
        try two.init();
        defer two.deinit();
        const a = &two.shards[0];
        for (&two.shards) |*s| s.wireHandlerShardPtrs();
        // A source that an unresolved id would put on the edge's shard and
        // the namespace's real id puts on the other: homed before the id
        // resolves, the job would land on the wrong shard.
        const id = nextNamespaceId(a);
        const home: u16 = 1 - edge;
        var sbuf: [16]u8 = undefined;
        var i: usize = 0;
        const source = while (true) : (i += 1) {
            const n = try std.fmt.bufPrint(&sbuf, "src{d}", .{i});
            if (a.router.hashToShard(node_router.routeNsKey(.invalid, n)) == edge and a.router.hashToShard(node_router.routeNsKey(id, n)) == home) break n;
        };
        const at = &two.shards[edge];
        const c = try TestClient.open(at);
        defer _ = std.c.close(c.pair[1]);
        var ybuf: [256]u8 = undefined;
        const yaml = try std.fmt.bufPrint(&ybuf,
            \\kind: Processing
            \\name: fresh-job
            \\namespace: fresh
            \\sources:
            \\  - name: src
            \\    stream: {{ name: {s} }}
            \\sinks:
            \\  - name: out
            \\    stream: {{ name: out }}
        , .{source});
        // The namespace's create and the submit go in together; nothing has
        // applied either when the submit routes.
        at.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "fresh", "", yaml, ""), .client);
        two.settle();
        try std.testing.expectEqual(id, two.namespaces.lookup("fresh").?);
        try std.testing.expectEqual(@as(usize, 0), two.shards[edge].processing_handler.jobCount());
        try std.testing.expectEqual(@as(usize, 1), two.shards[home].processing_handler.jobCount());
        // Its id carries the slot its source's stream ops route by.
        const job = two.shards[home].processing_handler.firstJob().?;
        try std.testing.expectEqual(node_router.slot(node_router.routeNsKey(id, source)), run_id_mod.extractSlot(job.job_id_owned).?);
        try std.testing.expectEqual(ProcessingHandler.JobStatus.running, job.status);
    }
}

test "Shard: a processing sink in a namespace not yet published writes nothing until it is, then writes on the shard its id puts the stream on" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    // A sink stream that id 0 would put here and the namespace's real id
    // puts on shard 1: routed before the publish, it lands on the wrong shard.
    const id = nextNamespaceId(a);
    var tbuf: [16]u8 = undefined;
    var i: usize = 0;
    const target = while (true) : (i += 1) {
        const t = try std.fmt.bufPrint(&tbuf, "out{d}", .{i});
        const before = a.router.hashToShard(node_router.routeNsKey(.invalid, t));
        const after = a.router.hashToShard(node_router.routeNsKey(id, t));
        if (before == 0 and after == 1) break t;
    };
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "rec-1");
    two.settle();

    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [256]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: early
        \\namespace: pns
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s}, namespace: default }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ source, target });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "pns", "", yaml, ""), .client);
    // The create and the submit apply; shard 0 hasn't published yet.
    _ = a.applyCommitted();
    try std.testing.expect(two.namespaces.lookup("pns") == null);
    try std.testing.expectEqual(@as(u32, 1), a.processing_handler.jobCount());

    const from_a = a.raft_node.log.lastIndex() + 1;
    var metrics = MetricsRegistry.init(std.testing.allocator);
    defer metrics.deinit();
    a.setMetricsRegistry(&metrics);
    _ = a.processing_handler.tickPipelines(a);
    // Not published: the pipeline waits, and says why, and the node counts it.
    var it = a.processing_handler.pipelines.valueIterator();
    try std.testing.expectEqualStrings("pns", it.next().?.wait.namespace);
    // Waiting on a namespace not yet published: neither due nor timed, so
    // the loop sleeps its own wake, not a poll interval's.
    {
        const n = a.processing_handler.nextWork(a, a.processing_handler.nowMs() + 5_000);
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
    }
    try std.testing.expectEqual(@as(usize, 0), entriesOf(a, .processing_sink_batch, from_a));
    try std.testing.expectEqual(@as(u64, 1), metrics.processing.pipelines_waiting_namespace.load(.monotonic));
    // A node that stops leading says nothing of it, gauge included, and
    // keeps no pipelines: its next leader builds its own. Until they go,
    // a pipeline's wait is no longer its.
    a.raft_node.role = .follower;
    {
        var wit = a.processing_handler.pipelines.valueIterator();
        const waiting = wit.next().?;
        try std.testing.expect(waiting.held_since_ms != ProcessingHandler.NEVER_MS);
        _ = a.processing_handler.tickPipelines(a);
        try std.testing.expectEqual(ProcessingHandler.NEVER_MS, waiting.held_since_ms);
    }
    _ = try a.tick(0);
    try std.testing.expectEqual(@as(u32, 0), a.processing_handler.pipelines.count());
    try std.testing.expectEqual(@as(u64, 0), metrics.processing.pipelines_waiting_namespace.load(.monotonic));
    a.raft_node.role = .leader;
    two.settle();
    try std.testing.expectEqual(id, two.namespaces.lookup("pns").?);
    // Published: the next tick, not the next poll, writes it. The stream
    // is on shard 1, which applies the record its channel brings; nothing
    // lands here.
    _ = a.processing_handler.tickPipelines(a);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 0), entriesOf(a, .stream_append, from_a));
    try std.testing.expectEqual(@as(usize, 1), streamRecords(b, target, "pns"));
    try std.testing.expectEqual(@as(usize, 0), streamRecords(a, target, "pns"));
    try std.testing.expect(!a.processing_handler.firstJob().?.held);
    try std.testing.expectEqual(@as(u64, 0), a.processing_handler.sink_drops + b.processing_handler.sink_drops);
}

/// A job on shard 0 reading `records` from a stream there into queue
/// `queue` there, reading `batch` a tick; its one pipeline.
fn localQueueSinkJob(two: *TwoShards, c: TestClient, queue: []const u8, records: usize, batch: u32) !*ProcessingHandler.PipelineState {
    const a = &two.shards[0];
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for (0..records) |_| _ = try a.stream_handler.appendPayloadToStream(source, "default", "r");
    two.settle();
    var ybuf: [256]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: local
        \\batch_size: {d}
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\  - name: out
        \\    queue: {{ name: {s} }}
    , .{ batch, source, queue });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    return pit.next().?;
}

fn localQueue(a: *Shard, buf: []u8) ![]const u8 {
    var qi: usize = 0;
    while (true) : (qi += 1) {
        const q = try std.fmt.bufPrint(buf, "q{d}", .{qi});
        if (a.router.hashToShard(node_router.routeNsKey(.default, q)) == 0) return q;
    }
}

/// Points `measurement`/`field` holds in `ns` on `shard`, any tags.
fn tsPoints(shard: *Shard, ns: ns_table.Id, measurement: []const u8, field: []const u8) !usize {
    var buf: [16]@import("../projection/ts.zig").StoredPoint = undefined;
    return (try shard.ts_handler.ts.queryRange(ns, measurement, field, null, 0, std.math.maxInt(u64), &buf)).points_in_buffer;
}

test "Shard: a TS sink whose measurement is on another shard writes through that shard's log, not into its store" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var mbuf: [16]u8 = undefined;
    var mi: usize = 0;
    const measurement = while (true) : (mi += 1) {
        const m = try std.fmt.bufPrint(&mbuf, "m{d}", .{mi});
        if (a.router.hashToShard(node_router.routeNsKey(.default, m)) == 1) break m;
    };
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for ([_][]const u8{ "1.5", "2.5" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [256]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: tsfar
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\  - name: out
        \\    ts: {{ measurement: {s} }}
    , .{ source, measurement });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    const from_b = b.raft_node.log.lastIndex() + 1;
    const from_a = a.raft_node.log.lastIndex() + 1;
    var pit = a.processing_handler.pipelines.valueIterator();
    pit.next().?.last_poll_ms = ProcessingHandler.NEVER_MS;
    _ = a.processing_handler.tickPipelines(a);
    // Proposed, not yet applied anywhere: shard 1's store is untouched.
    try std.testing.expectEqual(@as(usize, 0), try tsPoints(b, .default, measurement, "value"));
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 0), entriesOf(a, .ts_write, from_a));
    try std.testing.expect(entriesOf(b, .channel_inbound, from_b) > 0);
    try std.testing.expectEqual(@as(usize, 2), try tsPoints(b, .default, measurement, "value"));
    try std.testing.expectEqual(@as(usize, 0), try tsPoints(a, .default, measurement, "value"));
