/// A point of `measurement`'s field "value", written to `shard` as a
/// client's write is and applied.
fn tsPut(shard: *Shard, measurement: []const u8, value: f64, ts_ns: u64, tags: []const u8) !void {
    switch (@import("../ts/handler.zig").TSHandler.proposeWrite(shard, "default", measurement, "value", value, ts_ns, tags, entry_mod.Flags.NONE)) {
        .parked => {},
        else => return error.NotProposed,
    }
    _ = shard.applyCommitted();
}

/// A job on shard 0 (its first source an empty stream there) whose second
/// source is `source` (a stream, or a measurement when `ts`) on another
/// shard, writing each record to stream `out`: the pipeline of `source`,
/// which reads it through that shard's inbox.
fn remoteSourceJob(two: *TwoShards, c: TestClient, source: []const u8, ts: bool, out: []const u8) !*ProcessingHandler.PipelineState {
    return remoteSourceJobLate(two, c, source, ts, out, 0);
}

/// `remoteSourceJob`, its TS source holding back `lateness_ms`.
fn remoteSourceJobLate(two: *TwoShards, c: TestClient, source: []const u8, ts: bool, out: []const u8, lateness_ms: u32) !*ProcessingHandler.PipelineState {
    const a = &two.shards[0];
    var hbuf: [16]u8 = undefined;
    const home = try keyOn(a, .default, 0, &hbuf);
    var ybuf: [640]u8 = undefined;
    const yaml = if (ts) try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: far-src
        \\sources:
        \\  - name: home
        \\    stream: {{ name: {s} }}
        \\  - name: src
        \\    ts: {{ measurement: {s}, field: value, lateness_ms: {d} }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ home, source, lateness_ms, out }) else try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: far-src
        \\sources:
        \\  - name: home
        \\    stream: {{ name: {s} }}
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ home, source, out });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    return remotePipeline(a);
}

/// The pipeline of a job's second source on `a`.
fn remotePipeline(a: *Shard) *ProcessingHandler.PipelineState {
    var pit = a.processing_handler.pipelines.iterator();
    while (pit.next()) |e| if (std.mem.indexOfScalar(u8, e.key_ptr.*, 0) != null) return e.value_ptr;
    unreachable;
}

/// A sink batch on shard 0 with no writes, moving pipeline `key`'s cursor
/// from `from` to `to`, applied.
fn moveCursor(two: *TwoShards, ns: ns_table.Id, key: []const u8, from: anytype, to: anytype) !void {
    var buf: [256]u8 = undefined;
    const payload = try @import("../protocol/processing_entries.zig").SinkBatch.encodeInto(&buf, .{ .ns = ns.int(), .pipeline = key, .from_a = from.a, .from_b = from.b, .to_a = to.a, .to_b = to.b, .records = 0, .messages = .{ .bytes = "", .count = 0 } });
    _ = try two.shards[0].raft_node.propose(.processing_sink_batch, entry_mod.Flags.NONE, payload);
    // Applied without taking the inbox: a page waiting there is the next step's.
    try std.testing.expect(two.shards[0].applyCommitted());
}

fn tickNow(a: *Shard, pipe: *ProcessingHandler.PipelineState) void {
    pipe.last_poll_ms = ProcessingHandler.NEVER_MS;
    _ = a.processing_handler.tickPipelines(a);
}

/// A job of one stream source on shard 0 and the sinks `sinks` (YAML list
/// items), submitted and applied; its pipeline.
fn sinkJob(two: *TwoShards, c: TestClient, source: []const u8, sinks: []const u8) !*ProcessingHandler.PipelineState {
    const a = &two.shards[0];
    var ybuf: [4096]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: sinks
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\{s}
    , .{ source, sinks });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    return pit.next().?;
}

test "Shard: a pipeline's writes to another shard's queue that fills park there, and every record lands once, in order, as it drains" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    for (0..6) |i| {
        var rb: [8]u8 = undefined;
        _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{i}));
    }
    two.settle();
    // The queue holds two at most: the receiver's caps are what a sink's
    // write applies under, whatever its sender's are.
    b.queue_handler.caps.max_messages = 2;
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try sinkJob(&two, c, source, try std.fmt.bufPrint(&yb, "  - name: out\n    queue: {{ name: {s} }}", .{q.name}));
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 4), channels_mod.shardParked(.{ .store = &b.defaultPartition().store }).count);
    // Drained a queueful at a time: each lands in order, none twice.
    var got: [6][2]u8 = undefined;
    var n: usize = 0;
    for (0..6) |_| {
        var bodies: [8][]const u8 = undefined;
        const k = queueBodies(b, q.name, &bodies);
        for (bodies[0..k]) |body| {
            try std.testing.expect(n < got.len and body.len == 2);
            got[n] = body[0..2].*;
            n += 1;
        }
        if (n == 6) break;
        try purgeQueue(b, q.name);
        pumpChannels(&two);
    }
    try std.testing.expectEqual(@as(usize, 6), n);
    for (got, 0..) |g, i| try std.testing.expectEqual(@as(u8, '0' + @as(u8, @intCast(i))), g[1]);
    try std.testing.expectEqual(@as(u64, 0), a.processing_handler.sink_drops);
    for (b.channel.sink_refusals) |r| for (std.enums.values(proto.Reason)) |k| try std.testing.expectEqual(@as(u64, 0), r.get(k));
}

/// A job reading `source` on shard 0 into stream "bs-out" on shard 0,
/// `batch_size` records a poll; its pipeline.
fn batchJob(two: *TwoShards, c: TestClient, source: []const u8, batch_size: u32) !*ProcessingHandler.PipelineState {
    const a = &two.shards[0];
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: bs
        \\batch_size: {d}
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: bs-out }}
    , .{ batch_size, source });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    return pit.next().?;
}

test "Shard: a poll reads its batch_size, a page after another as each batch applies, and no more until the next poll" {
    for ([_]u32{ 200, 50 }) |batch_size| {
        var two: TwoShards = undefined;
        try two.init();
        defer two.deinit();
        const a = &two.shards[0];
        for (&two.shards) |*s| s.wireHandlerShardPtrs();
        var sbuf: [16]u8 = undefined;
        const source = try keyOn(a, .default, 0, &sbuf);
        for (0..200) |i| {
            var rb: [8]u8 = undefined;
            _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{i}));
            if (i % 50 == 49) two.settle();
        }
        two.settle();
        const c = try TestClient.open(a);
        defer _ = std.c.close(c.pair[1]);
        const pipe = try batchJob(&two, c, source, batch_size);
        // One poll: its pages follow one another without waiting for the
        // poll interval, each once the last batch applies.
        pipe.last_poll_ms = ProcessingHandler.NEVER_MS;
        for (0..20) |_| {
            _ = a.processing_handler.tickPipelines(a);
            two.settle();
        }
        try std.testing.expectEqual(@as(u64, @min(batch_size, 200)), pipe.records_in);
        // The next poll reads the next batch_size.
        if (batch_size < 200) {
            pipe.last_poll_ms = ProcessingHandler.NEVER_MS;
            for (0..20) |_| {
                _ = a.processing_handler.tickPipelines(a);
                two.settle();
            }
            try std.testing.expectEqual(@as(u64, 2 * batch_size), pipe.records_in);
        }
        pumpChannels(&two);
        try std.testing.expectEqual(@as(usize, pipe.records_in), streamRecords(a, "bs-out", "default") + streamRecords(&two.shards[1], "bs-out", "default"));
    }
}

test "Shard: a stateful operator starts empty in a new term, as its records are read again, and counts none twice" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for ([_][]const u8{ "r0", "r1", "r2" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: windowed
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: five
        \\    type: aggregate
        \\    function: count
        \\    window: count
        \\    window_count: 5
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: win-out }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const Out = struct {
        fn count(t: *TwoShards) usize {
            return streamRecords(&t.shards[0], "win-out", "default") + streamRecords(&t.shards[1], "win-out", "default");
        }
    };
    // Three counted, the window open: nothing to write, and the cursor
    // not yet logged (the last batch was just now).
    pipe.last_batch_ms = a.processing_handler.mono_ms();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expect(pipe.ahead);
    // Leader again in a later term: the three are read again from the
    // logged cursor. Counted on top of what it held, they and the first
    // two of them would close the window here.
    const raft = a.raft_node;
    raft.current_term += 1;
    raft.ready_index = raft.last_applied;
    pipe.last_batch_ms = a.processing_handler.mono_ms();
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 6), pipe.records_in);
    try std.testing.expectEqual(@as(usize, 0), Out.count(&two));
    // Two more: the window closes on the fifth, once.
    for ([_][]const u8{ "r3", "r4" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 1), Out.count(&two));
    _ = b;
}

test "Shard: operators that can't be rebuilt for a new term make the pipeline wait, said in its status, tried again each poll, not each tick" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for ([_][]const u8{ "r0", "r1" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: rebuild
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: n
        \\    type: aggregate
        \\    function: count
        \\    window: count
        \\    window_count: 5
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: rb-out }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    // A later term, with no memory to build its operators in.
    const raft = a.raft_node;
    raft.current_term += 1;
    raft.ready_index = raft.last_applied;
    const real = a.processing_handler.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    a.processing_handler.allocator = failing.allocator();
    tickNow(a, pipe);
    try std.testing.expectEqualStrings("out of memory", pipe.wait.operators);
    const job = a.processing_handler.firstJob().?;
    var lb: [512]u8 = undefined;
    try std.testing.expectEqualStrings("waiting: its operators couldn't be rebuilt: out of memory", a.processing_handler.liveNote(&job, &lb).?);
    // Ticks before the next poll don't try again.
    const tried = failing.alloc_index;
    for (0..5) |_| _ = a.processing_handler.tickPipelines(a);
    // Its retry is the next poll's, not the loop's: no deadline, so a
    // failing rebuild at a short poll interval can't wake it each ms.
    {
        const nw = a.processing_handler.nextWork(a, pipe.last_poll_ms + 1);
        try std.testing.expect(!nw.due);
        try std.testing.expectEqual(@as(?i64, null), nw.deadline_ms);
    }
    // With records waiting too: still the next poll's, never every tick.
    pipe.more = true;
    for (0..5) |_| {
        _ = a.processing_handler.tickPipelines(a);
        const nw = a.processing_handler.nextWork(a, pipe.last_poll_ms + 1);
        try std.testing.expect(!nw.due);
        try std.testing.expectEqual(@as(?i64, null), nw.deadline_ms);
    }
    try std.testing.expectEqual(tried, failing.alloc_index);
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    // Memory back, at the next poll: rebuilt for this term, and reading.
    a.processing_handler.allocator = real;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expect(pipe.wait == .none);
    try std.testing.expectEqual(raft.current_term, pipe.ops_term);
}

/// A stream job polling every `poll_ms`, its source `source`, sinking to
/// `sinks`, submitted and applied; its pipeline.
fn pacedJob(two: *TwoShards, c: TestClient, name: []const u8, source: []const u8, poll_ms: u32, sinks: []const u8) !*ProcessingHandler.PipelineState {
    const a = &two.shards[0];
    var ybuf: [1024]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: {s}
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s}, poll_interval_ms: {d} }}
        \\sinks:
        \\{s}
    , .{ name, source, poll_ms, sinks });
    // The one pipeline the submit adds.
    var before: [8][]const u8 = undefined;
    var n: usize = 0;
    var bit = a.processing_handler.pipelines.keyIterator();
    while (bit.next()) |k| : (n += 1) before[n] = k.*;
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.iterator();
    next: while (pit.next()) |e| {
        for (before[0..n]) |k| if (std.mem.eql(u8, k, e.key_ptr.*)) continue :next;
        return e.value_ptr;
    }
    return error.NoPipeline;
}

test "Shard: an idle pipeline wakes its shard at its own poll interval, no sooner; two wake at the earlier; none on a follower or for a stopped job" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sb: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sb);
    var tb: [16]u8 = undefined;
    const target = try keyOn(a, .default, 0, &tb);
    var yb: [128]u8 = undefined;
    const sinks = try std.fmt.bufPrint(&yb, "  - name: out\n    stream: {{ name: {s}-out }}", .{target});
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const fast = try pacedJob(&two, c, "fast", source, 10, sinks);
    _ = a.processing_handler.tickPipelines(a);
    const h = a.processing_handler;
    const t = fast.last_poll_ms;
    try std.testing.expect(t != 0);
    // Polled at t, the source empty: due again at t + 10, not before.
    for (0..10) |k| {
        const n = h.nextWork(a, t + @as(i64, @intCast(k)));
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, t + 10), n.deadline_ms);
    }
    try std.testing.expect(h.nextWork(a, t + 10).due);
    // An empty source: the loop never stays up for it, so nothing is
    // counted as an un-slept tick, and its sleep ends at the deadline.
    // (A new leader's first quota walk keeps the loop up too: count it done.)
    a.more_work = false;
    a.quota.clean = .{ .epoch = a.namespace_handler.table.quotaEpoch(), .term = a.raft_node.current_term };
    // The loop reads the pipelines' clock: held at each `now` in turn.
    const Clock = struct {
        var now: u64 = 0;
        fn read() u64 {
            return now;
        }
    };
    h.mono_ms = Clock.read;
    for (0..10) |k| {
        const now = t + @as(i64, @intCast(k));
        Clock.now = @intCast(now);
        a.notePipelinesNext(true);
        a.producers_due = h.nextWork(a, now).due;
        a.producers_deadline_ms = h.nextWork(a, now).deadline_ms;
        try std.testing.expectEqual(@as(u32, @intCast(10 - k)), a.loopTimeoutMs(false));
    }
    // The idle sleep ends at the deadline, at least 1 ms and at most 100.
    a.producers_due = false;
    Clock.now = @intCast(t);
    a.producers_deadline_ms = t + 10;
    try std.testing.expectEqual(@as(u32, 10), a.loopTimeoutMs(false));
    Clock.now = @intCast(t + 10);
    try std.testing.expectEqual(@as(u32, 1), a.loopTimeoutMs(false));
    Clock.now = @intCast(t);
    a.producers_deadline_ms = t + 500;
    try std.testing.expectEqual(@as(u32, 100), a.loopTimeoutMs(false));
    a.producers_deadline_ms = null;
    try std.testing.expectEqual(@as(u32, 100), a.loopTimeoutMs(false));
    h.mono_ms = @import("stdx").time.monotonicMs;
    try std.testing.expectEqual(@as(u64, 0), a.processing_unslept_ticks);
    // Due: the next tick doesn't sleep, and that is counted, on the shard
    // and in the metric a server exports.
    var metrics = MetricsRegistry.init(std.testing.allocator);
    defer metrics.deinit();
    a.setMetricsRegistry(&metrics);
    defer a.metrics_registry = null;
    a.producers_due = true;
    try std.testing.expectEqual(@as(u32, 0), a.loopTimeoutMs(false));
    try std.testing.expectEqual(@as(u64, 1), a.processing_unslept_ticks);
    try std.testing.expectEqual(@as(u64, 1), metrics.processing.unslept_ticks_total.load(.monotonic));
    a.producers_due = false;

    // A second job, every 50 ms, polled later: the earlier deadline wins.
    var s2: [16]u8 = undefined;
    const source2 = try keyOn(a, .default, 0, &s2);
    const slow = try pacedJob(&two, c, "slow", source2, 50, sinks);
    _ = a.processing_handler.tickPipelines(a);
    try std.testing.expect(slow.last_poll_ms >= t);
    const n2 = h.nextWork(a, slow.last_poll_ms);
    try std.testing.expectEqual(@as(?i64, @min(fast.last_poll_ms + 10, slow.last_poll_ms + 50)), n2.deadline_ms);

    // A node that doesn't lead keeps no deadline, nor is it due.
    a.notePipelinesNext(false);
    try std.testing.expect(!a.producers_due);
    try std.testing.expectEqual(@as(?i64, null), a.producers_deadline_ms);
    // A held job gives none either.
    var rit = h.runs.valueIterator();
    while (rit.next()) |r| r.held = true;
    const n3 = h.nextWork(a, t + 1000);
    try std.testing.expect(!n3.due);
    try std.testing.expectEqual(@as(?i64, null), n3.deadline_ms);
}

test "Shard: a pipeline with records left whose batch is in the log, or that waits at a full outbox, keeps the loop neither awake nor timed, tick after tick; freed, it's due" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    // More records than one page: `more` is set after the first.
    for (0..200) |i| {
        var rb: [8]u8 = undefined;
        _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{i}));
    }
    two.settle();
    // One byte a channel: the first batch fills it.
    a.outbox_caps = .{ .sink = .{ .shard = 1 << 30, .channel = 1 } };
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try pacedJob(&two, c, "held", source, 1, try std.fmt.bufPrint(&yb, "  - name: out\n    queue: {{ name: {s} }}", .{q.name}));
    const h = a.processing_handler;
    _ = h.tickPipelines(a);
    // Its batch proposed, not yet applied: skipped, neither due nor timed.
    if (pipe.batch_index > a.raft_node.last_applied) {
        const n = h.nextWork(a, pipe.last_poll_ms + 1000);
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
    }
    two.settle();
    const taken = pipe.records_in;
    try std.testing.expect(taken > 0 and taken < 200);
    try std.testing.expect(pipe.more);
    // Every later tick finds the full outbox: more stays set, nothing is
    // read, and the loop is told neither to stay up nor when to wake.
    for (0..20) |_| {
        _ = h.tickPipelines(a);
        two.settle();
        try std.testing.expect(pipe.wait == .outbox);
        try std.testing.expect(pipe.more);
        try std.testing.expectEqual(taken, pipe.records_in);
        const n = h.nextWork(a, h.nowMs());
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
    }
    // Delivered and trimmed: room, and the pipeline is due at once.
    pumpChannels(&two);
    two.settle();
    try std.testing.expect(h.nextWork(a, h.nowMs()).due);

    // Its sink's shard halted: a wait, so neither due nor timed.
    var slots: [2]health_mod.ShardSlot = @splat(.{});
    const had = a.node_health;
    a.node_health = &slots;
    defer a.node_health = had;
    slots[1].set(.halted);
    for (0..5) |_| {
        const n = h.nextWork(a, h.nowMs());
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
    }
    slots[1].set(.ok);
    try std.testing.expect(h.nextWork(a, h.nowMs()).due);

    // A page asked of another shard, not yet come: nothing until it does.
    const now = h.nowMs();
    pipe.read_seq = 1;
    pipe.read_sent_ms = now;
    try std.testing.expect(!h.nextWork(a, now + 10).due);
    try std.testing.expectEqual(@as(?i64, null), h.nextWork(a, now + 10).deadline_ms);
    // Past its deadline it's asked again: due.
    try std.testing.expect(h.nextWork(a, now + 6_000).due);
    pipe.read_seq = 0;

    // Cancelled with records left: no run, so nothing due or timed.
    var ib: [64]u8 = undefined;
    var rit = h.runs.keyIterator();
    const id = try std.fmt.bufPrint(&ib, "{s}", .{rit.next().?.*});
    a.runRequest(c.conn, try ParkTest.request(.processing_cancel, 6, "", id, "", ""), .client);
    two.settle();
    _ = h.tickPipelines(a);
    const n = h.nextWork(a, h.nowMs() + 1000);
    try std.testing.expect(!n.due);
    try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
}

test "Shard: a pipeline polls on the monotonic clock: a wall-clock step neither stops nor hurries it" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    // Far from any wall-clock time, so a poll timed by the wall clock
    // would read as long overdue, or decades ahead; and under one poll
    // interval, as a monotonic clock is just after boot.
    const Clock = struct {
        var now: u64 = 500;
        fn read() u64 {
            return now;
        }
    };
    a.processing_handler.mono_ms = Clock.read;
    const h = a.processing_handler;
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r0");
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: mono
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s}, poll_interval_ms: 1000 }}
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: mono-out }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = h.pipelines.valueIterator();
    const pipe = pit.next().?;
    // Never polled: due at once, though the clock is near 0.
    try std.testing.expect(h.nextWork(a, h.nowMs()).due);
    _ = h.tickPipelines(a);
    two.settle();
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expectEqual(@as(i64, 500), pipe.last_poll_ms);
    // The next poll is 1000 ms on, by this clock, and the loop sleeps to it.
    Clock.now = 900;
    const n = h.nextWork(a, h.nowMs());
    try std.testing.expect(!n.due);
    try std.testing.expectEqual(@as(?i64, 1_500), n.deadline_ms);
    a.notePipelinesNext(true);
    // As the loop asks it, with nothing else to do (a new leader's first
    // quota walk counted done).
    a.more_work = false;
    a.apply_behind = false;
    a.quota.clean = .{ .epoch = a.namespace_handler.table.quotaEpoch(), .term = a.raft_node.current_term };
    try std.testing.expectEqual(@as(u32, 100), a.loopTimeoutMs(false));
    Clock.now = 1_450;
    try std.testing.expectEqual(@as(u32, 50), a.loopTimeoutMs(false));
    // A record waits; not read before the poll, read at it.
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r1");
    two.settle();
    _ = h.tickPipelines(a);
    two.settle();
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    Clock.now = 1_500;
    _ = h.tickPipelines(a);
    two.settle();
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    try std.testing.expectEqual(@as(i64, 1_500), pipe.last_poll_ms);
}

test "Shard: a filter that drops whole pages keeps its pipeline due while records remain, and not after" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for (0..200) |i| {
        var rb: [8]u8 = undefined;
        _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{i}));
    }
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: dropper
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s}, poll_interval_ms: 1000, batch_size: 1000 }}
        \\operators:
        \\  - name: none
        \\    type: filter
        \\    condition: value_contains:never-in-a-record
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: dropped }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const h = a.processing_handler;
    // Page after page is dropped whole: nothing written, and the poll not
    // yet due again, yet each tick reads on.
    var last: u64 = 0;
    var ticks: usize = 0;
    while (pipe.records_in < 200) : (ticks += 1) {
        if (ticks > 0) try std.testing.expect(h.nextWork(a, pipe.last_poll_ms).due);
        _ = h.tickPipelines(a);
        two.settle();
        try std.testing.expect(pipe.records_in > last);
        last = pipe.records_in;
        if (ticks > 20) return error.NoProgress;
    }
    // Caught up: not due until its next poll, which is the deadline.
    _ = h.tickPipelines(a);
    two.settle();
    const n = h.nextWork(a, pipe.last_poll_ms + 1);
    try std.testing.expect(!n.due);
    try std.testing.expectEqual(@as(?i64, pipe.last_poll_ms + 1000), n.deadline_ms);
}

test "Shard: a pipeline waits while its outbox to a sink's shard, or all its outboxes, hold their cap, and reads on once they're taken" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    var rb: [8]u8 = undefined;
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r0");
    two.settle();
    // One byte a channel: the first batch fills it.
    a.outbox_caps = .{ .sink = .{ .shard = 1 << 30, .channel = 1 } };
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try sinkJob(&two, c, source, try std.fmt.bufPrint(&yb, "  - name: out\n    queue: {{ name: {s} }}", .{q.name}));
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    const read: contract_view.ReadView = .{ .store = &a.defaultPartition().store };
    const held = channels_mod.metaOf(read, 1, .sink).bytes;
    try std.testing.expect(held > 0);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{1}));
    two.settle();
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expectEqual(@as(?u16, 1), pipe.wait.outbox.to);
    try std.testing.expectEqual(held, pipe.wait.outbox.bytes);
    // The sink's bytes are counted against the sink's caps alone: a main or
    // history write to shard 1 isn't held by them, a sink's is.
    try std.testing.expect(a.sendWait(1, .main, .default) == null);
    try std.testing.expect(a.sendWait(1, .history, .default) == null);
    try std.testing.expect(a.sendWait(1, .sink, .default).? == .outbox);
    {
        // A replica of shard 0, as a restart or a new leader holds it: the
        // same log, applied, holds the same outbox bytes.
        const pipe_fds = try @import("stdx").io.pipe();
        defer _ = std.c.close(pipe_fds[0]);
        defer _ = std.c.close(pipe_fds[1]);
        var r = try Shard.init(std.testing.allocator, 0, 2, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{ .namespaces = two.namespaces });
        defer r.deinit();
        r.wireHandlerShardPtrs();
        var i: u64 = r.raft_node.last_applied + 1;
        while (i <= a.raft_node.last_applied) : (i += 1) {
            const e = a.raft_node.log.getEntry(i).?;
            var out = persistence_mod.Result.start(&e);
            try std.testing.expect(r.applyEntry(&e, &out));
        }
        try std.testing.expectEqual(held, channels_mod.metaOf(.{ .store = &r.defaultPartition().store }, 1, .sink).bytes);
        try std.testing.expectEqual(held, r.outboxBytes(.sink));
    }
    const job = a.processing_handler.firstJob().?;
    var lb: [512]u8 = undefined;
    try std.testing.expectEqualStrings("waiting: the outbox to shard 1 is full (46 B of 1 B)", a.processing_handler.liveNote(&job, &lb).?);
    // Delivered, acked and trimmed: room again, and the next record goes.
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 0), channels_mod.metaOf(read, 1, .sink).bytes);
    tickNow(a, pipe);
    two.settle();
    try std.testing.expect(pipe.wait == .none);
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    // The shard's cap, over all its outboxes, holds it the same way.
    a.outbox_caps = .{ .sink = .{ .shard = 1, .channel = 1 << 30 } };
    _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rb, "r{d}", .{2}));
    two.settle();
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    try std.testing.expectEqual(@as(?u16, null), pipe.wait.outbox.to);
    // Trims are spaced 100 ms apart; this one is due now.
    a.channel.peers[1].lanes[@backingInt(channels_mod.Lane.sink)].last_trim_ms = 0;
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 0), a.outboxBytes(.sink));
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    pumpChannels(&two);
    var bodies: [8][]const u8 = undefined;
    try std.testing.expectEqual(@as(usize, 3), queueBodies(b, q.name, &bodies));
}

test "Shard: a pipeline whose namespace holds three quarters of a channel's outbox waits for its share, though the outbox has room" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r0");
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try sinkJob(&two, c, source, try std.fmt.bufPrint(&yb, "  - name: out\n    queue: {{ name: {s} }}", .{q.name}));
    tickNow(a, pipe);
    two.settle();
    const read: contract_view.ReadView = .{ .store = &a.defaultPartition().store };
    const held = channels_mod.nsBytesOf(read, 1, .sink, .default);
    try std.testing.expectEqual(channels_mod.metaOf(read, 1, .sink).bytes, held);
    // A cap the outbox is under, but whose three quarters the namespace holds.
    a.outbox_caps = .{ .sink = .{ .shard = 1 << 30, .channel = held + held / 4 + 1 } };
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r1");
    two.settle();
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expectEqual(@as(?u16, 1), pipe.wait.share.to);
    try std.testing.expectEqual(held, pipe.wait.share.bytes);
    // Taken and trimmed: its share is free, and it reads on.
    a.channel.peers[1].lanes[2].last_trim_ms = 0;
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 0), channels_mod.nsBytesOf(read, 1, .sink, .default));
    tickNow(a, pipe);
    two.settle();
    try std.testing.expect(pipe.wait == .none);
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
}

/// The pipeline whose first sink writes into `namespace`.
fn pipelineOf(a: *Shard, namespace: []const u8) *ProcessingHandler.PipelineState {
    var it = a.processing_handler.pipelines.valueIterator();
    while (it.next()) |p| if (std.mem.eql(u8, p.sinks[0].namespace, namespace)) return p;
    unreachable;
}

test "Shard: a namespace holding three quarters of all this shard's outboxes waits for its share, and another namespace's pipeline reads on" {
    var two: TwoShards = undefined;
    try two.init();
