test "Shard: pressure that arrived as a send-only shard's outbox emptied still expires, and its pipeline reads on" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r0");
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try sinkJob(&two, c, source, try std.fmt.bufPrint(&yb, "  - name: out\n    queue: {{ name: {s} }}", .{q.name}));
    tickNow(a, pipe);
    two.settle();
    a.channel.peers[1].lanes[@backingInt(channels_mod.Lane.sink)].last_trim_ms = 0;
    pumpChannels(&two);
    // Everything sent is taken and trimmed: nothing left for a's channels.
    const fams = &a.defaultPartition().store.families;
    try std.testing.expectEqual(@as(usize, 0), fams[channels_mod.OutFam.ID].count + fams[channels_mod.InFam.ID].count + fams[channels_mod.ParkFam.ID].count);
    // The last answer before the trim said shard 1 is halted.
    // Time is set, not waited for: each phase stamps the pressure as of
    // the clock it is read against.
    if (Shard.nowMs() <= 2 * channel_driver.PRESSURE_EXPIRY_MS) return error.SkipZigTest;
    const p = &a.channel.peers[1].lanes[@backingInt(channels_mod.Lane.sink)];
    p.pressure[0] = .{ .shard = 1, .cause = @backingInt(channel_driver.Cause.halted) };
    p.pressure_len = 1;
    p.probe_ms = 0;
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r1");
    two.settle();
    p.pressure_ms = Shard.nowMs();
    // It holds a's sink sends to shard 1, and no other lane's.
    try std.testing.expect(a.sendWait(1, .sink, .default) != null);
    try std.testing.expect(a.sendWait(1, .main, .default) == null);
    try std.testing.expect(a.sendWait(1, .history, .default) == null);
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expect(pipe.wait == .pressure);
    // Its channels keep ticking while the pressure is live: it probes.
    p.pressure_ms = Shard.nowMs();
    a.tickChannels();
    try std.testing.expect(p.probe_ms > 0);
    // Read on the pipelines' clock: pressure stamped as of it holds the
    // pipeline, though the host's clock is long past the stamp.
    {
        const Clock = struct {
            fn read() u64 {
                return 1_000;
            }
        };
        const since = pipe.held_since_ms;
        const counted = pipe.wait_counted_ms;
        a.processing_handler.mono_ms = Clock.read;
        p.pressure_ms = 1_000;
        tickNow(a, pipe);
        try std.testing.expect(pipe.wait == .pressure);
        a.processing_handler.mono_ms = @import("stdx").time.monotonicMs;
        pipe.held_since_ms = since;
        pipe.wait_counted_ms = counted;
    }
    // The last answer carrying it was long ago, and the driver's own clock
    // stopped then: it is gone by the time now, and the pipeline reads on.
    p.pressure_ms = 1;
    a.channel.now_ms = 1;
    a.tickChannels();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expect(pipe.wait == .none);
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);
    // Reading again, it no longer waits: a next wait starts its own count.
    try std.testing.expectEqual(ProcessingHandler.NEVER_MS, pipe.held_since_ms);
}

test "Shard: records whose operators emit nothing aren't read again while their cursor waits to be logged" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for ([_][]const u8{ "r0", "r1", "r2" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: quiet
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: none
        \\    type: filter
        \\    condition: value_contains:never-in-a-record
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: quiet-out }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    // The first page logs its cursor; the next, within the second, has
    // nothing to log and reads on from where it is.
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r3");
    two.settle();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 4), pipe.records_in);
    try std.testing.expect(pipe.ahead);
    // Polled again before the second is up: nothing read twice.
    for (0..3) |_| {
        tickNow(a, pipe);
        two.settle();
    }
    try std.testing.expectEqual(@as(u64, 4), pipe.records_in);
    // Past it, the cursor is logged where the read reached.
    pipe.last_batch_ms = 0;
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r4");
    two.settle();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 5), pipe.records_in);
    try std.testing.expect(!pipe.ahead);
    const job = a.processing_handler.firstJob().?;
    const at = @import("../processing/sinks_machine.zig").cursorOf(.{ .store = &a.defaultPartition().store }, .default, job.job_id_owned);
    try std.testing.expectEqual(pipe.stream_cursor_seq, at.b);
    try std.testing.expectEqual(pipe.stream_cursor_ts, at.a);
    // Every record read is counted once, those whose batch waited too.
    try std.testing.expectEqual(@as(u64, 5), job.records_processed);
}

test "Shard: a TS sink drops a record lacking a tag's field, counted and shown on its job, and its cursor passes it as the rest land" {
    var two: TwoShards = undefined;
    try two.init();
