    try std.testing.expectEqual(pipe.stream_cursor_ts, at.a);
    try std.testing.expectEqual(@as(u64, 4), job.records_processed);
}

test "Shard: an operator chain out of memory ends the batch before its record: nothing written, skipped or passed, and the next tick takes it" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var target_buf: [24]u8 = undefined;
    const target = try nameOn(a, .default, 0, "tout", &target_buf);
    for ([_][]const u8{ "{\"v\":1}", "{\"v\":2}", "{\"v\":3}" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: short
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: m
        \\    type: map
        \\    v: "$.v"
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ source, target });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const h = a.processing_handler;

    // Every allocation of the chain's arena fails, at a time the
    // pipelines' clock gives.
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    h.chain_backing = failing.allocator();
    const Clock = struct {
        fn read() u64 {
            return 700;
        }
    };
    h.mono_ms = Clock.read;
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(i64, 700), pipe.stalled_ms);
    // Waiting while the stall lasts, by that clock; not after.
    try std.testing.expect(!h.nextWork(a, 799).due);
    h.mono_ms = @import("stdx").time.monotonicMs;
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 0), pipe.records_in);
    try std.testing.expectEqual(@as(u64, 0), pipe.stream_cursor_ts);
    try std.testing.expectEqual(@as(u64, 0), h.sink_drops);
    try std.testing.expectEqual(@as(u64, 0), h.chain_errors);
    try std.testing.expectEqual(@as(u64, 0), h.firstJob().?.drops);
    try std.testing.expectEqual(@as(usize, 0), streamRecords(a, target, "default"));
    // The stall shows on the job: not a silent RUNNING.
    {
        const job = h.firstJob().?;
        var nb: [512]u8 = undefined;
        try std.testing.expect(std.mem.indexOf(u8, h.liveNote(&job, &nb).?, "1 batch stopped short of memory, each record tried again") != null);
    }

    // Just stalled: a wait, neither due nor timed, until the shard's own
    // wake retries it.
    {
        const n = h.nextWork(a, pipe.stalled_ms + 1);
        try std.testing.expect(!n.due);
        try std.testing.expectEqual(@as(?i64, null), n.deadline_ms);
    }

    // Memory back, the wait over: the same records, every one, once.
    h.chain_backing = null;
    pipe.stalled_ms = ProcessingHandler.NEVER_MS;
    pipe.last_batch_ms = 0;
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(@as(usize, 3), streamRecords(a, target, "default"));
    try std.testing.expectEqual(@as(u64, 0), h.firstJob().?.drops);
}

test "Shard: a running sum out of memory is run again and counts each record once" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var target_buf: [24]u8 = undefined;
    const target = try nameOn(a, .default, 0, "tsum", &target_buf);
    for ([_][]const u8{ "{\"v\":1}", "{\"v\":2}", "{\"v\":3}" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: summed
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: s
        \\    type: aggregate
        \\    function: sum
        \\    field: "$.v"
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
    , .{ source, target });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const h = a.processing_handler;
    // Fails at every allocation number in turn, then runs clean: whatever
    // failed, the totals are 1, 3 and 6, each record counted once.
    var fail_at: usize = 0;
    while (fail_at < 40) : (fail_at += 1) {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = fail_at });
        h.chain_backing = failing.allocator();
        pipe.last_batch_ms = 0;
        pipe.stalled_ms = ProcessingHandler.NEVER_MS;
        tickNow(a, pipe);
        two.settle();
        h.chain_backing = null;
        if (pipe.records_in == 3) break;
    }
    pipe.last_batch_ms = 0;
    pipe.stalled_ms = ProcessingHandler.NEVER_MS;
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expect(h.memory_stalls > 0);
    try std.testing.expectEqual(@as(usize, 3), streamRecords(a, target, "default"));
    var lb: [128]u8 = undefined;
    const last = lastStreamPayload(a, target, "default", &lb) orelse return error.NoRecord;
    try std.testing.expect(std.mem.indexOf(u8, last, "\"value\":6,\"count\":3") != null);
}

test "Shard: a job's processed count takes each record once, across batches not logged, logged, and refused" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    for ([_][]const u8{ "r0", "r1", "r2" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: counted
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: none
        \\    type: filter
        \\    condition: value_contains:never-in-a-record
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: counted-out }}
    , .{source});
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const Step = struct {
        fn run(t: *TwoShards, sh: *Shard, p: *ProcessingHandler.PipelineState, src: []const u8, rec: []const u8, logged: bool) !void {
            _ = try sh.stream_handler.appendPayloadToStream(src, "default", rec);
            t.settle();
            // A batch with no writes is logged once a second has passed
            // since the last; within it, it waits, unlogged.
            if (logged) p.last_batch_ms = 0;
            tickNow(sh, p);
            t.settle();
        }
    };
    const counted = struct {
        fn n(sh: *Shard) u64 {
            return sh.processing_handler.firstJob().?.records_processed;
        }
    }.n;
    // Logged: the three there.
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), counted(a));
    // Unlogged, then logged: the next batch takes it, then counts only its
    // own.
    try Step.run(&two, a, pipe, source, "r3", false);
    try std.testing.expectEqual(@as(u64, 3), counted(a));
    try Step.run(&two, a, pipe, source, "r4", true);
    try std.testing.expectEqual(@as(u64, 5), counted(a));
    try Step.run(&two, a, pipe, source, "r5", true);
    try std.testing.expectEqual(@as(u64, 6), counted(a));
    // Unlogged, then refused by the log: read again from the logged
    // cursor, and counted once when a batch goes through.
    try Step.run(&two, a, pipe, source, "r6", false);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "r7");
    two.settle();
    a.raft_node.writes_stopped = true;
    pipe.last_batch_ms = 0;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 6), counted(a));
    a.raft_node.writes_stopped = false;
    pipe.last_batch_ms = 0;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 8), counted(a));
}

test "Shard: a batch that carries a record on counts the records it covers once, after one not logged" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var obuf: [16]u8 = undefined;
    const out = try keyOn(a, .default, 0, &obuf);
    _ = try a.stream_handler.appendPayloadToStream(source, "default", "drop-0");
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: carrying
        \\batch_size: 500
        \\sources:
        \\  - name: src
        \\    stream: {{ name: {s} }}
        \\operators:
        \\  - name: some
        \\    type: filter
        \\    condition: value_contains:keep
        \\sinks:
        \\  - name: out
        \\    stream: {{ name: {s} }}
        \\  - name: again
        \\    stream: {{ name: {s} }}
    , .{ source, out, out });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    const counted = struct {
        fn n(sh: *Shard) u64 {
            return sh.processing_handler.firstJob().?.records_processed;
        }
    }.n;
    // A record with no writes, within a second of the last batch: read on,
    // not logged.
    pipe.last_batch_ms = a.processing_handler.mono_ms();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 0), counted(a));
    try std.testing.expect(pipe.ahead);
    // Records of two writes each, one more than one batch's writes hold:
    // the batch covers the first record and those it holds, the last
    // carried to the next, which it leads without the cursor being read
    // again.
    const fit = channels_mod.MAX_SENDS / 2;
    var rbuf: [16]u8 = undefined;
    for (0..fit + 1) |i| _ = try a.stream_handler.appendPayloadToStream(source, "default", try std.fmt.bufPrint(&rbuf, "keep-{d}", .{i}));
    two.settle();
    tickNow(a, pipe);
    _ = a.applyCommitted();
    try std.testing.expectEqual(@as(u64, 1 + fit), counted(a));
    try std.testing.expect(pipe.carry_n > 0);
    for (0..3) |_| {
        tickNow(a, pipe);
        two.settle();
    }
    try std.testing.expectEqual(@as(u64, fit + 2), counted(a));
}

test "Shard: a batch proposed again in a new term before the first applied lands once" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    var obuf: [16]u8 = undefined;
    const out = try keyOn(b, .default, 1, &obuf);
    for ([_][]const u8{ "r0", "r1", "r2" }) |r| _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [128]u8 = undefined;
    const pipe = try sinkJob(&two, c, source, try std.fmt.bufPrint(&yb, "  - name: out\n    stream: {{ name: {s} }}", .{out}));
    const raft = a.raft_node;
    const from = raft.log.lastIndex() + 1;
    // Proposed, and not applied before the term moves on.
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(a, .processing_sink_batch, from));
    // A new term's leader that proposes before its predecessor's batch
    // applies reads again from the applied cursor and proposes the same
    // batch. A real leader waits for that batch to apply first, so this
    // tests the applier's guard, not the usual path.
    raft.current_term += 1;
    raft.ready_index = raft.last_applied;
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(usize, 2), entriesOf(a, .processing_sink_batch, from));
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 3), streamRecords(b, out, "default"));
    // And nothing more: the cursor is past them.
    tickNow(a, pipe);
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 3), streamRecords(b, out, "default"));
}

test "Shard: a record whose writes don't fit one entry is skipped, counted, and named in its job's status; the records around it land" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(a, .default, 0, &sbuf);
    // Seventeen sinks, each taking the whole record: 63 KiB seventeen
    // times is past the 1 MiB one entry carries.
    const SINKS = 17;
    var yb: [2048]u8 = undefined;
    var yw: std.Io.Writer = .fixed(&yb);
    for (0..SINKS) |k| try yw.print("{s}  - name: s{d}\n    stream: {{ name: out{d} }}", .{ if (k == 0) "" else "\n", k, k });
    const big = try std.testing.allocator.alloc(u8, 63 * 1024);
    defer std.testing.allocator.free(big);
    @memset(big, 'x');
    for ([_][]const u8{ "before", big, "after" }) |r| {
        _ = try a.stream_handler.appendPayloadToStream(source, "default", r);
        two.settle();
    }
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const pipe = try sinkJob(&two, c, source, yw.buffered());
    var metrics = MetricsRegistry.init(std.testing.allocator);
    defer metrics.deinit();
    a.setMetricsRegistry(&metrics);
    for (0..4) |_| {
        tickNow(a, pipe);
        two.settle();
        pumpChannels(&two);
    }
    for (0..SINKS) |k| {
        var nb: [16]u8 = undefined;
        const name = try std.fmt.bufPrint(&nb, "out{d}", .{k});
        try std.testing.expectEqual(@as(usize, 2), streamRecords(a, name, "default") + streamRecords(b, name, "default"));
    }
    const job = a.processing_handler.firstJob().?;
    try std.testing.expectEqual(@as(u64, 1), job.drops);
    try std.testing.expectEqual(@as(u64, 1), a.processing_handler.too_large);
    // Counted once as dropped, and once as too large.
    try std.testing.expectEqual(@as(u64, 1), metrics.processing.records_dropped_total.load(.monotonic));
    try std.testing.expectEqual(@as(u64, 1), metrics.processing.records_too_large_total.load(.monotonic));
    var lb: [512]u8 = undefined;
    const note = a.processing_handler.liveNote(&job, &lb).?;
    try std.testing.expect(std.mem.indexOf(u8, note, "1 record skipped") != null);
    try std.testing.expect(std.mem.indexOf(u8, note, "don't fit one entry") != null);
}

test "Shard: a pipeline whose source stream is on another shard reads it only through that shard's inbox" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(b, .default, 1, &sbuf);
    var obuf: [16]u8 = undefined;
    const out = try keyOn(a, .default, 0, &obuf);
    for ([_][]const u8{ "r0", "r1", "r2" }) |r| _ = try b.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const pipe = try remoteSourceJob(&two, c, source, false, out);

    // The tick asks; nothing is read here until shard 1 answers.
    tickNow(a, pipe);
    try std.testing.expect(pipe.read_seq != 0);
    try std.testing.expectEqual(@as(u64, 0), pipe.records_in);
    // While it waits, ticks ask nothing more.
    const asked = pipe.read_seq;
    tickNow(a, pipe);
    try std.testing.expectEqual(asked, pipe.read_seq);
    try std.testing.expectEqual(@as(usize, 1), b.mailbox.inbox.pending());
    two.settle();
    try std.testing.expectEqual(@as(u64, 0), pipe.read_seq);
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 3), streamRecords(a, out, "default"));

    // More appended: the next read takes them, none again.
    _ = try b.stream_handler.appendPayloadToStream(source, "default", "r3");
    two.settle();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 4), pipe.records_in);
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 4), streamRecords(a, out, "default"));
}

