test "Shard: a TS source on another shard holds back its window from that shard's newest point, and reads the rest once the field is idle" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var mbuf: [16]u8 = undefined;
    const measurement = try keyOn(b, .default, 1, &mbuf);
    var obuf: [16]u8 = undefined;
    const out = try keyOn(a, .default, 0, &obuf);
    const s = std.time.ns_per_s;
    try tsPut(b, measurement, 1, 10 * s, "host=a");
    try tsPut(b, measurement, 2, 20 * s, "host=a");
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    // The source's idle clock, advanced by hand.
    const Clock = struct {
        var now: u64 = 1_000_000;
        fn read() u64 {
            return now;
        }
    };
    a.processing_handler.mono_ms = Clock.read;
    const pipe = try remoteSourceJobLate(&two, c, measurement, true, out, 5000);
    // The first ask, before this shard has seen the field, already reads
    // up to shard 1's newest less the window: the point at 10 s.
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expectEqual(10 * s, pipe.ts_cursor.ns);
    // The page said how many writes the field has had.
    try std.testing.expectEqual(@as(?u64, 2), pipe.seen_writes);
    // A point 2 s behind the newest, from another host: inside the window,
    // so ahead of the cursor, and not read yet.
    try tsPut(b, measurement, 3, 18 * s, "host=b");
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 1), pipe.records_in);
    try std.testing.expectEqual(@as(?u64, 3), pipe.seen_writes);
    // Once the field has had no write for the window: the rest, in order.
    Clock.now += 5000;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(20 * s, pipe.ts_cursor.ns);

    // Idle again, judged from the last page; then a write lands on shard 1
    // before the next ask. Its count no longer matches what this shard
    // judged idle at, so shard 1 holds the window from the new newest:
    // a point that then arrives 2 s behind it is still ahead of the cursor.
    Clock.now += 5000;
    try tsPut(b, measurement, 4, 40 * s, "host=a");
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(20 * s, pipe.ts_cursor.ns);
    try tsPut(b, measurement, 5, 38 * s, "host=b");
    // The window passes since the last page, but that page saw 4 writes,
    // not 5: still held, and this ask learns of the fifth.
    Clock.now += 5000;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(@as(?u64, 5), pipe.seen_writes);
    // No write since, for the window: both read, in time order.
    Clock.now += 5000;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 5), pipe.records_in);
    try std.testing.expectEqual(40 * s, pipe.ts_cursor.ns);
}

test "Shard: a TS source with more points at one time than a tick has room for goes on through them, each written once" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var mbuf: [16]u8 = undefined;
    const measurement = try keyOn(a, .default, 0, &mbuf);
    var tbuf: [16]u8 = undefined;
    const hosts = 400;
    for (0..hosts) |i| try tsPut(a, measurement, 1, 5_000_000, try std.fmt.bufPrint(&tbuf, "host={d}", .{i}));
    var obuf: [3][16]u8 = undefined;
    var outs: [3][]const u8 = undefined;
    var k: usize = 0;
    var found: usize = 0;
    while (found < 3) : (k += 1) {
        const name = try std.fmt.bufPrint(&obuf[found], "out{d}", .{k});
        if (a.router.hashToShard(node_router.routeNsKey(.default, name)) == 0) {
            outs[found] = name;
            found += 1;
        }
    }
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var ybuf: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&ybuf,
        \\kind: Processing
        \\name: wide
        \\sources:
        \\  - name: src
        \\    ts: {{ measurement: {s}, field: value, lateness_ms: 0 }}
        \\sinks:
        \\  - name: a
        \\    stream: {{ name: {s} }}
        \\  - name: b
        \\    stream: {{ name: {s} }}
        \\  - name: c
        \\    stream: {{ name: {s} }}
    , .{ measurement, outs[0], outs[1], outs[2] });
    a.runRequest(c.conn, try ParkTest.request(.processing_submit, 5, "", "", yaml, ""), .client);
    two.settle();
    var pit = a.processing_handler.pipelines.valueIterator();
    const pipe = pit.next().?;
    // A batch takes the points whose writes fit one entry, a few of 400
    // sharing one time: the next goes on from the last point it wrote.
    // The channel delivers as they go: past a window of writes unacked,
    // the pipeline would wait for it.
    for (0..60) |_| {
        tickNow(a, pipe);
        two.settle();
        pumpChannels(&two);
        if (streamRecords(a, outs[2], "default") == hosts) break;
    }
    // Each point read once: one cut from a full batch carries its writes
    // to the next, its operators not run on it again.
    // 1200 writes: the channel delivers a batch at a time.
    for (0..20) |_| {
        pumpChannels(&two);
        if (streamRecords(a, outs[2], "default") == hosts) break;
    }
    try std.testing.expectEqual(@as(u64, hosts), pipe.records_in);
    for (outs) |o| try std.testing.expectEqual(@as(usize, hosts), streamRecords(a, o, "default"));
    try std.testing.expectEqual(@as(u64, 5_000_000), pipe.ts_cursor.ns);
}

test "Shard: a TS page held partway, among points sharing a time, goes on from the last point written, none written twice" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var mbuf: [16]u8 = undefined;
    const measurement = try keyOn(b, .default, 1, &mbuf);
    var tbuf: [16]u8 = undefined;
    const hosts = 300;
    for (0..hosts) |i| try tsPut(b, measurement, 1, 5_000_000, try std.fmt.bufPrint(&tbuf, "host={d}", .{i}));
    var obuf: [16]u8 = undefined;
    const out = try keyOn(a, .default, 0, &obuf);
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const pipe = try remoteSourceJob(&two, c, measurement, true, out);

    // A page of more points than one batch's writes take: the batch ends
    // partway through points sharing a time.
    tickNow(a, pipe);
    _ = b.drainInbox();
    _ = a.drainInbox();
    try std.testing.expect(pipe.records_in > 0 and pipe.records_in < hosts);
    for (0..40) |_| {
        two.settle();
        tickNow(a, pipe);
        if (pipe.records_in == hosts) break;
    }
    two.settle();
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, hosts), pipe.records_in);
    try std.testing.expectEqual(@as(usize, hosts), streamRecords(a, out, "default"));
}

test "Shard: a source page that answers no read in flight, comes in another term, or finds the cursor moved is dropped, and a lost read is asked again" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    var sbuf: [16]u8 = undefined;
    const source = try keyOn(b, .default, 1, &sbuf);
    var obuf: [16]u8 = undefined;
    const out = try keyOn(a, .default, 0, &obuf);
    for ([_][]const u8{ "r0", "r1" }) |r| _ = try b.stream_handler.appendPayloadToStream(source, "default", r);
    two.settle();
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    const pipe = try remoteSourceJob(&two, c, source, false, out);

    // Asked again before the first answer (as after the deadline): the
    // first answer is stale and dropped, the second processed.
    tickNow(a, pipe);
    pipe.read_sent_ms -= 10_000;
    tickNow(a, pipe);
    try std.testing.expectEqual(@as(usize, 2), b.mailbox.inbox.pending());
    two.settle();
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);

    // A page from an earlier term: dropped, and asked again.
    _ = try b.stream_handler.appendPayloadToStream(source, "default", "r2");
    two.settle();
    tickNow(a, pipe);
    _ = b.drainInbox();
    a.raft_node.current_term += 1;
    _ = a.drainInbox();
    try std.testing.expectEqual(@as(u64, 2), pipe.records_in);

    // A lost read: once its deadline passes, it is asked again, and the
    // record comes once.
    a.raft_node.current_term -= 1;
    pipe.read_sent_ms -= 10_000;
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);

    // A batch moved the cursor while a read was out: its page is dropped.
    _ = try b.stream_handler.appendPayloadToStream(source, "default", "r3");
    two.settle();
    tickNow(a, pipe);
    _ = b.drainInbox();
    const sm_ = @import("../processing/sinks_machine.zig");
    var pkit = a.processing_handler.pipelines.iterator();
    const pkey = while (pkit.next()) |e| {
        if (std.mem.indexOfScalar(u8, e.key_ptr.*, 0) != null) break e.key_ptr.*;
    } else unreachable;
    const ns = a.processing_handler.runs.getPtr(pkey[0..std.mem.indexOfScalar(u8, pkey, 0).?]).?.ns_id;
    const at = sm_.cursorOf(.{ .store = &a.defaultPartition().store }, ns, pkey);
    try moveCursor(&two, ns, pkey, at, .{ .a = at.a, .b = at.b + 1 });
    _ = a.drainInbox();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(@as(u64, 0), pipe.read_seq);
    try moveCursor(&two, ns, pkey, .{ .a = at.a, .b = at.b + 1 }, at);

    // Its sinks out of room when the page comes: dropped, the cursor where
    // it was, and read again once there's room.
    tickNow(a, pipe);
    _ = b.drainInbox();
    const cursor_seq = pipe.stream_cursor_seq;
    var kbuf: [16]u8 = undefined;
    var i: usize = 0;
    while (a.raft_node.log.lastIndex() - a.raft_node.last_applied < raft_node_mod.MAX_OUTSTANDING) : (i += 1)
        _ = try KVHandler.testProposePut(a, try std.fmt.bufPrint(&kbuf, "fill{d}", .{i}), "v");
    _ = a.drainInbox();
    try std.testing.expectEqual(@as(u64, 3), pipe.records_in);
    try std.testing.expectEqual(cursor_seq, pipe.stream_cursor_seq);
    two.settle();
    tickNow(a, pipe);
    two.settle();
    try std.testing.expectEqual(@as(u64, 4), pipe.records_in);
}

test "Shard: source reads and pages are freed when dropped: a page for a pipeline not here, and either still in the inbox at stop" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const read: @import("../processing/source_page.zig").Read = .{ .term = a.raft_node.current_term, .seq = 1, .kind = .stream, .key = "gone", .namespace = "default", .source = "s", .from_a = 0, .from_b = 0, .limit = 10 };
    var builder: @import("../processing/source_page.zig").Page.Builder = .{};
    defer builder.deinit(a.allocator);
    try builder.begin(a.allocator, read);
    try builder.record(a.allocator, 1, 0, "x");
    const page = try builder.finish(a.allocator, 1, 0, 0);
    // A page for a pipeline that was removed: dropped, freed.
    try std.testing.expect(a.mailbox.inbox.send(.{ .tag = .source_page, .src_shard = 1, .payload_len = @intCast(page.len), .payload_ptr = page.ptr }));
    _ = a.drainInbox();
    // Both kinds unread at stop: freed.
    const ask = read.encode(b.allocator).?;
    try std.testing.expect(b.mailbox.inbox.send(.{ .tag = .source_read, .src_shard = 0, .payload_len = @intCast(ask.len), .payload_ptr = ask.ptr }));
    var builder2: @import("../processing/source_page.zig").Page.Builder = .{};
    defer builder2.deinit(b.allocator);
    try builder2.begin(b.allocator, read);
    const page2 = try builder2.finish(b.allocator, 0, 0, 0);
    try std.testing.expect(b.mailbox.inbox.send(.{ .tag = .source_page, .src_shard = 0, .payload_len = @intCast(page2.len), .payload_ptr = page2.ptr }));
    b.refuseUnrunRequests();
    try std.testing.expectEqual(@as(usize, 0), b.mailbox.inbox.pending());
}

test "Shard: a start's retry choosing its run id, sent before its namespace is published, is decided on its workflow's shard by the namespace's id" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    // A workflow whose shard is 0 by the namespace's id, and 1 by none.
    const id = nextNamespaceId(a);
    var wbuf: [16]u8 = undefined;
    var i: usize = 0;
    const w = while (true) : (i += 1) {
        const n = try std.fmt.bufPrint(&wbuf, "wf{d}", .{i});
        const by_id = a.router.hashToShard(node_router.routeNsKey(id, n));
        const by_none = a.router.hashToShard(node_router.routeNsKey(.invalid, n));
        if (by_id == 0 and by_none == 1) break n;
    };
    var dbuf: [256]u8 = undefined;
    const def = try std.fmt.bufPrint(&dbuf,
        \\{{"kind":"Workflow","name":"{s}","version":"1.0.0",
        \\"start":{{"wait_for_signal":{{"type":"go"}},"transitions":{{"success":"flo.Completed"}}}}}}
    , .{w});
    // Created on shard 0 with the namespace; applied, not yet published.
    const ca = try TestClient.open(a);
    defer _ = std.c.close(ca.pair[1]);
    a.runRequest(ca.conn, try ParkTest.request(.workflow_create, 1, "wfresh", w, def, ""), .client);
    _ = a.applyCommitted();
    var out: [512]u8 = undefined;
    var resp = try nextAnswer(ca, a, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(two.namespaces.lookup("wfresh") == null);

    // Started there, with its idempotency key and its own run id.
    const both = [_]u8{ 0, 0, 1, 1, 0, 'z', 1, 2, 0, 'r', '1' };
    a.runRequest(ca.conn, try ParkTest.request(.workflow_start, 2, "wfresh", w, &both, ""), .client);
    // Every shard says whether it holds the id; nothing publishes.
    for (0..8) |_| for (&two.shards) |*s| {
        _ = s.drainInbox();
        _ = s.applyCommitted();
    };
    resp = try nextAnswer(ca, a, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expect(a.workflow_handler.holdsRun(id, "r1"));
    try std.testing.expect(two.namespaces.lookup("wfresh") == null);

    // Its retry from shard 1 is the same start, decided on shard 0: the
    // run's holder is its workflow's shard, not another workflow's.
    const cb = try TestClient.open(b);
    defer _ = std.c.close(cb.pair[1]);
    b.runRequest(cb.conn, try ParkTest.request(.workflow_start, 9, "wfresh", w, &both, ""), .client);
    two.settle();
    resp = try nextAnswer(cb, b, &out);
    try std.testing.expectEqual(@as(u64, 9), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    try std.testing.expectError(error.IncompleteResponse, nextAnswer(cb, b, &out));
}

test "Shard: worker.list on a node of two shards lists both shards' workers, in id order and paged" {
    var f: MgetGatherFixture = undefined;
    try f.init(8);
    defer f.deinit();
    const a = &f.two.shards[0];
    // Each registration runs on its worker's shard.
    var name: [8]u8 = undefined;
    for (0..12) |i| {
        const id = try std.fmt.bufPrint(&name, "w{d:0>2}", .{i});
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.worker_register, 100 + i), .namespace = "default", .key = id, .value = "" }, .client);
        f.two.settle();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try f.answer()).header.status);
    }
    try std.testing.expect(f.two.shards[0].worker_handler.workers.count() > 0);
    try std.testing.expect(f.two.shards[1].worker_handler.workers.count() > 0);

    const List = table_run.op("worker.list");
    var body_buf: [List.request.max_size]u8 = undefined;
    var cursor_buf: [64]u8 = undefined;
    var cursor: []const u8 = "";
    var seen: usize = 0;
    var pages: usize = 0;
    while (true) : (pages += 1) {
        const body = try List.request.encodeInto(&body_buf, .{ .limit = 5, .cursor = cursor, .action = "" });
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.worker_list, 200 + pages), .namespace = "default", .key = "", .value = body }, .client);
        f.two.settle();
        const resp = try f.answer();
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
        var diag: schema.Diagnostic = .{};
        const page = try List.response.decodeAll(resp.data, &diag);
        var it = page.workers.iterator();
        while (try it.next()) |w| : (seen += 1) {
            try std.testing.expectEqualStrings(try std.fmt.bufPrint(&name, "w{d:0>2}", .{seen}), w.id);
        }
        const next = page.cursor orelse break;
        // Each page moves the cursor on, so a regression fails, not hangs.
        try std.testing.expect(std.mem.order(u8, next, cursor) == .gt and pages < 12);
        @memcpy(cursor_buf[0..next.len], next);
        cursor = cursor_buf[0..next.len];
    }
    try std.testing.expectEqual(@as(usize, 12), seen);
    try std.testing.expectEqual(@as(usize, 2), pages);
    try f.expectSettled(0);
}

test "Shard: stream.group.members answers the named group's members by id, and a group that isn't there is not found" {
    var f: MgetGatherFixture = undefined;
    try f.init(8);
    defer f.deinit();
    // Each shard holds the group: the request is answered by whichever owns
    // the stream. Its members are the consumers holding its records.
    for (&f.two.shards) |*s| {
        const p = s.defaultPartition();
        for (0..4) |i| try testStreamAppend(p, "s", i + 1, 1, 1);
        // Delivered out of order; listed by id.
        for ([_][]const u8{ "c-9", "c-1", "c-5", "c-3" }, 0..) |id, i| {
            var pb: [ge_mod.Deliver.max_size]u8 = undefined;
            const body = try ge_mod.Deliver.encodeInto(&pb, .{ .ns = 1, .stream = "s", .group = "g", .count = 1, .max_bytes = 1 << 20, .holder = id, .lease_ms = 30_000, .create = true, .ready = .{ .bytes = "", .count = 0 }, .through_ms = std.math.maxInt(u64), .through_seq = std.math.maxInt(u64), .max_held = qe_caps.DEFAULT_MAX_MESSAGES, .max_held_bytes = qe_caps.DEFAULT_MAX_BYTES, .shard_held_bytes = qe_caps.DEFAULT_SHARD_HELD_BYTES });
            const e = entry_mod.buildEntry(.group_deliver, entry_mod.Flags.NONE, 1, 100 + i, 2_000_000, body);
            var out: persistence_mod.Result = .{};
            out.reset(&e);
            try contract_machine.applyEntry(&@import("../stream/group_machine.zig").machine, &p.store, &p.apply_scratch, &e, &out);
            try std.testing.expect(out.refused() == null);
        }
    }
    const a = &f.two.shards[0];
    const Members = table_run.op("stream.group.members");
    var body_buf: [Members.request.max_size]u8 = undefined;
    for ([_][]const u8{ "g", "nope" }, 0..) |group, i| {
        const body = try Members.request.encodeInto(&body_buf, .{ .group = group });
        a.runRequest(f.client.conn, .{ .header = proto.RequestHeader.init(.stream_group_members, 300 + i), .namespace = "default", .key = "s", .value = body }, .client);
        f.two.settle();
        const resp = try f.answer();
        if (i == 1) {
            try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), resp.header.status);
            continue;
        }
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
        var diag: schema.Diagnostic = .{};
        const v = try Members.response.decodeAll(resp.data, &diag);
        var it = v.members.iterator();
        for ([_][]const u8{ "c-1", "c-3", "c-5", "c-9" }) |want| {
            const m = (try it.next()).?;
            try std.testing.expectEqualStrings(want, m.id);
            try std.testing.expectEqual(@as(i64, 2), m.joined_at_ms);
        }
        try std.testing.expect((try it.next()) == null);
        try std.testing.expect(!v.more);
    }
    try f.expectSettled(0);
}

