/// A node that has joined a cluster but leads nothing, with a client: its
/// writes and blocking reads are held for a leader.
const FollowerTest = struct {
    pipe_fds: [2]std.posix.fd_t,
    rn: RaftNetwork,
    shard: Shard,
    pair: [2]std.posix.fd_t,
    conn: *Connection,

    fn init(t: *FollowerTest) !void {
        t.pipe_fds = try @import("stdx").io.pipe();
        t.rn = try RaftNetwork.init(std.testing.allocator, 8, 0, 9000, .{ 127, 0, 0, 1 }, "s");
        t.shard = try Shard.init(std.testing.allocator, 0, 1, t.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 8, .join, .{}, .{});
        t.shard.raft_network = &t.rn;
        t.shard.wireHandlerShardPtrs();
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &t.pair));
        // A test that reads an answer that never comes fails, not hangs.
        try @import("stdx").net.sysFcntlSetNonblocking(t.pair[1]);
        try @import("stdx").net.sysFcntlSetNonblocking(t.pair[0]);
        t.conn = try t.shard.addConnection(t.pair[0]);
    }

    fn deinit(t: *FollowerTest) void {
        _ = std.c.close(t.pair[1]);
        t.shard.deinit();
        t.rn.deinit();
        _ = std.c.close(t.pipe_fds[0]);
        _ = std.c.close(t.pipe_fds[1]);
    }

    fn blockingDequeue(id: u64) ![]u8 {
        var opts: [8]u8 = undefined;
        var ob = proto.OptionsBuilder.init(&opts);
        try ob.addU32(.block_ms, 60_000);
        return testRequestWith(.queue_dequeue, id, "q", "", ob.getOptions());
    }
};

test "Shard: a start leaves its run to step on every replica; the leader logs its step once while it may apply" {
    const start = [_]u8{ 2, 0, 'w', 'f', 1, 0, '1', 1 } ++ [_]u8{ 0, 0, 0, 0, 0 };
    var pbuf: [128]u8 = undefined;
    const e = entry_mod.buildCommandEntry(.workflow_start, 0, 1, 1, 0, .default, wf_test_key(.default, "r1"), &start, &pbuf).?;

    // A follower applies the run and keeps no index of it: the leader
    // builds its own from the store (`WorkflowHandler.leadCaches`).
    var t: FollowerTest = undefined;
    try t.init();
    defer t.deinit();
    try std.testing.expect(t.shard.raft_node.role != .leader);
    var out = persistence_mod.Result.start(&e);
    try std.testing.expect(t.shard.applyEntry(&e, &out));
    try std.testing.expect(t.shard.workflow_handler.appliedRun(wf_test_key(.default, "r1")) != null);
    try std.testing.expectEqual(@as(u32, 0), t.shard.workflow_handler.to_step.count());
    try std.testing.expectEqual(@as(u32, 0), t.shard.workflow_handler.stepping.count());

    // The leader of a group of one.
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const r = shard.raft_node;
    const next = r.last_applied + 1;
    const led = entry_mod.buildCommandEntry(.workflow_start, 0, r.current_term, next, 0, .default, wf_test_key(.default, "r1"), &start, &pbuf).?;
    out = persistence_mod.Result.start(&led);
    try std.testing.expect(shard.applyEntry(&led, &out));
    const wf = shard.workflow_handler;
    try std.testing.expect(wf.to_step.contains(wf_test_key(.default, "r1")));
    // Its step logged: not taken again while that may apply.
    wf.advanceStartedRuns(&shard);
    try std.testing.expectEqual(@as(?u64, 0), wf.stepping.get(wf_test_key(.default, "r1")));
    const logged = r.log.lastIndex();
    wf.advanceStartedRuns(&shard);
    try std.testing.expectEqual(logged, r.log.lastIndex());
}

test "Shard: a run whose leader stepped down before its first step takes it when a leader is next ready" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    const def =
        \\{"kind":"Workflow","name":"wf","version":"1","start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 1, "wf", def);

    // Started, then this leader stepped down before taking its first step,
    // and leads again in a later term.
    try ParkTest.send(&shard, conn, .workflow_start, 2, "wf", "");
    var key_buf: [64]u8 = undefined;
    const key = blk: {
        var it = shard.workflow_handler.to_step.keyIterator();
        const k = it.next().?.*;
        @memcpy(key_buf[0..k.len], k);
        break :blk key_buf[0..k.len];
    };
    const run = shard.workflow_handler.inspect(key).?;
    try std.testing.expectEqual(WorkflowHandler.RunStatus.running, run.status);
    shard.replica.leadershipLost("test");
    const r = shard.raft_node;
    r.role = .leader;
    r.current_term += 1;
    r.ready_index = r.log.lastIndex();

    // Step-down cleared the caches; the tick builds them for the new term.
    try std.testing.expect(!shard.workflow_handler.to_step.contains(key));
    shard.workflow_handler.leadCaches(r.current_term);
    shard.runStepping();
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, shard.workflow_handler.inspect(key).?.status);
    try std.testing.expect(!shard.workflow_handler.to_step.contains(key));
}

test "Shard: a workflow create whose trigger names its own namespace says so in its entry, and one naming another doesn't" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    const head = "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1\",\"trigger\":{\"stream\":\"events\",\"namespace\":\"";
    const tail = "\"},\"start\":{\"wait_for_signal\":{\"type\":\"go\"},\"transitions\":{\"success\":\"flo.Completed\"}}}";
    for ([_][]const u8{ "default", "other" }, [_]u16{ entry_mod.Flags.OWN_NAMESPACE, entry_mod.Flags.NONE }, 1..) |named, want, id| {
        var buf: [512]u8 = undefined;
        const def = try std.fmt.bufPrint(&buf, "{s}{s}{s}", .{ head, named, tail });
        const from = shard.raft_node.log.lastIndex() + 1;
        try ParkTest.send(&shard, conn, .workflow_create, id, "wf", def);
        const at = entryAt(&shard, .workflow_create, from).?;
        try std.testing.expectEqual(want, shard.raft_node.log.getEntry(at).?.header.flags);
    }
}

test "Shard: a node that stops leading forgets the expire it proposed and the runs it was delivering" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    const actions = shard.actions_handler;

    // Proposed and not yet applied when this node stops leading.
    actions.expiring = 7;
