test "Shard: an idempotency key of any length is scoped to its namespace, a retry with key and run id is the same start, and a run id started twice is refused" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [2048]u8 = undefined;

    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 80, "a", "gate", def, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 81, "b", "gate", def, ""), .client);
    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);

    const keyed = [_]u8{ 0, 0, 1, 3, 0, 'k', 'e', 'y', 0 };
    const named = [_]u8{ 0, 0, 0, 1, 2, 0, 'r', '1' };
    // A retry carrying both its key and its own run id is the same start.
    const both = [_]u8{ 0, 0, 1, 1, 0, 'z', 1, 2, 0, 'r', '2' };
    // A key longer than any fixed buffer is still a key.
    var long: [2 + 1 + 2 + 2000 + 1]u8 = undefined;
    @memset(&long, 'x');
    long[0] = 0;
    long[1] = 0;
    long[2] = 1;
    std.mem.writeInt(u16, long[3..5], 2000, .little);
    long[long.len - 1] = 0;
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 82, "a", "gate", &keyed, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 83, "b", "gate", &keyed, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 84, "a", "gate", &named, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 85, "a", "gate", &named, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 86, "a", "gate", &both, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 87, "a", "gate", &both, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 88, "a", "gate", &long, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 89, "a", "gate", &long, ""), .client);
    try ParkTest.ack(&shard);
    var rs: [8]proto.Response = undefined;
    var big: [4096]u8 = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &big, &rs);
    // One key in two namespaces is two runs.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[1].header.status);
    try std.testing.expect(!std.mem.eql(u8, rs[0].data, rs[1].data));
    // The run id is the first start's; the second is refused.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[2].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), rs[3].header.status);
    // Key and run id together: the retry is answered with the first run.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[5].header.status);
    try std.testing.expectEqualStrings(rs[4].data, rs[5].data);
    // A long key: one run, both answered with it.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[7].header.status);
    try std.testing.expectEqualStrings(rs[6].data, rs[7].data);
    try std.testing.expectEqual(@as(usize, 5), shard.workflow_handler.runCount());

    // A namespace a run key cannot carry (the key is read back up to its
    // first ':') is refused, for a definition and for a start, before
    // anything is proposed.
    const before = shard.raft_node.log.lastIndex();
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 90, "a:b", "gate", def, ""), .client);
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 91, "a:b", "gate", &keyed, ""), .client);
    try ParkTest.responses(&shard, conn, pair[1], &big, &two);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), two[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), two[1].header.status);
    try std.testing.expect(std.mem.startsWith(u8, (try two[1].refused()).message, "invalid namespace name"));
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());
}

test "Shard: concurrent conditional writes are decided in log order: one run per idempotency key, one create per namespace, one version per register" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [2048]u8 = undefined;

    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(&shard, conn, .workflow_create, 70, "gate", def);
    try ParkTest.ack(&shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);

    // Each pair passes its handler's check before the other applies.
    const start = [_]u8{ 0, 0, 1, 3, 0, 'k', 'e', 'y', 0 };
    try ParkTest.send(&shard, conn, .workflow_start, 71, "gate", &start);
    try ParkTest.send(&shard, conn, .workflow_start, 72, "gate", &start);
    try ParkTest.send(&shard, conn, .namespace_create, 73, "team", "");
    try ParkTest.send(&shard, conn, .namespace_create, 74, "team", "");
    try ParkTest.send(&shard, conn, .action_register, 75, "act", "");
    try ParkTest.send(&shard, conn, .action_register, 76, "act", "");
    // The creates aren't parked writes: the first waits for its publish,
    // and the second finds the name being created.
    try std.testing.expectEqual(@as(u32, 4), shard.pending_count);
    try ParkTest.ack(&shard);
    shard.namespace_handler.settle(&shard);

    var got: [6]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &got);
    // In request order, whatever order they were answered in.
    var rs: [6]proto.Response = undefined;
    for (got) |r| rs[r.header.request_id - 71] = r;
    // The second start is answered with the first's run, and created none.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[1].header.status);
    try std.testing.expectEqualStrings(rs[0].data, rs[1].data);
    try std.testing.expectEqual(@as(usize, 1), shard.workflow_handler.runCount());
    try std.testing.expectEqual(@as(u32, 1), shard.workflow_handler.to_step.count());
    // The second create finds the namespace being created.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[2].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), rs[3].header.status);
    // Two registers are two versions.
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), rs[5].header.status);
    try std.testing.expectEqual(@as(?u32, 2), ActionsHandler.for_tests.version(&shard, .default, "act"));
}

test "Shard: park answers from its own entry when a later one has already committed" {
    try parkAnswersFromOwnEntry(false);
}

test "Shard: park answers from its own entry when the later one is a millisecond on" {
    try parkAnswersFromOwnEntry(true);
}

/// `apart` sleeps between the two appends, so they are stamped in different
/// milliseconds and both have sequence 0: the records differ only by
/// timestamp.
fn parkAnswersFromOwnEntry(apart: bool) !void {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // On a single node both appends commit as they are proposed; the second
    // stands for another thread's proposal landing before this write parks.
    // The first write is answered from the first's result.
    const Seen = struct {
        var index: u64 = 0;
        var id: ?StreamID = null;
        fn respond(_: *Shard, _: *Connection, _: u64, result: *const persistence_mod.Result) void {
            index = result.index;
            var r = result.reader();
            const seq = r.int(u64) orelse return;
            id = .{ .sequence = seq, .timestamp_ms = r.int(u64) orelse return };
        }
    };
    Seen.id = null;
    var vb: [64]u8 = undefined;
    const v = stream_mod.appendValueOf(&vb, 1, 1);
    const first = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    if (apart) @import("stdx").time.sleep(2 * std.time.ns_per_ms);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    shard.park(conn, try ParkTest.request(.stream_append, 50, "", "s", "a", ""), first, Seen.respond);
    try std.testing.expectEqual(first.index, Seen.index);
    // The dispatch that parked applies the rest; the second record is not
    // the one the first write was answered with. A record is named by its
    // whole ID: the sequence alone restarts each millisecond.
    try std.testing.expect(shard.applyCommitted());
    const hash = stream_mod.streamKey(.default, "s");
    const first_id = shard.stream_handler.stream.streamFirstId(hash);
    const last_id = shard.stream_handler.stream.streamLastId(hash);
    try std.testing.expect(Seen.id.?.eql(first_id));
    try std.testing.expect(!Seen.id.?.eql(last_id));
    if (apart) {
        try std.testing.expectEqual(@as(u64, 0), first_id.sequence);
        try std.testing.expectEqual(@as(u64, 0), last_id.sequence);
    }
}

/// A lone shard with a small hot ring and a warm store that keeps almost
/// nothing, holding one-record appends to stream "s", each followed by
/// `filler` appends to stream "f".
const ColdStream = struct {
    tmp: std.testing.TmpDir,
    data_dir: []const u8,
    pipe_fds: [2]i32,
    shard: Shard,
    value: []u8,

    fn init(self: *ColdStream, durability: Durability, appends: usize, filler: usize, flush_every: usize) !void {
        self.tmp = std.testing.tmpDir(.{});
        self.data_dir = try testDataDir(&self.tmp);
        self.pipe_fds = try @import("stdx").io.pipe();
        self.shard = try Shard.init(std.testing.allocator, 0, 1, self.pipe_fds[0], self.data_dir, 64 * 1024, 0, 0, durability, 1, .single, .{}, .{});
        // Each flush its own sealed segment, as the bulk thread reads them.
        self.shard.durable_log.?.max_segment_bytes = 1;
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        self.shard.defaultPartition().setWarmBudget(4096);
        // One record per append: [count][len][payload][header_count].
        var batch: [4 + 4 + 2048 + 2]u8 = undefined;
        std.mem.writeInt(u32, batch[0..4], 1, .little);
        std.mem.writeInt(u32, batch[4..8], 2048, .little);
        @memset(batch[8 .. 8 + 2048], 'r');
        std.mem.writeInt(u16, batch[8 + 2048 ..][0..2], 0, .little);
        self.value = try stream_mod.encodeAppendValue(std.testing.allocator, 0, &batch);
        for (0..appends) |i| {
            _ = try persistence_mod.proposeEntry(&self.shard, .stream_append, entry_mod.Flags.NONE, "", "s", self.value);
            for (0..filler) |_| _ = try persistence_mod.proposeEntry(&self.shard, .stream_append, entry_mod.Flags.NONE, "", "f", self.value);
            try std.testing.expect(self.shard.applyCommitted());
            if (flush_every > 0 and i % flush_every == flush_every - 1) try self.shard.flushSegmentToDisk();
        }
        if (flush_every > 0) try self.shard.flushSegmentToDisk();
    }

    fn deinit(self: *ColdStream) void {
        self.shard.deinit();
        std.testing.allocator.free(self.value);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
        std.testing.allocator.free(self.data_dir);
        self.tmp.cleanup();
    }

    fn window(limit: u32) waiter_pool_mod.StreamWindow {
        return .{ .stream = stream_mod.streamKey(.default, "s"), .limit = limit };
    }

    /// Read `w`, landing disk reads and reading again while it is held, as
    /// the shard's tick and a held read's wake do.
    fn read(self: *ColdStream, w: *waiter_pool_mod.StreamWindow, buf: *[StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord) !struct { []stream_mod.StreamRecord, @import("../protocol/result.zig").CommandResult } {
        const handler = self.shard.stream_handler;
        for (0..5_000) |_| {
            const records, const result = handler.readReadable(w, buf);
            if (result != .pending) return .{ records, result };
            if (handler.held == .blocked) return error.Blocked;
            var waited: usize = 0;
            while (!self.shard.stream_disk.?.drain()) : (waited += 1) {
                if (waited == 2_000) return error.NeverLanded;
                @import("stdx").time.sleep(std.time.ns_per_ms);
            }
        }
        return error.NeverServed;
    }
};

test "Shard: a stream record past the hot ring and the warm store is read back from its segment" {
    var c: ColdStream = undefined;
    // Async durability, flushed every 10 appends: segments of 10. (Under sync
    // each commit seals a segment of its own.)
    try c.init(.async_flush, 100, 0, 10);
    defer c.deinit();
    // From the start: held once, then every record, the first ones from the
    // durable log, none skipped.
    var w = ColdStream.window(10);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    const records, const result = try c.read(&w, &buf);
    defer c.shard.stream_handler.freeResult(result);
    try std.testing.expectEqual(@as(usize, 10), records.len);
    try std.testing.expectEqual(@as(u32, 10), std.mem.readInt(u32, result.stream_messages.data[0..4], .little));
    try std.testing.expectEqual(@as(u64, 0), c.shard.stream_handler.skipped_appends);
    // The first record's tier byte says disk: after the count, sequence
    // and timestamp.
    try std.testing.expectEqual(@backingInt(proto.StorageTier.disk), result.stream_messages.data[4 + 8 + 8]);
}

test "Shard: a stream record past the warm store but not yet flushed is read from the writer's buffer, not skipped" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 100, 0, 0);
    defer c.deinit();
    // Under async durability a burst outruns the flush: nothing is sealed.
    try std.testing.expect(c.shard.durable_log.?.writer.entry_count > 0);
    var w = ColdStream.window(10);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    const records, const result = try c.read(&w, &buf);
    defer c.shard.stream_handler.freeResult(result);
    try std.testing.expectEqual(@as(usize, 10), records.len);
    try std.testing.expectEqual(@as(u64, 0), c.shard.stream_handler.skipped_appends);
    try std.testing.expectEqual(@backingInt(proto.StorageTier.disk), result.stream_messages.data[4 + 8 + 8]);
}

test "Shard: a cold walk of a stream interleaved with another reads every record, a run per read, none skipped" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 300, 2, 20);
    defer c.deinit();
    var bulk = try BulkIo.init(std.testing.allocator);
    defer bulk.deinit();
    try bulk.start();
    c.shard.attachBulkIo(&bulk);
    c.shard.stream_disk.?.setOwner();
    defer bulk.stop();
    const handler = c.shard.stream_handler;
    var w = ColdStream.window(100);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    var served: usize = 0;
    while (served < 300) {
        const records, const result = try c.read(&w, &buf);
        defer handler.freeResult(result);
        if (records.len == 0) break;
        served += std.mem.readInt(u32, result.stream_messages.data[0..4], .little);
        w.after = stream_mod.lastRecordOf(records[records.len - 1]);
    }
    try std.testing.expectEqual(@as(usize, 300), served);
    try std.testing.expectEqual(@as(u64, 0), handler.skipped_appends);
    // A read lands a run of the asking stream's window: far fewer reads
    // than records, the filler stream's entries never cached.
    const reads = c.shard.stream_disk.?.reads_made;
    std.debug.print("cold walk: {d} records in {d} reads\n", .{ served, reads });
    try std.testing.expect(reads > 0 and reads * 10 <= served);
}

/// A group request on `c`, sent again while it is refused retryable, with
/// the shard's disk reads landed between tries; the answer in `buf`. Up to
/// 10 s: past the pins (5 s) that may hold a full cache.
fn untilServed(c: *ColdStream, conn: *Connection, fd: std.posix.fd_t, buf: []u8, op: proto.OpCode, id: u64, value: []const u8, options: []const u8) !proto.Response {
    for (0..2_000) |_| {
        c.shard.runRequest(conn, try ParkTest.request(op, id, "", "s", value, options), .client);
        // A group read's delivery is logged: answered once it applies.
        _ = c.shard.applyCommitted();
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&c.shard, conn, fd, buf, &one);
        if (one[0].header.status != @backingInt(proto.StatusCode.unavailable)) return one[0];
        _ = c.shard.stream_disk.?.drain();
        @import("stdx").time.sleep(5 * std.time.ns_per_ms);
    }
    return error.NeverServed;
}

test "Shard: a group answer tells a record on its way back from disk from one it can't read" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 60, 0, 10);
    defer c.deinit();
    var all: [60]stream_mod.StreamRecord = undefined;
    const name_hash = stream_mod.streamKey(.default, "s");
    try std.testing.expectEqual(@as(usize, 60), c.shard.stream_handler.stream.readStreamAfter(name_hash, StreamID.MIN, null, &all));
    // The first is past the hot ring and the warm store; the last is hot;
    // the third id is no append of the stream.
    const ids = [_]StreamID{ all[0].id, all[59].id, .{ .timestamp_ms = 1, .sequence = 0 } };
    var unread: [3]StreamHandler.Unread = undefined;
    const body = try c.shard.stream_handler.serializeGroupRecords(name_hash, 1, 1, 1, &ids, &.{ 1, 1, 1 }, &unread);
    defer c.shard.stream_handler.allocator.free(body);
    try std.testing.expectEqual(StreamHandler.Unread.fetching, unread[0]);
    try std.testing.expectEqual(StreamHandler.Unread.read, unread[1]);
    try std.testing.expectEqual(StreamHandler.Unread.lost, unread[2]);
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, body[24..28], .little));
}

test "Shard: a cold group read delivers only what its reply carries" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 60, 0, 10);
    defer c.deinit();
    const d = c.shard.stream_disk.?;
    // Small, so a landing holds a few records: replies are true prefixes,
    // and served ones are evicted.
    d.cache_budget = 4096;
    var all: [60]stream_mod.StreamRecord = undefined;
    const name_hash = stream_mod.streamKey(.default, "s");
    try std.testing.expectEqual(@as(usize, 60), c.shard.stream_handler.stream.readStreamAfter(name_hash, StreamID.MIN, null, &all));

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    // Room for a whole answer: flushing one into a full socket waits on a
    // reader that only reads once the flush returns.
    const room: c_int = 1 << 20;
    _ = std.c.setsockopt(pair[0], std.c.SOL.SOCKET, std.c.SO.SNDBUF, std.mem.asBytes(&room), @sizeOf(c_int));
    _ = std.c.setsockopt(pair[1], std.c.SOL.SOCKET, std.c.SO.RCVBUF, std.mem.asBytes(&room), @sizeOf(c_int));
    const conn = try c.shard.addConnection(pair[0]);
    var buf: [1 << 18]u8 = undefined;
    var ob_buf: [16]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&ob_buf);
    try ob.addU32(.count, 20);
    const c1 = "\x01\x00" ++ "g" ++ "\x02\x00" ++ "c1";

    // Each group read delivers what its reply carries, a prefix, and the
    // next one starts right after it: nothing delivered past the reply.
    var delivered: usize = 0;
    var id: u64 = 1;
    while (delivered < 30) : (id += 1) {
        const r = try untilServed(&c, conn, pair[1], &buf, .stream_group_read, id, c1, ob.getOptions());
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), r.header.status);
        // [term][index][expires_at_ms][count] then the records.
        const n = std.mem.readInt(u32, r.data[24..28], .little);
        try std.testing.expect(n > 0 and n < 20);
        try std.testing.expectEqual(all[delivered].id.sequence, std.mem.readInt(u64, r.data[28..36], .little));
        try std.testing.expectEqual(all[delivered].id.timestamp_ms, std.mem.readInt(u64, r.data[36..44], .little));
        delivered += n;
    }
    try std.testing.expect(!d.cache.contains(all[0].ual_index));
    // What was delivered is exactly what replies carried: leased, no more.
    var mk: [4 + 16]u8 = undefined;
    const scope = @import("../stream/group_machine.zig").scopeOf(.default, "s", "g");
    const read: @import("../contract/view.zig").ReadView = .{ .store = &c.shard.defaultPartition().store };
    const meta = (try read.get(@import("../stream/group_machine.zig").Metas, @import("../stream/group_machine.zig").storeKey(&mk, .default, &scope))).?.v;
    try std.testing.expectEqual(@as(u64, delivered), meta.leased);
}

test "Shard: a stream read of a corrupt sealed segment takes the shard offline, and /status says why" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 100, 0, 10);
    defer c.deinit();
    // A byte flipped in the first sealed segment, past its header.
    const seg = (try c.shard.durable_log.?.segments())[0].path;
    const bytes = try DamageTest.readFile(seg);
    defer std.testing.allocator.free(bytes);
    bytes[bytes.len - 8] ^= 0xff;
    try DamageTest.writeFile(seg, bytes);

    var w = ColdStream.window(10);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    _ = c.shard.stream_handler.readReadable(&w, &buf);
    _ = c.shard.stream_disk.?.drain();
    // Damage, as boot and apply report it: offline on a lone node, counted.
    const damage = c.shard.offline orelse return error.ShardNotOffline;
    try std.testing.expectEqual(silent_loss.Path.segment_unreadable, damage.path);
    try std.testing.expectEqual(@as(u64, 1), c.shard.losses.total(.segment_unreadable));
    var slot: health_mod.ShardSlot = .{};
    c.shard.health = &slot;
    c.shard.publishHealth();
    try std.testing.expect(std.mem.indexOf(u8, slot.reason().?, "corrupt") != null);
}

test "Shard: a read held on a disk read that finds the log damaged is refused with the damage, not answered with records past it" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 100, 0, 10);
    defer c.deinit();
    const seg = (try c.shard.durable_log.?.segments())[0].path;
    const bytes = try DamageTest.readFile(seg);
    defer std.testing.allocator.free(bytes);
    bytes[bytes.len - 8] ^= 0xff;
    try DamageTest.writeFile(seg, bytes);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try c.shard.addConnection(pair[0]);
    // From the start, past the hot ring: held on the disk read.
    var ob_buf: [32]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&ob_buf);
    try ob.addStreamId(.stream_start, 0, 0);
    try ob.addU32(.count, 5);
    c.shard.runRequest(conn, try ParkTest.request(.stream_read, 7, "", "s", "", ob.getOptions()), .client);
    try std.testing.expectEqual(@as(u16, 1), c.shard.waiter_pool.countByKind(.stream_disk_read));
    // The read finds the segment corrupt: the shard is damaged, and the held
    // read is told so.
    _ = c.shard.stream_disk.?.drain();
    try std.testing.expect(c.shard.offline != null);
    try std.testing.expectEqual(@as(u16, 0), c.shard.waiter_pool.countByKind(.stream_disk_read));
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&c.shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 7), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), one[0].header.status);
    try std.testing.expect(std.mem.indexOf(u8, one[0].data, "damaged") != null);
    // And nothing more is read from the log.
    try std.testing.expect(c.shard.stream_disk.?.stopped);
}

test "Shard: a stream read whose disk read is blocked is refused at once, not held" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 100, 0, 10);
    defer c.deinit();
    c.shard.durable_log.?.test_open_error = error.SystemResources;
    var w = ColdStream.window(10);
    var buf: [StreamHandler.MAX_READ_BATCH]stream_mod.StreamRecord = undefined;
    try std.testing.expectError(error.Blocked, c.read(&w, &buf));
    // Backing off: asked again at once, it is still blocked, with no read.
    _, const again = c.shard.stream_handler.readReadable(&w, &buf);
    try std.testing.expect(again == .pending and c.shard.stream_handler.held == .blocked);
}

test "Shard: a run's history read that meets a blocked disk read stops, answered retryable, never as lost" {
    var c: ColdStream = undefined;
    try c.init(.async_flush, 0, 0, 0);
    defer c.deinit();
    const he = @import("../protocol/history_entries.zig");
    const s = &c.shard;
    var buf: [he.Chunk.max_size]u8 = undefined;
    const p = try he.Chunk.encodeInto(&buf, .{ .ns = ns_table.DEFAULT.int(), .family = @backingInt(he.Family.action), .owner = "act", .run = "r1", .created_ns = 3, .first_seq = 1, .last_seq = 2, .final = true, .completed_ms = 77, .records = "events" });
    try sendFromApplyFlagged(s, @intCast(node_router.nsKeySlot(.default, "act")), .history_chunk, entry_mod.Flags.HISTORY, p);
    // Its frames to itself come through its own inbox.
    for (0..8) |_| {
        s.tickChannels();
        _ = s.drainInbox();
        _ = s.applyCommitted();
    }
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const landed = try s.stream_handler.readHistory(arena.allocator(), .action, .default, "act", "r1", 3, 77, .{}, 10, std.math.maxInt(usize));
    try std.testing.expectEqual(@as(usize, 1), landed.pieces.len);
    // Pushed out of the ring and the warm store, onto disk only.
    for (0..80) |_| {
        _ = try persistence_mod.proposeEntry(s, .stream_append, entry_mod.Flags.NONE, "", "f", c.value);
        try std.testing.expect(s.applyCommitted());
    }
    try s.flushSegmentToDisk();
    // The disk can't be read now: the read stops before the chunk, to be
    // tried again, and says nothing of it as lost.
    s.durable_log.?.test_open_error = error.SystemResources;
    // Asked for, its read fails; asked again, it is held back.
    var held = try s.stream_handler.readHistory(arena.allocator(), .action, .default, "act", "r1", 3, 77, .{}, 10, std.math.maxInt(usize));
    var tries: usize = 0;
    while (s.stream_handler.held != .blocked and tries < 2_000) : (tries += 1) {
        try std.testing.expect(held.pending);
        _ = s.stream_disk.?.drain();
        @import("stdx").time.sleep(std.time.ns_per_ms);
        held = try s.stream_handler.readHistory(arena.allocator(), .action, .default, "act", "r1", 3, 77, .{}, 10, std.math.maxInt(usize));
    }
    try std.testing.expect(s.stream_handler.held == .blocked);
    try std.testing.expect(held.pending);
    try std.testing.expectEqual(@as(usize, 0), held.pieces.len);
}

test "Shard: an internal op from a client is answered as an unknown one, and nothing is proposed" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [256]u8 = undefined;
    var one: [1]proto.Response = undefined;

    const last = shard.raft_node.log.lastIndex();
    // namespace.ensure would create the namespace; from a client it is no op at all.
    try ParkTest.send(&shard, conn, .namespace_ensure, 1, "fresh", "");
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), one[0].header.status);
    const r = try one[0].refused();
    try std.testing.expectEqual(proto.Reason.unknown_op, r.reason);
    try std.testing.expectEqualStrings("unknown op 0x16", r.message);
    // The admin socket is a client's socket too.
    shard.runRequest(conn, try ParkTest.request(.namespace_ensure, 2, proto.DEFAULT_NAMESPACE, "fresh", "", ""), .admin);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), one[0].header.status);
    try std.testing.expectEqualStrings("unknown op 0x16", (try one[0].refused()).message);
    try std.testing.expectEqual(last, shard.raft_node.log.lastIndex());
    try std.testing.expect(!shard.namespace_handler.known("fresh"));
}

test "Shard: a stream's first append to a namespace nobody created is listed under that namespace" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);

    // The append is stamped with its namespace's id and listed under it, so
    // the namespace's create must apply first, here and on every replay.
    shard.runRequest(conn, try ParkTest.request(.stream_append, 40, "fresh", "s", "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "a" ++ "\x00\x00", ""), .client);
    try ParkTest.ack(&shard);
    var buf: [256]u8 = undefined;
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const read: view_mod.ReadView = .{ .store = &shard.defaultPartition().store };
    try std.testing.expect(shard.namespaceId("fresh") != .invalid);
    try std.testing.expect(stream_machine.metaOf(read, shard.namespaceId("fresh"), "s") != null);
    try std.testing.expect(stream_machine.metaOf(read, .default, "s") == null);
}

test "Shard: a blocking stream read wakes on its own namespace's append, even one proposed before it parked, and returns only what is past its cursor" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;

    // An append's value is a batch: [count:u32]([len:u32][payload][header_count:u16])*
    const first = "\x01\x00\x00\x00" ++ "\x0c\x00\x00\x00" ++ "first-record" ++ "\x00\x00";
    const second = "\x01\x00\x00\x00" ++ "\x0d\x00\x00\x00" ++ "second-record" ++ "\x00\x00";
    // The other namespace exists, by a write to another of its streams: a
    // read of one never created is answered at once that it isn't.
    shard.runRequest(conn, try ParkTest.request(.stream_append, 9, "other", "elsewhere", first, ""), .client);
    try ParkTest.ack(&shard);
    var created: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &created);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), created[0].header.status);
    shard.runRequest(conn, try ParkTest.request(.stream_append, 1, "app", "s", first, ""), .client);
    try ParkTest.ack(&shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    const cursor_seq = std.mem.readInt(u64, one[0].data[0..8], .little);
    const cursor_ms = std.mem.readInt(u64, one[0].data[8..16], .little);

    // Proposed, not yet applied, when the read parks: the read finds
    // nothing and must still wake when this applies.
    shard.runRequest(conn, try ParkTest.request(.stream_append, 2, "app", "s", second, ""), .client);

    var opts_buf: [64]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&opts_buf);
    try ob.addStreamId(.stream_start, cursor_ms, cursor_seq);
    try ob.addU32(.block_ms, 5000);
    shard.runRequest(conn, try ParkTest.request(.stream_read, 3, "app", "s", "", ob.getOptions()), .client);
    // The same stream name in another namespace has nothing to wake it.
    var other_buf: [64]u8 = undefined;
    var other = proto.OptionsBuilder.init(&other_buf);
    try other.addU32(.block_ms, 5000);
    shard.runRequest(conn, try ParkTest.request(.stream_read, 4, "other", "s", "", other.getOptions()), .client);
    try std.testing.expectEqual(@as(u16, 2), shard.waiter_pool.countByKind(.stream_read));

    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    const read = if (two[0].header.request_id == 3) two[0] else two[1];
    try std.testing.expectEqual(@as(u64, 3), read.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), read.header.status);
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, read.data[0..4], .little));
    try std.testing.expect(std.mem.indexOf(u8, read.data, "second-record") != null);
    try std.testing.expect(std.mem.indexOf(u8, read.data, "first-record") == null);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_read));
}

test "Shard: a blocking read on one partition skips other partitions' appends without rescanning them, and wakes on its own" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;
    const other = "\x01\x00\x00\x00" ++ "\x0b\x00\x00\x00" ++ "other-part1" ++ "\x00\x00";
    const mine = "\x01\x00\x00\x00" ++ "\x0a\x00\x00\x00" ++ "mine-part2" ++ "\x00\x00";

    var read_buf: [64]u8 = undefined;
    var ro = proto.OptionsBuilder.init(&read_buf);
    try ro.addU32(.partition, 2);
    try ro.addU32(.block_ms, 5000);
    shard.runRequest(conn, try ParkTest.request(.stream_read, 1, "", "s", "", ro.getOptions()), .client);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_read));

    var p1_buf: [16]u8 = undefined;
    var p1 = proto.OptionsBuilder.init(&p1_buf);
    try p1.addU32(.partition, 1);
    shard.runRequest(conn, try ParkTest.request(.stream_append, 2, "", "s", other, p1.getOptions()), .client);
    try ParkTest.ack(&shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    // Still parked, with its cursor at the last id it scanned.
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_read));
    const scanned = shard.stream_handler.stream.streamLastId(shard.waiter_pool.waiters[0].stream.stream);
    try std.testing.expect(shard.waiter_pool.waiters[0].stream.after.eql(scanned));

    var p2_buf: [16]u8 = undefined;
    var p2 = proto.OptionsBuilder.init(&p2_buf);
    try p2.addU32(.partition, 2);
    shard.runRequest(conn, try ParkTest.request(.stream_append, 3, "", "s", mine, p2.getOptions()), .client);
    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    const read = if (two[0].header.request_id == 1) two[0] else two[1];
    try std.testing.expectEqual(@as(u64, 1), read.header.request_id);
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, read.data[0..4], .little));
    try std.testing.expect(std.mem.indexOf(u8, read.data, "mine-part2") != null);
    try std.testing.expectEqual(@as(u16, 0), shard.waiter_pool.countByKind(.stream_read));
}

test "Shard: a blocking group read wakes on its own namespace's append, not a same-named stream elsewhere" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;
    const rec = "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "r" ++ "\x00\x00";
    // [group_len:u16][group][consumer_len:u16][consumer]
    const group_consumer = "\x01\x00" ++ "g" ++ "\x01\x00" ++ "c";

    var ob_buf: [16]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&ob_buf);
    try ob.addU32(.block_ms, 5000);
    // Both namespaces exist: a wait in one never created is refused.
    for ([_][]const u8{ "app", "other" }) |ns| {
        _ = shard.namespace_handler.applyCreate(ns);
    }
    shard.runRequest(conn, try ParkTest.request(.stream_group_read, 1, "app", "s", group_consumer, ob.getOptions()), .client);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_group_read));

    shard.runRequest(conn, try ParkTest.request(.stream_append, 2, "other", "s", rec, ""), .client);
    try ParkTest.ack(&shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_group_read));

    shard.runRequest(conn, try ParkTest.request(.stream_append, 3, "app", "s", rec, ""), .client);
    try ParkTest.ack(&shard);
    // The woken read proposed its deliver; answered when it commits.
    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    try std.testing.expect(two[0].header.request_id == 1 or two[1].header.request_id == 1);
    try std.testing.expectEqual(@as(u16, 0), shard.waiter_pool.countByKind(.stream_group_read));
}

test "Shard: a group follows its stream's real trim and delete: a deliver after the trim takes only what's left, and after the delete its group is gone" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    // Not the default namespace: a trim names its stream under the entry's id.
    _ = shard.namespace_handler.applyCreate("app");

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const group_consumer = "\x01\x00" ++ "g" ++ "\x01\x00" ++ "c";
    var id: u64 = 1;
    inline for (.{ "a", "b", "c" }) |p| {
        const rec = "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ p ++ "\x00\x00";
        shard.runRequest(conn, try ParkTest.request(.stream_append, id, "app", "s", rec, ""), .client);
        id += 1;
        try ParkTest.ack(&shard);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    }
    // c holds "a".
    var count_buf: [16]u8 = undefined;
    var count = proto.OptionsBuilder.init(&count_buf);
    try count.addU32(.count, 10);
    var first_buf: [16]u8 = undefined;
    var first = proto.OptionsBuilder.init(&first_buf);
    try first.addU32(.count, 1);
    shard.runRequest(conn, try ParkTest.request(.stream_group_read, id, "app", "s", group_consumer, first.getOptions()), .client);
    id += 1;
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, one[0].data[24..28], .little));

    // The stream handler's own trim, keeping one: "a" and "b" go.
    var trim_buf: [16]u8 = undefined;
    var trim = proto.OptionsBuilder.init(&trim_buf);
    try trim.addU64(.limit, 1);
    shard.runRequest(conn, try ParkTest.request(.stream_trim, id, "app", "s", "", trim.getOptions()), .client);
    id += 1;
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const gm = @import("../stream/group_machine.zig");
    const ns = shard.namespace_handler.idOf("app").?;
    const sk = gm.streamOf(ns, "s");
    try std.testing.expect(gm.floorOf(group_handler.streamRecOf(&shard, sk)).eql(shard.stream_handler.stream.streamRemovedThrough(sk)));
    try std.testing.expect(!gm.floorOf(group_handler.streamRecOf(&shard, sk)).eql(StreamID.MIN));

    // A deliver now takes "c" alone: not "b", which the trim cut.
    shard.runRequest(conn, try ParkTest.request(.stream_group_read, id, "app", "s", group_consumer, count.getOptions()), .client);
    id += 1;
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, one[0].data[24..28], .little));
    // [term][index][expires][count], then [seq:u64][ts:i64][tier:u8]
    // [partition:u32][key_present:u8][payload_len:u32][payload].
    const at = 28 + 8 + 8 + 1 + 4 + 1;
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, one[0].data[at..][0..4], .little));
    try std.testing.expectEqualStrings("c", one[0].data[at + 4 ..][0..1]);

    // The handler's own delete, forced: the group's stream moves on a
    // generation, so the group is gone.
    var del_buf: [16]u8 = undefined;
    var del = proto.OptionsBuilder.init(&del_buf);
    try del.addFlag(.force);
    shard.runRequest(conn, try ParkTest.request(.stream_delete, id, "app", "s", "", del.getOptions()), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqual(@as(u64, 1), group_handler.streamRecOf(&shard, sk).gen);
    try std.testing.expect(group_handler.metaOf(&shard, ns, "s", "g") == null);
}

test "Shard: a nack wakes a parked group read, and the next read serves the nacked record" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);

    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const rec = "\x01\x00\x00\x00" ++ "\x01\x00\x00\x00" ++ "r" ++ "\x00\x00";
    const group_consumer = "\x01\x00" ++ "g" ++ "\x01\x00" ++ "c";

    shard.runRequest(conn, try ParkTest.request(.stream_append, 1, "app", "s", rec, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    // A read is answered once its deliver commits.
    shard.runRequest(conn, try ParkTest.request(.stream_group_read, 2, "app", "s", group_consumer, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    const got = one[0].data;
    try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, got[24..28], .little));
    try std.testing.expect(std.mem.indexOf(u8, got, "r") != null);
    const term = std.mem.readInt(u64, got[0..8], .little);
    const index = std.mem.readInt(u64, got[8..16], .little);
    const seq = std.mem.readInt(u64, got[28..36], .little);
    const ms = std.mem.readInt(u64, got[36..44], .little);

    // Nothing new: the next read parks.
    var ob_buf: [16]u8 = undefined;
    var ob = proto.OptionsBuilder.init(&ob_buf);
    try ob.addU32(.block_ms, 5000);
    shard.runRequest(conn, try ParkTest.request(.stream_group_read, 3, "app", "s", group_consumer, ob.getOptions()), .client);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.stream_group_read));

    // The consumer nacks what it got, by its delivery: the parked read is
    // woken, and takes it again.
    var nack: [128]u8 = undefined;
    @memcpy(nack[0..group_consumer.len], group_consumer);
    var off: usize = group_consumer.len;
    std.mem.writeInt(u64, nack[off..][0..8], term, .little);
    std.mem.writeInt(u64, nack[off + 8 ..][0..8], index, .little);
    std.mem.writeInt(u32, nack[off + 16 ..][0..4], 1, .little);
    std.mem.writeInt(u64, nack[off + 20 ..][0..8], ms, .little);
    std.mem.writeInt(u64, nack[off + 28 ..][0..8], seq, .little);
    std.mem.writeInt(u32, nack[off + 36 ..][0..4], 1, .little);
    // No error: [error_len:u16] 0.
    std.mem.writeInt(u16, nack[off + 40 ..][0..2], 0, .little);
    off += 42;
    shard.runRequest(conn, try ParkTest.request(.stream_group_nack, 4, "app", "s", nack[0..off], ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.ack(&shard);
    var two: [2]proto.Response = undefined;
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    try std.testing.expectEqual(@as(u16, 0), shard.waiter_pool.countByKind(.stream_group_read));
    for (two) |r| {
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), r.header.status);
        if (r.header.request_id == 4) try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, r.data[0..4], .little));
        if (r.header.request_id == 3) {
            // The nacked record, delivered a second time.
            try std.testing.expectEqual(@as(u32, 1), std.mem.readInt(u32, r.data[24..28], .little));
            try std.testing.expect(std.mem.indexOf(u8, r.data, "r") != null);
            try std.testing.expectEqual(@as(u32, 2), std.mem.readInt(u32, r.data[r.data.len - 4 ..][0..4], .little));
        }
    }
}

