test "Shard: with sync durability, entries after one the writer could not buffer reach disk once each, in order" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());

    // An empty buffer with no room: buffering the next entry allocates,
    // and that allocation fails. The one after it is appended before any
    // flush, as a follower appends a batch.
    const writer = s.shard.durable_log.?.writer;
    try std.testing.expectEqual(@as(u32, 0), writer.entry_count);
    writer.data.clearAndFree(writer.allocator);
    writer.sparse_index.clearAndFree(writer.allocator);
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    const first = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k1", "v");
    writer.allocator = real;
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);

    s.shard.syncFlushIfNeeded();
    try std.testing.expectEqual(first.index + 1, s.shard.raft_node.durable_index);
    var got: [4]entry_mod.Entry = undefined;
    var arena: [256]u8 = undefined;
    try std.testing.expectEqual(@as(usize, 2), s.shard.durable_log.?.readRange(first.index, &got, &arena).count);
    try std.testing.expectEqual(first.index, got[0].header.index);
    try std.testing.expectEqual(first.index + 1, got[1].header.index);
}

test "Shard: in sync mode a buffer-failure run holds behind the gap and ends once rebuffering catches up" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());

    // Empty the buffer and fail the next growth, as the sync-durability test above.
    const writer = s.shard.durable_log.?.writer;
    writer.data.clearAndFree(writer.allocator);
    writer.sparse_index.clearAndFree(writer.allocator);
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k1", "v");
    writer.allocator = real;
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);
    // The run started. Behind the gap the append hook returns early, so the
    // next entry does not clear it — it holds until rebuffering catches up.
    try std.testing.expect(writer.buffer_failing_since_ms != 0);
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    try std.testing.expect(writer.buffer_failing_since_ms != 0);

    // The sync flush rebuffers the gap, ending the run; the count stays.
    s.shard.syncFlushIfNeeded();
    try std.testing.expect(writer.first_unbuffered == null);
    try std.testing.expectEqual(@as(u64, 0), writer.buffer_failing_since_ms);
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);
}

test "Shard: with sync durability, an entry that left memory before reaching disk stops the shard's writes, by name" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: SyncAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k1", &buf)).getStatus());

    // The hook could not buffer k2, and the ring evicted it before the
    // flush: it is nowhere.
    const writer = s.shard.durable_log.?.writer;
    writer.first_unbuffered = s.shard.raft_node.log.lastIndex() + 1;
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    _ = s.shard.raft_node.log.ual.evictOlderThan(std.math.maxInt(u64));

    const lost = try s.put(3, "k3", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, lost.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, lost.data, "lost when the node restarts") != null);
    try std.testing.expect(s.shard.raft_node.writes_stopped);

    // The next write is refused before it reaches the log.
    const last = s.shard.raft_node.log.lastIndex();
    const refused = try s.put(4, "k4", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, refused.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, refused.data, "stopped taking writes") != null);
    try std.testing.expectEqual(last, s.shard.raft_node.log.lastIndex());
}

const GapAlone = struct {
    data_dir: []const u8,
    pipe_fds: [2]i32,
    pair: [2]std.posix.fd_t,
    shard: Shard,
    conn: *Connection,

    fn init(self: *GapAlone, tmp: *std.testing.TmpDir) !void {
        self.data_dir = try testDataDir(tmp);
        self.pipe_fds = try @import("stdx").io.pipe();
        // Bounds off (0/0): only the staging-gap path is under test here.
        self.shard = try Shard.init(std.testing.allocator, 0, 1, self.pipe_fds[0], self.data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        self.shard.wireHandlerShardPtrs();
        try std.testing.expect(self.shard.applyCommitted());
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &self.pair));
        self.conn = try self.shard.addConnection(self.pair[0]);
    }

    fn deinit(self: *GapAlone) void {
        self.shard.deinit();
        _ = std.c.close(self.pair[1]);
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
        std.testing.allocator.free(self.data_dir);
    }

    /// Flush what is buffered to disk and drop the writer's spare capacity, so
    /// the very next append must allocate — and the next `openGap` can fail it.
    fn settleEmpty(self: *GapAlone) !void {
        try self.shard.flushSegmentToDisk();
        const writer = self.shard.durable_log.?.writer;
        writer.data.clearAndFree(writer.allocator);
        writer.sparse_index.clearAndFree(writer.allocator);
    }

    /// Send a put whose append cannot be staged for disk (its allocation
    /// fails), opening a gap. Caller has already `settleEmpty`.
    fn openGap(self: *GapAlone, id: u64, key: []const u8) !void {
        const writer = self.shard.durable_log.?.writer;
        const real = writer.allocator;
        var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
        writer.allocator = failing.allocator();
        try ParkTest.send(&self.shard, self.conn, .kv_put, id, key, "v");
        writer.allocator = real;
        _ = self.shard.applyCommitted();
    }

    fn put(self: *GapAlone, id: u64, key: []const u8, buf: []u8) !proto.Response {
        try ParkTest.send(&self.shard, self.conn, .kv_put, id, key, "v");
        _ = self.shard.applyCommitted();
        var r: [1]proto.Response = undefined;
        try ParkTest.responses(&self.shard, self.conn, self.pair[1], buf, &r);
        return r[0];
    }

    fn reply(self: *GapAlone, buf: []u8) !proto.Response {
        _ = self.shard.applyCommitted();
        var r: [1]proto.Response = undefined;
        try ParkTest.responses(&self.shard, self.conn, self.pair[1], buf, &r);
        return r[0];
    }
};

test "Shard: alone with async_flush, a write that can't be staged for disk is held, not acked, then acked once it is re-staged" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: GapAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;

    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());
    try s.settleEmpty();
    try s.openGap(2, "k1");

    // The entry is a gap: its write is held (not answered), it is not applied,
    // and the shard reports the stall like a failed flush would.
    const writer = s.shard.durable_log.?.writer;
    try std.testing.expect(writer.first_unbuffered != null);
    try std.testing.expect(s.conn.response_deferred);
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k1") == null);
    try std.testing.expect(s.shard.asyncBoundCrossed() == .gap);
    try std.testing.expectEqual(health_mod.ShardState.cannot_flush, s.shard.healthState());
    try std.testing.expect(writer.gap_open_since_ms != 0);

    // The flush re-stages the entry from the log, clearing the gap; the held
    // write is then answered, once, and the value is present.
    try s.shard.flushSegmentToDisk();
    try std.testing.expect(writer.first_unbuffered == null);
    try std.testing.expectEqual(@as(u64, 0), writer.gap_open_since_ms);
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.reply(&buf)).getStatus());
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k1") != null);
    try std.testing.expectEqual(health_mod.ShardState.ok, s.shard.healthState());

    // A later write lands once, as normal.
    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(3, "k2", &buf)).getStatus());
    try std.testing.expect(s.shard.kv_handler.kv.getIn(.default, "k2") != null);
}

test "Shard: alone with async_flush, a held write whose entry leaves memory before disk is told it is lost, and writes stop" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: GapAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;

    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());
    try s.settleEmpty();
    try s.openGap(2, "k1");
    try std.testing.expect(s.conn.response_deferred);

    // The gap entry is evicted from the log before it could be re-staged: it is
    // nowhere, so the shard stops writes and the held write is told it is lost.
    _ = s.shard.raft_node.log.ual.evictOlderThan(std.math.maxInt(u64));
    s.shard.flushSegmentToDisk() catch {};
    try std.testing.expect(s.shard.raft_node.writes_stopped);
    const lost = try s.reply(&buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, lost.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, lost.data, "lost when the node restarts") != null);

    // A new write is refused before it reaches the log.
    const last = s.shard.raft_node.log.lastIndex();
    const refused = try s.put(3, "k3", &buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, refused.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, refused.data, "stopped taking writes") != null);
    try std.testing.expectEqual(last, s.shard.raft_node.log.lastIndex());

    // writes_stopped is permanent, so admission keeps deferring to it even once
    // flushing has been failing past the time bound — it never flips back to a
    // transient "retry". And a follower still withholds its ack (gapHeld stays
    // true), since the gap entry must never count toward commit on a node whose
    // disk it can't reach.
    s.shard.async_flush_bound_ms = 3000;
    s.shard.flushes_failing_since_ms = Shard.nowMs() -| 5000; // well past the bound
    try std.testing.expect(s.shard.asyncBoundCrossed() == .none);
    try std.testing.expect(s.shard.gapHeld());
}

test "Shard: in a cluster with async_flush, a held write whose entry is evicted may still apply, so it is not told it is lost" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: GapAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;

    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());
    try s.settleEmpty();
    try s.openGap(2, "k1");
    try std.testing.expect(s.conn.response_deferred);

    // A voter peer: this node is no longer alone. The evicted entry may still
    // hold and commit on that peer, so a blind resend would apply it twice — the
    // held write is told it may still apply and to check before resending, not
    // that it is lost (which the alone case says).
    s.shard.raft_node.addPeer(2);
    try std.testing.expect(s.shard.raft_node.voterPeers() > 0);
    _ = s.shard.raft_node.log.ual.evictOlderThan(std.math.maxInt(u64));
    s.shard.flushSegmentToDisk() catch {};
    try std.testing.expect(s.shard.raft_node.writes_stopped);
    const held = try s.reply(&buf);
    try std.testing.expectEqual(proto.StatusCode.unavailable, held.getStatus());
    try std.testing.expect(std.mem.indexOf(u8, held.data, "check before resending") != null);
    try std.testing.expect(std.mem.indexOf(u8, held.data, "lost when the node restarts") == null);
}

test "Shard: alone with async_flush, a gap held open never lets channelDurable pass the flushed tip" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var s: GapAlone = undefined;
    try s.init(&tmp);
    defer s.deinit();
    var buf: [1024]u8 = undefined;

    try std.testing.expectEqual(proto.StatusCode.ok, (try s.put(1, "k0", &buf)).getStatus());
    try s.settleEmpty(); // k0 on disk; the flushed tip is at k0.
    const durable_before = s.shard.channelDurable();

    try s.openGap(2, "k1");
    const gap_at = s.shard.durable_log.?.writer.first_unbuffered.?;
    // The flushed tip a channel delivers against must sit before the gap.
    try std.testing.expect(s.shard.channelDurable() < gap_at);
    try std.testing.expectEqual(durable_before, s.shard.channelDurable());

    // Writes commit behind the gap (held by the apply-hold, never staged).
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k2", "v");
    _ = try kv_handler_mod.KVHandler.testProposePut(&s.shard, "k3", "v");
    _ = s.shard.applyCommitted();

    // A flush that can't re-stage the gap must not advance the flushed tip:
    // channelDurable stays put, so a channel trims no further than disk holds.
    const writer = s.shard.durable_log.?.writer;
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    s.shard.flushSegmentToDisk() catch {};
    writer.allocator = real;
    try std.testing.expect(s.shard.channelDurable() < gap_at);
    try std.testing.expectEqual(durable_before, s.shard.channelDurable());

    // Healed: the flush re-stages from the gap and the tip advances past it.
    try s.shard.flushSegmentToDisk();
    try std.testing.expect(writer.first_unbuffered == null);
    try std.testing.expect(s.shard.channelDurable() >= gap_at);
}

test "Shard: a trigger moved to another stream and back goes on from its logged place, live and after a restart alike" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const on = struct {
        fn def(comptime stream: []const u8) []const u8 {
            return "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1.0.0\",\"trigger\":{\"stream\":\"" ++ stream ++ "\"},\"start\":{\"wait_for_signal\":{\"type\":\"never\"},\"transitions\":{\"success\":\"flo.Completed\"}}}";
        }
    };
    const key = wf_test_key(.default, "wf");
    var cursor_at: StreamID = undefined;
    {
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        try std.testing.expect(shard.applyCommitted());
        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);
        try ParkTest.send(&shard, conn, .workflow_create, 1, "wf", on.def("events"));
        _ = shard.applyCommitted();
        for (0..3) |k| {
            var pbuf: [16]u8 = undefined;
            _ = try shard.stream_handler.appendPayloadToStream("events", "default", try std.fmt.bufPrint(&pbuf, "ev-{d}", .{k}));
        }
        _ = shard.applyCommitted();
        shard.workflow_handler.triggers_dirty = true;
        shard.workflow_handler.tickStreamTriggers(&shard);
        _ = shard.applyCommitted();
        try std.testing.expectEqual(@as(usize, 3), shard.workflow_handler.runCount());
        const at = shard.workflow_handler.triggerCursor(key, .default);
        try std.testing.expect(at.timestamp_ms != 0);
        // Moved to another stream, then back, with no start between them:
        // the place is still in this stream.
        try ParkTest.send(&shard, conn, .workflow_create, 2, "wf", on.def("other"));
        _ = shard.applyCommitted();
        try ParkTest.send(&shard, conn, .workflow_create, 3, "wf", on.def("events"));
        _ = shard.applyCommitted();
        try std.testing.expect(shard.workflow_handler.triggerCursor(key, .default).eql(at));
        // Polled again: nothing it took already starts again.
        shard.workflow_handler.triggers_dirty = true;
        shard.workflow_handler.tickStreamTriggers(&shard);
        _ = shard.applyCommitted();
        try std.testing.expectEqual(@as(usize, 3), shard.workflow_handler.runCount());
        try shard.flushSegmentToDisk();
        cursor_at = at;
    }
    var again = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer again.deinit();
    again.wireHandlerShardPtrs();
    _ = again.applyCommitted();
    try std.testing.expectEqual(@as(usize, 3), again.workflow_handler.runCount());
    // Its trigger is built from the store once it leads, as its first tick
    // does.
    again.workflow_handler.leadCaches(again.raft_node.current_term);
    try std.testing.expect(again.workflow_handler.triggerCursor(key, .default).eql(cursor_at));
}

test "Shard: a node keeps its workflow caches only while it leads: built from the store in each term, cleared when it stops" {
    // A follower applies a start and indexes nothing; leading, it builds the
    // index from the store.
    {
        const start = [_]u8{ 2, 0, 'w', 'f', 1, 0, '1', 1 } ++ [_]u8{ 0, 0, 0, 0, 0 };
        var pbuf: [128]u8 = undefined;
        const e = entry_mod.buildCommandEntry(.workflow_start, 0, 1, 1, 0, .default, wf_test_key(.default, "r1"), &start, &pbuf).?;
        var t: FollowerTest = undefined;
        try t.init();
        defer t.deinit();
        var out = persistence_mod.Result.start(&e);
        try std.testing.expect(t.shard.applyEntry(&e, &out));
        const h = t.shard.workflow_handler;
        try std.testing.expectEqual(@as(u32, 0), h.to_step.count());
        h.leadCaches(7);
        try std.testing.expect(h.to_step.contains(wf_test_key(.default, "r1")));
        // Again in the same term: nothing changes.
        h.leadCaches(7);
        try std.testing.expectEqual(@as(u32, 1), h.to_step.count());
    }

    // A leader with a stream trigger: stopping drops it, and the node's
    // count of triggers with it; the next term builds it again.
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    const def = "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1.0.0\",\"trigger\":{\"stream\":\"events\"},\"start\":{\"wait_for_signal\":{\"type\":\"never\"},\"transitions\":{\"success\":\"flo.Completed\"}}}";
    try ParkTest.send(&shard, conn, .workflow_create, 1, "wf", def);
    _ = shard.applyCommitted();
    const h = shard.workflow_handler;
    const term = shard.raft_node.current_term;
    h.leadCaches(term);
    try std.testing.expectEqual(@as(u32, 1), h.stream_triggers.count());
    const triggers = WorkflowHandler.streamTriggerCount();
    shard.stoppedLeading("test");
    try std.testing.expectEqual(@as(u32, 0), h.stream_triggers.count());
    try std.testing.expectEqual(@as(u32, 0), h.to_step.count());
    try std.testing.expectEqual(triggers - 1, WorkflowHandler.streamTriggerCount());
    h.leadCaches(term + 1);
    try std.testing.expectEqual(@as(u32, 1), h.stream_triggers.count());
    try std.testing.expectEqual(triggers, WorkflowHandler.streamTriggerCount());
}

test "Shard: a leader that built its workflow caches while halted keeps what applies after the repair, and steps it once ready" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const h = shard.workflow_handler;
    const term = shard.raft_node.current_term;

    // Halted, it leads and holds its duties: its caches are built then, as
    // its first tick in the term does (`leads or holds`), over what applied.
    shard.halted = .{ .index = 1, .term = term, .crc = 0 };
    h.leadCaches(term);
    try std.testing.expectEqual(@as(u32, 0), h.to_step.count());

    // Repaired in the same term: a run that waits on nothing, one parked on
    // a call, one on a timer, all applied after the rebuild.
    shard.halted = null;
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    try ParkTest.send(&shard, conn, .workflow_create, 1, "wf", "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1.0.0\",\"start\":{\"wait_for_signal\":{\"type\":\"never\"},\"transitions\":{\"success\":\"flo.Completed\"}}}");
    var vb: [96]u8 = undefined;
    const start = (@import("../workflow/runs_machine.zig").Start{ .workflow = "wf", .version = "1", .status = .running, .event = "", .idem = null, .input = "" }).encode(&vb).?;
    _ = try persistence_mod.proposeEntryIn(&shard, .workflow_start, entry_mod.Flags.NONE, .default, wf_test_key(.default, "r1"), start);
    try proposeCall(&shard, "act", "wf", "a1", false);
    _ = try persistence_mod.proposeEntryIn(&shard, .workflow_start, entry_mod.Flags.NONE, .default, wf_test_key(.default, "r3"), start);
    const runs_machine = @import("../workflow/runs_machine.zig");
    // Applied, so the timer's step names the run's incarnation.
    _ = shard.applyCommitted();
    const timer: runs_machine.Step.Value = .{
        .created_ns = runs_machine.runOf(.{ .store = &shard.defaultPartition().store }, wf_test_key(.default, "r3")).?.created_ns,
        .rev = 0,
        .step = "s",
        .events = .{ .bytes = "", .count = 0 },
        .outputs = .{ .bytes = "", .count = 0 },
        .wait = .timer,
        .wait_kind = .action,
        .wait_slot = 0,
        .wait_on = "",
        .wait_due_ms = std.math.maxInt(i32),
        .wait_timeout_to = "",
        .progress = "",
        .settles = "",
        .takes = .{ .bytes = "", .count = 0 },
        .caller_slot = 0,
        .workflow = "wf",
        .ends = 0,
        .has_output = false,
        .output = "",
        .call = "",
    };
    var sb: [512]u8 = undefined;
    _ = try persistence_mod.proposeEntryIn(&shard, .workflow_step, entry_mod.Flags.NONE, .default, wf_test_key(.default, "r3"), try runs_machine.Step.encodeInto(&sb, timer));
    try std.testing.expect(shard.applyCommitted());

    // Each is in its cache, though the rebuild ran before it applied.
    try std.testing.expect(h.to_step.contains(wf_test_key(.default, "r1")));
    try std.testing.expect(h.parked.contains(wf_test_key(.default, "c-a1")));
    try std.testing.expect(h.timers.count() > 0);
    // Ready in the same term: no second rebuild, and the run steps.
    h.leadCaches(term);
    try std.testing.expect(h.to_step.contains(wf_test_key(.default, "r1")));
    const before = shard.raft_node.log.lastIndex();
    h.advanceStartedRuns(&shard);
    try std.testing.expect(shard.raft_node.log.lastIndex() > before);
}

test "Shard: a namespace create is published, and answered, only once its segment and directory are on disk" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    {
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        try std.testing.expect(shard.applyCommitted());
        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);

        shard.runRequest(conn, try ParkTest.request(.namespace_create, 1, "", "orders", "", ""), .client);
        _ = shard.applyCommitted();
        const nh = shard.namespace_handler;
        // Applied, so shard 0 knows it; not on disk, so nothing else does,
        // and its client waits.
        try std.testing.expect(nh.known("orders"));
        try std.testing.expect(nh.table.lookup("orders") == null);
        try std.testing.expect(conn.response_deferred);

        const syncs = @import("stdx").fs.dir_syncs.load(.monotonic);
        nh.settle(&shard);
        // The flush synced the segment directory before the table moved.
        try std.testing.expect(@import("stdx").fs.dir_syncs.load(.monotonic) > syncs);
        const id = nh.table.lookup("orders").?;
        try std.testing.expectEqual(@import("../namespace/table.zig").FIRST_ALLOCATED, id);
        var buf: [256]u8 = undefined;
        var one: [1]proto.Response = undefined;
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    }
    // A restart publishes it from its segment, under the same id, with no
    // flush owed.
    var again = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer again.deinit();
    again.wireHandlerShardPtrs();
    _ = again.applyCommitted();
    again.namespace_handler.settle(&again);
    try std.testing.expectEqual(@as(?ns_table.Id, ns_table.FIRST_ALLOCATED), again.namespace_handler.table.lookup("orders"));
    try std.testing.expectEqual(ns_table.FIRST_ALLOCATED.int() + 1, again.namespace_handler.nextId());
}

test "Shard: a restart puts every namespace its log created in the table before any request runs" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const N = 40;
    var name_buf: [16]u8 = undefined;
    var last_index: u64 = 0;
    {
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        try std.testing.expect(shard.applyCommitted());
        var pair: [2]std.posix.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
        defer _ = std.c.close(pair[1]);
        const conn = try shard.addConnection(pair[0]);
        for (0..N) |i| {
            shard.runRequest(conn, try ParkTest.request(.namespace_create, @intCast(i + 1), "", try std.fmt.bufPrint(&name_buf, "ns{d}", .{i}), "", ""), .client);
            _ = shard.applyCommitted();
        }
        shard.namespace_handler.settle(&shard);
        try std.testing.expectEqual(@as(u32, N + 1), shard.namespace_handler.live());
        last_index = shard.namespace_handler.table.publishedIndex();
    }
    var again = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer again.deinit();
    again.wireHandlerShardPtrs();
    const nh = again.namespace_handler;
    // Replayed into the store, so shard 0 knows them; the table waits for
    // the boot step every node runs before its shards start.
    try std.testing.expectEqual(@as(u32, N + 1), nh.live());
    try std.testing.expect(nh.table.lookup("ns0") == null);
    try raiseNamespaceIdFloor((&again)[0..1]);
    for (0..N) |i| {
        const name = try std.fmt.bufPrint(&name_buf, "ns{d}", .{i});
        try std.testing.expectEqual(nh.idOf(name), nh.table.lookup(name));
        try std.testing.expectEqualStrings(name, nh.table.nameOf(nh.idOf(name).?).?);
    }
    try std.testing.expectEqual(last_index, nh.table.publishedIndex());
    try std.testing.expectEqual(ns_table.FIRST_ALLOCATED.int() + N, nh.nextId());
    // Nothing is published twice at the first settle.
    nh.settle(&again);
    try std.testing.expect(!nh.publish_from_store);
}

test "Shard: until shard 0 publishes a namespace, another shard's write to it waits for shard 0 rather than running under no id" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    // Applied on shard 0, as boot replay leaves a create: in its store, not
    // yet in the table.
    const id: ns_table.Id = .of(a.namespace_handler.nextId());
    try std.testing.expectEqual(.created, a.namespace_handler.applyCreateAt("orders", id, 1, 1));
    try std.testing.expect(a.namespace_handler.prepareWrite(a, "orders") == .go);
    try std.testing.expect(b.namespace_handler.prepareWrite(b, "orders") == .ensure);
    try std.testing.expectEqual(ns_table.INVALID, b.forwardedNamespaceId("orders"));
    try raiseNamespaceIdFloor(&two.shards);
    try std.testing.expect(b.namespace_handler.prepareWrite(b, "orders") == .go);
    try std.testing.expectEqual(id, b.forwardedNamespaceId("orders"));
}

test "Shard: a second create of a name being created waits for the first, and is never told it exists when it doesn't" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [512]u8 = undefined;
    var two: [2]proto.Response = undefined;

    // The first create's outcome never comes: this node stops leading.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 1, "", "team", "", ""), .client);
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 2, "", "team", "", ""), .client);
    try std.testing.expect(conn.response_deferred);
    shard.namespace_handler.forgetImplicitCreates(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    for (two) |r| try std.testing.expectEqual(@backingInt(proto.StatusCode.unavailable), r.header.status);

    // A node leads again only in a new term, ready once it has applied
    // what it proposed before: the late "team" create among them. So the
    // next create's id is past it.
    try ParkTest.ack(&shard);
    shard.namespace_handler.settle(&shard);
    // This time it applies: the first made it, the second finds it there.
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 3, "", "crew", "", ""), .client);
    shard.runRequest(conn, try ParkTest.request(.namespace_create, 4, "", "crew", "", ""), .client);
    for (0..2) |_| {
        try ParkTest.ack(&shard);
        shard.namespace_handler.settle(&shard);
    }
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    var by_id: [2]proto.Response = undefined;
    for (two) |r| by_id[r.header.request_id - 3] = r;
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), by_id[0].header.status);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.conflict), by_id[1].header.status);
}

test "Shard: with async durability, an entry the writer could not buffer opens a gap and holds; a flush re-stages it and what follows" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try shard.flushSegmentToDisk();

    // Async acks before disk, so a hole would be acked-but-lost. Async now holds
    // at the gap exactly as sync does: the entry that failed to stage is kept,
    // and nothing after it buffers until a flush re-stages from the gap.
    const writer = shard.durable_log.?.writer;
    writer.data.clearAndFree(writer.allocator);
    writer.sparse_index.clearAndFree(writer.allocator);
    const real = writer.allocator;
    var failing = std.testing.FailingAllocator.init(real, .{ .fail_index = 0 });
    writer.allocator = failing.allocator();
    const first = try kv_handler_mod.KVHandler.testProposePut(&shard, "k1", "v");
    writer.allocator = real;
    _ = try kv_handler_mod.KVHandler.testProposePut(&shard, "k2", "v");
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures);
    try std.testing.expectEqual(first.index, writer.first_unbuffered);
    try std.testing.expect(writer.gap_open_since_ms != 0);
    try std.testing.expectEqual(@as(u32, 0), writer.entry_count); // nothing buffered past the gap
    try std.testing.expectEqual(health_mod.ShardState.cannot_flush, shard.healthState());

    // The flush re-stages from the gap: the held entry and the one after it both
    // reach disk once each, in order; the gap clears and health recovers.
    try shard.flushSegmentToDisk();
    try std.testing.expect(writer.first_unbuffered == null);
    try std.testing.expectEqual(@as(u64, 0), writer.gap_open_since_ms);
    try std.testing.expectEqual(@as(u64, 1), writer.buffer_failures); // the count stays
    try std.testing.expectEqual(health_mod.ShardState.ok, shard.healthState());
    var got: [4]entry_mod.Entry = undefined;
    var arena: [256]u8 = undefined;
    try std.testing.expectEqual(@as(usize, 2), shard.durable_log.?.readRange(first.index, &got, &arena).count);
    try std.testing.expectEqual(first.index, got[0].header.index);
    try std.testing.expectEqual(first.index + 1, got[1].header.index);
}

test "shard: a forwarded request parsed without its options trailer re-serializes whole" {
    const payload = [_]u8{ 0, 0, 2, 0, 'k', '0', 0, 0, 0, 0 };
    var header = proto.RequestHeader.init(.kv_exists, 5);
    header.payload_length = payload.len;
    header.crc32 = header.computeCRC32(&payload);
    var frame: [@sizeOf(proto.RequestHeader) + payload.len]u8 = undefined;
    @memcpy(frame[0..@sizeOf(proto.RequestHeader)], std.mem.asBytes(&header));
    @memcpy(frame[@sizeOf(proto.RequestHeader)..], &payload);
    const req = try proto.Request.parse(&frame);

    const wire = try Shard.serializeRequest(std.testing.allocator, req);
    defer std.testing.allocator.free(wire);
    const again = try proto.Request.parse(wire);
    try std.testing.expectEqualStrings("k0", again.key);
    try std.testing.expectEqual(@as(u64, 5), again.header.request_id);
    try std.testing.expectEqual(@as(usize, 0), again.options.len);
}

test "Shard: an await that claims a pending run at once gets exactly one answer, carrying the run" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    var out: [4096]u8 = undefined;

    // Register the action, then invoke it: one pending run.
    // invoke value: [priority:u8][delay_ms:i64][has_caller:u8][has_idem:u8][has_labels:u8][input]
    const invoke_value: []const u8 = "\x00job-input";
    for ([_]struct { op: proto.OpCode, id: u64, value: []const u8 }{
        .{ .op = .action_register, .id = 1, .value = "" },
        .{ .op = .action_invoke, .id = 2, .value = invoke_value },
    }) |r| {
        const frame = try testRequest(r.op, r.id, "act", r.value);
        defer std.testing.allocator.free(frame);
        _ = feedClient(c.pair[1], &shard, c.conn.fd, frame);
        _ = shard.applyCommitted();
        const n = try readAnswer(c.pair[1], &shard, c.conn.fd, &out, @sizeOf(proto.ResponseHeader));
        const resp = try proto.Response.parse(out[0..n]);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    }
    try std.testing.expectEqual(@as(c_int, 0), unreadBytes(c.pair[1]));

    // The await takes it: one ok frame with the task once its deliver
    // applies, and nothing after it.
    var await_buf: [64]u8 = undefined;
    const frame = try testRequest(.action_await, 3, "worker-1", try ActionsHandler.for_tests.awaitBody(&await_buf, &.{"act"}, 30_000, null));
    defer std.testing.allocator.free(frame);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, frame);
    _ = shard.applyCommitted();
    const n = try readAnswer(c.pair[1], &shard, c.conn.fd, &out, @sizeOf(proto.ResponseHeader));
    const resp = try proto.Response.parse(out[0..n]);
    try std.testing.expectEqual(@as(u64, 3), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), resp.header.status);
    const task = (try ActionsHandler.for_tests.task(resp.data)).?;
    try std.testing.expectEqualStrings("job-input", task.input);
    try std.testing.expectEqualStrings("act", task.action);
    try std.testing.expectEqual(n, @sizeOf(proto.ResponseHeader) + resp.data.len);
    shard.flushToClient(c.conn.fd);
    try std.testing.expectEqual(@as(c_int, 0), unreadBytes(c.pair[1]));
}

/// One leading shard and a client, for the action ops: each call is fed,
/// applied (twice: an await's deliver applies after its proposal), and its
/// answer read.
const ActionsTest = struct {
    pipe_fds: [2]std.posix.fd_t,
    shard: Shard,
    c: TestClient,
    out: [8192]u8 = undefined,
    next_id: u64 = 100,

    fn init(t: *ActionsTest) !void {
        return t.initAs(.single);
    }

    fn initAs(t: *ActionsTest, mode: anytype) !void {
        t.pipe_fds = try @import("stdx").io.pipe();
        t.shard = try Shard.init(std.testing.allocator, 0, 1, t.pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, mode, .{}, .{});
        t.shard.wireHandlerShardPtrs();
        try std.testing.expect(t.shard.applyCommitted());
        t.c = try TestClient.open(&t.shard);
        t.next_id = 100;
    }

    fn deinit(t: *ActionsTest) void {
        _ = std.c.close(t.c.pair[1]);
        t.shard.deinit();
        _ = std.c.close(t.pipe_fds[0]);
        _ = std.c.close(t.pipe_fds[1]);
    }

    /// Fed without reading an answer.
    fn feed(t: *ActionsTest, op: proto.OpCode, key: []const u8, value: []const u8) !void {
        t.next_id += 1;
        const frame = try testRequest(op, t.next_id, key, value);
        defer std.testing.allocator.free(frame);
        _ = feedClient(t.c.pair[1], &t.shard, t.c.conn.fd, frame);
        _ = t.shard.applyCommitted();
        _ = t.shard.applyCommitted();
    }

    fn call(t: *ActionsTest, op: proto.OpCode, key: []const u8, value: []const u8) !proto.Response {
        try t.feed(op, key, value);
        const resp = try nextAnswer(t.c, &t.shard, &t.out);
        try std.testing.expectEqual(t.next_id, resp.header.request_id);
        return resp;
    }

    fn ok(t: *ActionsTest, op: proto.OpCode, key: []const u8, value: []const u8) !proto.Response {
        const resp = try t.call(op, key, value);
        if (resp.header.status != @backingInt(proto.StatusCode.ok)) {
            std.debug.print("{s} refused: {s}\n", .{ @tagName(op), if (resp.refused()) |r| r.message else |_| "" });
            return error.TestUnexpectedResult;
        }
        return resp;
    }

    /// A task taken by `worker`, or none, waiting `block_ms` at most.
    fn take(t: *ActionsTest, worker: []const u8, action: []const u8, block_ms: u64, request_key: ?[]const u8) !?@import("../protocol/action_ops.zig").Task.Value {
        var b: [256]u8 = undefined;
        const resp = try t.ok(.action_await, worker, try ActionsHandler.for_tests.awaitBody(&b, &.{action}, block_ms, request_key));
        return ActionsHandler.for_tests.task(resp.data);
    }

    fn run(t: *ActionsTest, id: []const u8) action_machine.Run.Value {
        return ActionsHandler.for_tests.run(&t.shard, .default, id).?;
    }
};

test "actions: an await takes a ready run under a new delivery; a complete naming it completes the run, its result and outcome kept; one naming another delivery, or another action, is refused" {
    var t: ActionsTest = undefined;
    try t.init();
    defer t.deinit();
    _ = try t.ok(.action_register, "act", "");
    _ = try t.ok(.action_invoke, "act", "\x00in");
    var task = (try t.take("w1", "act", 0, null)).?;
    try std.testing.expectEqual(@as(u32, 1), task.deliveries);
    try std.testing.expectEqualStrings("in", task.input);
    var run_buf: [64]u8 = undefined;
    const run_id = run_buf[0..task.run.len];
    @memcpy(run_id, task.run);
    task.run = run_id;
    var action_buf: [16]u8 = undefined;
    @memcpy(action_buf[0..3], "act");
    task.action = action_buf[0..3];
    try std.testing.expectEqual(action_machine.Status.leased, t.run(run_id).status);
    try std.testing.expectEqualStrings("w1", t.run(run_id).holder);

    var body: [1024]u8 = undefined;
    var other = task;
    other.deliveries = 2;
    var resp = try t.call(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, other, "w1", "", ""));
    try std.testing.expectEqual(proto.Reason.stale_report, (try resp.refused()).reason);
    other = task;
    other.action = "other";
    resp = try t.call(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, other, "w1", "", ""));
    try std.testing.expectEqual(proto.Reason.not_found, (try resp.refused()).reason);
    // An outcome longer than a workflow branch's name is refused by name:
    // sent as a client with a wider bound would send it.
    const ops_ = @import("../protocol/action_ops.zig");
    const Wide = schema.Record(&.{
        .{ .name = "action", .T = ops_.ActionName },
        .{ .name = "worker", .T = ops_.WorkerId },
        .{ .name = "deliveries", .T = schema.Int(u32) },
        .{ .name = "term", .T = schema.Int(u64) },
        .{ .name = "index", .T = schema.Int(u64) },
        .{ .name = "outcome", .T = schema.Defaulted(schema.Bytes(1024), "") },
        .{ .name = "result", .T = schema.Defaulted(schema.Bytes(ops_.MAX_OUTPUT), "") },
    });
    const long: [ops_.MAX_OUTCOME + 1]u8 = @splat('o');
    var wide: [2048]u8 = undefined;
    resp = try t.call(.action_complete, run_id, try Wide.encodeInto(&wide, .{ .action = "act", .worker = "w1", .deliveries = task.deliveries, .term = task.term, .index = task.index, .outcome = &long, .result = "" }));
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), resp.header.status);
    try std.testing.expect(std.mem.indexOf(u8, (try resp.refused()).message, "outcome") != null);
    try std.testing.expectEqual(action_machine.Status.leased, t.run(run_id).status);

    _ = try t.ok(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, task, "w1", "approved", "out"));
    try std.testing.expectEqual(action_machine.Status.completed, t.run(run_id).status);
    try std.testing.expectEqualStrings("approved", t.run(run_id).outcome);
    try std.testing.expectEqualStrings("out", t.run(run_id).result);
    // A resend is answered as the first was.
    _ = try t.ok(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, task, "w1", "approved", "out"));
}

test "actions: an action run's history reads back whole, a page at a time by its cursor and newest first; its status is a preview with its flag" {
    var t: ActionsTest = undefined;
    try t.init();
    defer t.deinit();
    _ = try t.ok(.action_register, "act", "");
    _ = try t.ok(.action_invoke, "act", "\x00in");
    var task = (try t.take("w1", "act", 0, null)).?;
    var run_buf: [64]u8 = undefined;
    const run_id = run_buf[0..task.run.len];
    @memcpy(run_id, task.run);
    task.run = run_id;
    var action_buf: [16]u8 = undefined;
    @memcpy(action_buf[0..3], "act");
    task.action = action_buf[0..3];
    const result: [300]u8 = @splat('r');
    var body: [1024]u8 = undefined;
    _ = try t.ok(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, task, "w1", "ok", &result));

    var diag: schema.Diagnostic = .{};
    const status = try table_run.op("action.status").response.decodeAll((try t.ok(.action_status, run_id, "")).data, &diag);
    try std.testing.expectEqual(@as(usize, action_machine.PREVIEW), status.output.?.len);
    try std.testing.expect(status.output_truncated);
    try std.testing.expect(!status.error_truncated);

    const R = history_read.Request;
    var rb: [R.max_size]u8 = undefined;
    // Its last chunk is still on the lane: the read is held, then answered
    // once it lands.
    try t.feed(.action_history, run_id, try R.encodeInto(&rb, .{ .limit = 2, .cursor = null, .newest_first = false }));
    try std.testing.expectEqual(@as(u16, 1), t.shard.waiter_pool.countByKind(.history_read));
    try ParkTest.deliverOwn(&t.shard);
    try std.testing.expectEqual(@as(u16, 0), t.shard.waiter_pool.countByKind(.history_read));
    const first = try history_read.Response.decodeAll((try nextAnswer(t.c, &t.shard, &t.out)).data, &diag);
    try std.testing.expectEqual(@as(u32, 2), first.events.count);
    try std.testing.expect(first.has_more);
    const cursor = first.cursor;
    var it = first.events.iterator();
    try std.testing.expectEqualStrings(action_machine.EV_INVOKED, (try it.next()).?.event_type);
    try std.testing.expectEqualStrings(action_machine.EV_DELIVERED, (try it.next()).?.event_type);
    // The rest, from its cursor: the whole result, and its outcome.
    const rest = try history_read.Response.decodeAll((try t.ok(.action_history, run_id, try R.encodeInto(&rb, .{ .limit = 100, .cursor = cursor, .newest_first = false }))).data, &diag);
    try std.testing.expect(!rest.has_more);
    it = rest.events.iterator();
    const settled = (try it.next()).?;
    try std.testing.expectEqualStrings(action_machine.EV_SETTLED, settled.event_type);
    try std.testing.expectEqualSlices(u8, &result, settled.detail);
    try std.testing.expectEqualStrings("ok", settled.extra);
    try std.testing.expectEqualStrings(action_machine.EV_ENDED, (try it.next()).?.event_type);
    // Newest first, one: its end.
    const newest = try history_read.Response.decodeAll((try t.ok(.action_history, run_id, try R.encodeInto(&rb, .{ .limit = 1, .cursor = null, .newest_first = true }))).data, &diag);
    it = newest.events.iterator();
    try std.testing.expectEqualStrings(action_machine.EV_ENDED, (try it.next()).?.event_type);
}

test "actions: a delete of a live run is refused run_live; of an ended one, its status and history then answer not found, a held history read too, and a resend not found" {
    var t: ActionsTest = undefined;
    try t.init();
    defer t.deinit();
    _ = try t.ok(.action_register, "act", "");
    _ = try t.ok(.action_invoke, "act", "\x00in");
    var task = (try t.take("w1", "act", 0, null)).?;
    var run_buf: [64]u8 = undefined;
    const run_id = run_buf[0..task.run.len];
    @memcpy(run_id, task.run);
    task.run = run_id;
    var action_buf: [16]u8 = undefined;
    @memcpy(action_buf[0..3], "act");
    task.action = action_buf[0..3];
    const live = try t.call(.action_run_delete, run_id, "");
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), live.header.status);
    try std.testing.expectEqual(proto.Reason.run_live, (try live.refused()).reason);
    var body: [1024]u8 = undefined;
    _ = try t.ok(.action_complete, run_id, try ActionsHandler.for_tests.completeBody(&body, task, "w1", "", "done"));
    // A history read held while its last chunk is on the lane.
    const R = history_read.Request;
    var rb: [R.max_size]u8 = undefined;
    try t.feed(.action_history, run_id, try R.encodeInto(&rb, .{ .limit = 10, .cursor = null, .newest_first = false }));
    try std.testing.expectEqual(@as(u16, 1), t.shard.waiter_pool.countByKind(.history_read));
    // The delete applies before the chunk lands: the drop follows it on
    // the lane, and the held read is answered not found.
    _ = try t.ok(.action_run_delete, run_id, "");
    try ParkTest.deliverOwn(&t.shard);
    try std.testing.expectEqual(@as(u16, 0), t.shard.waiter_pool.countByKind(.history_read));
    const held = try nextAnswer(t.c, &t.shard, &t.out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), held.header.status);
    for ([_]proto.OpCode{ .action_status, .action_run_delete }) |op| {
        const r = try t.call(op, run_id, "");
        try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), r.header.status);
    }
    const h = try t.call(.action_history, run_id, try R.encodeInto(&rb, .{ .limit = 10, .cursor = null, .newest_first = false }));
    try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), h.header.status);
    try std.testing.expect(ActionsHandler.for_tests.run(&t.shard, .default, run_id) == null);
}

test "actions: an action's runs list newest first by cursor, to the last page; a cursor no run can be at is refused" {
    var t: ActionsTest = undefined;
    try t.init();
    defer t.deinit();
    _ = try t.ok(.action_register, "act", "");
    for (0..3) |_| _ = try t.ok(.action_invoke, "act", "\x00in");
    const Op = table_run.op("action.list_runs");
    var rb: [Op.request.max_size]u8 = undefined;
    var diag: schema.Diagnostic = .{};
    var ids: [3][64]u8 = undefined;
    var lens: [3]usize = undefined;
    var n: usize = 0;
    var after: ?@import("../protocol/action_ops.zig").RunCursor.Value = null;
    var cb: [64]u8 = undefined;
    var pages: usize = 0;
    var prev_at: i64 = std.math.maxInt(i64);
    while (true) : (pages += 1) {
        const page = try Op.response.decodeAll((try t.ok(.action_list_runs, "act", try Op.request.encodeInto(&rb, .{ .limit = 2, .after = after }))).data, &diag);
        var it = page.runs.iterator();
        while (try it.next()) |r| : (n += 1) {
            @memcpy(ids[n][0..r.run.len], r.run);
            lens[n] = r.run.len;
            try std.testing.expectEqual(@import("../protocol/action_ops.zig").RunStatus.pending, r.status);
            // Newest first, then by id: no earlier one comes after.
            if (n > 0) {
                try std.testing.expect(r.created_at_ms <= prev_at);
                if (r.created_at_ms == prev_at) try std.testing.expect(std.mem.order(u8, r.run, ids[n - 1][0..lens[n - 1]]) == .gt);
            }
            prev_at = r.created_at_ms;
        }
        const c = page.cursor orelse break;
        @memcpy(cb[0..c.run.len], c.run);
        after = .{ .created_at_ms = c.created_at_ms, .run = cb[0..c.run.len] };
    }
    try std.testing.expectEqual(@as(usize, 3), n);
    try std.testing.expectEqual(@as(usize, 1), pages);
    // Each once.
    try std.testing.expect(!std.mem.eql(u8, ids[0][0..lens[0]], ids[1][0..lens[1]]));
    try std.testing.expect(!std.mem.eql(u8, ids[1][0..lens[1]], ids[2][0..lens[2]]));
    const bad = try t.call(.action_list_runs, "act", try Op.request.encodeInto(&rb, .{ .limit = 2, .after = .{ .created_at_ms = -1, .run = "r" } }));
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), bad.header.status);
    // With no action named, refused: its runs are on its name's shard.
    const keyless = try t.call(.action_list_runs, "", try Op.request.encodeInto(&rb, .{ .limit = 2, .after = null }));
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), keyless.header.status);
}

test "actions: a direct invoke is refused overloaded, not run, while its namespace's history waits on the lane, and goes once it drains" {
    var t: ActionsTest = undefined;
    try t.init();
    defer t.deinit();
    t.shard.outbox_caps = .{ .other = .{ .shard = 1 << 30, .channel = 400 } };
    _ = try t.ok(.action_register, "act", "");
    // An input over half a chunk goes to the lane as it is invoked, past
    // twice the cap.
    var value: [1 + 3000]u8 = @splat('i');
    value[0] = 0;
    _ = try t.ok(.action_invoke, "act", &value);
    try std.testing.expect(t.shard.historyWait(.default) != null);
    const last = t.shard.raft_node.log.lastIndex();
    const held = try t.call(.action_invoke, "act", &value);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), held.header.status);
    const why = try held.refused();
    try std.testing.expectEqual(proto.Ran.no, why.ran);
    try std.testing.expect(std.mem.indexOf(u8, why.message, "history") != null);
    try std.testing.expectEqual(last, t.shard.raft_node.log.lastIndex());
    try ParkTest.deliverOwn(&t.shard);
    try std.testing.expect(t.shard.historyWait(.default) == null);
    _ = try t.ok(.action_invoke, "act", &value);
}

