    for (0..4) |k| _ = try applyActionEntry(&t.shard, .action_invoke, testInvoke("act", try std.fmt.bufPrint(&run, "r{d}", .{k})), 2 + k, base + k);
    // The first two held, the rest dropped.
    actions.noteDue(base);
    actions.noteDue(base + 1);
