}

test "actions: however awaits, invokes, refusals, step-downs and commits interleave, the leader picks each due run once" {
    var prng = @import("stdx").PRNG.init(0x5E1EC7);
    const r = prng.random();
    const view = @import("../contract/view.zig");
    for (0..8) |_| {
        var t: ClusterActionsTest = undefined;
        try t.init();
        defer t.deinit();
        try t.setUp(&.{ "r0", "r1" }, 0);
        const actions = t.shard.actions_handler;
        const now: u64 = @intCast(@import("stdx").time.nanoTimestamp());
        var name_buf: [16]u8 = undefined;
        var b: [256]u8 = undefined;
        var store_index: u64 = 100;
        var invoked: u64 = 2;
        var most: usize = 0;
        var refused: u32 = 0;
        var agains: u32 = 0;
        for (0..300) |step| {
            store_index += 1;
            switch (r.uintLessThan(u8, 20)) {
                // A run, as an applied invoke leaves it: most due at once,
                // some not for an hour.
                0...3 => {
                    const later = r.uintLessThan(u8, 4) == 0;
                    _ = try applyActionEntry(&t.shard, .action_invoke, testInvoke("act", try std.fmt.bufPrint(&name_buf, "r{d}", .{invoked})), store_index, if (later) now + std.time.ns_per_hour else 1);
                    invoked += 1;
                },
                // An await from one of a few workers, now and then with a
                // request key; its deliver stays in flight until the ack.
                4...12 => {
                    var wb: [8]u8 = undefined;
                    const worker = try std.fmt.bufPrint(&wb, "w{d}", .{r.uintLessThan(u8, 6)});
                    var kb: [4]u8 = undefined;
                    const key: ?[]const u8 = if (r.uintLessThan(u8, 3) == 0) try std.fmt.bufPrint(&kb, "k{d}", .{r.uintLessThan(u8, 2)}) else null;
                    // A key whose delivery its worker still holds is given
                    // that delivery again, not a new one.
                    var held = false;
                    if (key) |k| {
                        var rb: [64]u8 = undefined;
                        var sk: [128]u8 = undefined;
                        const rec_key = try view.idKey(&sk, .default, action_machine.requestKey(&rb, worker, k));
                        if (t.shard.defaultPartition().store.get(action_machine.Requests.ID, rec_key)) |bytes| {
                            const rec = (try action_machine.Requests.Value.decode(bytes)).v;
                            if (ActionsHandler.for_tests.run(&t.shard, .default, rec.run)) |run| held = run.status == .leased and run.token.term == rec.term and run.token.index == rec.index;
                        }
                    }
                    const before = actions.pending.items.len;
                    try ParkTest.send(&t.shard, t.c.conn, .action_await, 1000 + step, worker, try ActionsHandler.for_tests.awaitBody(&b, &.{"act"}, 0, key));
                    if (held) {
                        agains += 1;
                        try std.testing.expectEqual(before, actions.pending.items.len);
                    }
                },
                // A rival delivery of a run in flight lands first: that
                // deliver is refused when it applies.
                13...14 => if (actions.pending.items.len > 0) {
                    var eb: [256]u8 = undefined;
                    const pd = actions.pending.items[r.uintLessThan(usize, actions.pending.items.len)];
                    const e = t.shard.raft_node.log.getEntryCopy(pd.index, &eb) orelse return error.TestUnexpectedResult;
                    var diag: schema.Diagnostic = .{};
                    const d = try action_entries.Deliver.decodeAll(e.payload, &diag);
                    var rb: [16]u8 = undefined;
                    @memcpy(rb[0..d.run.len], d.run);
                    _ = try applyActionEntry(&t.shard, .action_deliver, action_entries.Deliver.Value{ .ns = ns_table.DEFAULT.int(), .action = "act", .run = rb[0..d.run.len], .due_ns = d.due_ns, .holder = "rival", .request_key = null, .lease_ms = 5000 }, store_index, now);
                    refused += 1;
                },
                // This node steps down, and leads again.
                15 => actions.stoppedLeading(&t.shard),
                else => try ParkTest.ack(&t.shard),
            }
            // Every deliver proposed and not yet applied names its own run,
            // due when it was proposed; only those runs are held back.
            var runs: [256][]const u8 = undefined;
            var bufs: [256][256]u8 = undefined;
            for (actions.pending.items, 0..) |pd, k| {
                const e = t.shard.raft_node.log.getEntryCopy(pd.index, &bufs[k]) orelse return error.TestUnexpectedResult;
                var diag: schema.Diagnostic = .{};
                const d = try action_entries.Deliver.decodeAll(e.payload, &diag);
                try std.testing.expect(d.due_ns <= e.header.timestamp_ns);
                runs[k] = d.run;
                for (runs[0..k]) |other| try std.testing.expect(!std.mem.eql(u8, other, runs[k]));
            }
            try std.testing.expectEqual(actions.pending.items.len, actions.reserved.count());
            most = @max(most, actions.pending.items.len);
            // Answers are drained so the client's socket never fills.
            var sink: [8192]u8 = undefined;
            while (std.c.read(t.c.pair[1], &sink, sink.len) > 0) {}
        }
        // Delivers were in flight together, some were refused, and some
        // keys found their delivery.
        errdefer std.debug.print("at most {d} in flight, {d} refused, {d} given again\n", .{ most, refused, agains });
        try std.testing.expect(most >= 3 and refused > 0 and agains > 0);
    }
}

test "actions: a waiting await's key holds every name the request gave, and as many of its worker's as fit" {
    const long: [256]u8 = @splat('n');
    var names: [40][]const u8 = undefined;
    var bufs: [40][256]u8 = undefined;
    for (&names, 0..) |*n, i| {
        bufs[i] = long;
        bufs[i][0] = @intCast('a' + (i % 26));
        bufs[i][1] = @intCast('a' + (i / 26));
        n.* = &bufs[i];
    }
    // Two named by the request, the rest registered: those that fit go in.
    const n = ActionsHandler.for_tests.awaitKeyNames("w", &names, 2).?;
    try std.testing.expect(n >= 2 and n < names.len);
    // The request's own must fit.
    try std.testing.expect(ActionsHandler.for_tests.awaitKeyNames("w", &names, names.len) == null);
}

test "Shard: a parked await and an invoke reusing its request id each get one answer" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);
    var out: [4096]u8 = undefined;

    const reg = try testRequest(.action_register, 1, "act", "");
    defer std.testing.allocator.free(reg);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, reg);
    _ = shard.applyCommitted();
    _ = try readAnswer(c.pair[1], &shard, c.conn.fd, &out, @sizeOf(proto.ResponseHeader));

    // The await parks: nothing is pending yet.
    var await_buf: [64]u8 = undefined;
    const aw = try testRequest(.action_await, 7, "worker-1", try ActionsHandler.for_tests.awaitBody(&await_buf, &.{"act"}, 30_000, null));
    defer std.testing.allocator.free(aw);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, aw);
    shard.flushToClient(c.conn.fd);
    try std.testing.expectEqual(@as(c_int, 0), unreadBytes(c.pair[1]));

    // An invoke under the same id wakes it while being dispatched: the
    // await's task is a deferred answer to "request 7", which isn't this
    // request's own.
    const invoke_value: []const u8 = "\x00job";
    const inv = try testRequest(.action_invoke, 7, "act", invoke_value);
    defer std.testing.allocator.free(inv);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, inv);
    _ = shard.applyCommitted();
    // Woken, the await proposed its deliver; it answers once that applies.
    _ = shard.applyCommitted();
    shard.flushToClient(c.conn.fd);

    var rs: [2]proto.Response = undefined;
    var buf: [4096]u8 = undefined;
    try ParkTest.responses(&shard, c.conn, c.pair[1], &buf, &rs);
    var tasks: usize = 0;
    for (rs) |r| {
        try std.testing.expectEqual(@as(u64, 7), r.header.request_id);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), r.header.status);
        if (std.mem.endsWith(u8, r.data, "job")) tasks += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), tasks);
    try std.testing.expectEqual(@as(u64, 0), shard.answered_as_deferred);
}

test "Shard: a handler answering its own request as deferred is caught, and answered once" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);

    // The shape the immediate await had: deliver as deferred, park nothing.
    const SelfDeferred = struct {
        fn handle(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
            const sh: *Shard = @ptrCast(@alignCast(shard_ptr));
            const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
            sh.deliverDeferredOk(conn.replyTo(), req.header.request_id, "only-answer");
        }
    };
    shard.dispatcher.register(.queue_stats, SelfDeferred.handle);

    const frame = try testRequest(.queue_stats, 9, "q", "");
    defer std.testing.allocator.free(frame);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, frame);
    var one: [1]proto.Response = undefined;
    var buf: [1024]u8 = undefined;
    try ParkTest.responses(&shard, c.conn, c.pair[1], &buf, &one);
    try std.testing.expectEqualStrings("only-answer", one[0].data);
    try std.testing.expectEqual(@as(u64, 1), shard.answered_as_deferred);
}

test "Shard: a refusal longer than its frame is sent cut, under its id, and alone" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);

    // A handler refusing with a 2000-byte message, as a long echoed name
    // or a nested parse path can make one. It used to send nothing.
    const Long = struct {
        fn handle(shard_ptr: *anyopaque, conn_ptr: *anyopaque, req: proto.Request) void {
            const sh: *Shard = @ptrCast(@alignCast(shard_ptr));
            const conn: *Connection = @ptrCast(@alignCast(conn_ptr));
            sh.sendErrorResponse(conn, req.header.request_id, .bad_request, stdx.repeat("€", 666) ++ "xx");
        }
    };
    shard.dispatcher.register(.queue_stats, Long.handle);

    const frame = try testRequest(.queue_stats, 11, "q", "");
    defer std.testing.allocator.free(frame);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, frame);
    var one: [1]proto.Response = undefined;
    var buf: [2048]u8 = undefined;
    try ParkTest.responses(&shard, c.conn, c.pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 11), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), one[0].header.status);
    const body = try one[0].refused();
    try std.testing.expect(std.unicode.utf8ValidateSlice(body.message));
    try std.testing.expect(std.mem.endsWith(u8, body.message, proto.TRUNCATED_MARKER));
    try std.testing.expect(body.message.len > 900);
}

