test "Shard: a node whose removal committed is told so; one only removed in an uncommitted config is not" {
    var t: AdminTest = undefined;
    try t.init(1, .bootstrap);
    defer t.deinit();
    const raft = t.shard.raft_node;
    try std.testing.expect(t.shard.applyCommitted());
    var abuf: [transport.APPEND_REQ_PREFIX + 64]u8 = undefined;
    const n = transport.serializeAppendRequest(.{ .term = 9, .leader_id = 9, .prev_log_index = 0, .prev_log_term = 0, .leader_commit = 0, .entries = &.{} }, &abuf).?;
    const frame: RaftFrame = .{ .source_node = 9, .group_id = 0, .msg_type = .append_entries, .payload = abuf[0..n] };

    const uncommitted = raft.latest_config.withJoiner(9, false).without(9, 1234);
    raft.setMembership(&uncommitted, raft.log.lastIndex());
    t.shard.replica.handleRaftFrame(frame);
    try std.testing.expectEqual(@as(u64, 0), t.shard.removed_notice_ms);
    raft.commitMembership(&uncommitted, raft.log.lastIndex());
    t.shard.replica.handleRaftFrame(frame);
    try std.testing.expect(t.shard.removed_notice_ms != 0);
}

test "Shard: a replica sends writers to the leader by name, and a quiet replica asks to join again" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2 }).withJoiner(3, true);
    raft.setMembership(&cfg, 1);
    raft.lost_log = .none;
    raft.leader_id = 1;
    var buf: [512]u8 = undefined;
    try expectAnswer(try t.ask(.kv_put, "v", &buf), .unavailable, "this node is a replica; send writes to the leader, node 1");

    // Its config committed, so only the replica rule can make it ask.
    raft.commit_index = raft.membership_index;
    const now = Shard.nowMs();
    raft.last_leader_contact_ms = now;
    try std.testing.expect(!t.shard.joinWanted(now));
    // No leader for longer than an election: it may have been aged out
    // without being told, so it asks again.
    try std.testing.expect(t.shard.joinWanted(now + raft.config.election_timeout_max_ms + 1));
}

test "Shard: a client's membership change to a follower is refused admin-only, never carried to the leader" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2 }).withJoiner(3, true);
    raft.setMembership(&cfg, 1);
    raft.lost_log = .none;
    raft.leader_id = 1;
    var buf: [512]u8 = undefined;
    // A client's write to a follower is sent on to the leader (the replica rule).
    try expectAnswer(try t.ask(.kv_put, "v", &buf), .unavailable, "this node is a replica; send writes to the leader, node 1");
    // But a membership change is admin-only, and runRequest authorizes
    // (src/node/run.zig authorize) before it ever routes — so a client's
    // promote or remove is refused here, on a follower as on a leader,
    // and is never carried to the leader. The redirect/carry exemption
    // deeper in dispatchLocal is unreachable for a .client origin.
    var pv: [4]u8 = undefined;
    std.mem.writeInt(u32, &pv, 2, .little);
    try expectAnswer(try t.askFrom(.client, .cluster_promote, &pv, &buf), .unauthorized, "served only on the node's admin socket");
    var rv: [5]u8 = undefined;
    std.mem.writeInt(u32, rv[0..4], 2, .little);
    rv[4] = 1;
    try expectAnswer(try t.askFrom(.client, .cluster_remove, &rv, &buf), .unauthorized, "served only on the node's admin socket");
    // The config is untouched: nothing was proposed or forwarded.
    try std.testing.expect(raft.latest_config.isVoter(2));
    try std.testing.expect(raft.latest_config.names(3));
}

test "Shard: a replica refuses an admin-socket membership change up front, and redirects a client write" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2 }).withJoiner(3, true);
    raft.setMembership(&cfg, 1);
    raft.lost_log = .none;
    raft.leader_id = 1;

    // A client's write to this replica is redirected to the leader, answered
    // here and now (the replica cannot carry a client's write).
    var buf: [512]u8 = undefined;
    try expectAnswer(try t.ask(.kv_put, "v", &buf), .unavailable, "this node is a replica; send writes to the leader, node 1");

    // A replica can't carry an admin-socket membership change either — it has
    // no voter link to the leader, so the leader never answers a forward from
    // it (the client would see a stray not_found). So the replica refuses the
    // change up front, naming the leader, and forwards nothing.
    const before = t.shard.forward_count;
    try expectAnswer(try t.promote(2, &buf), .unavailable, "this node is a replica; an admin command must go to a voter");
    try std.testing.expectEqual(before, t.shard.forward_count);
    try std.testing.expect(!t.conn.response_deferred);
}

test "Shard: a replica points a namespace alter from its admin socket at a voter's admin socket, not the leader's client port" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    const cfg = membership.Config.ofVoters(&.{ 1, 2 }).withJoiner(3, true);
    raft.setMembership(&cfg, 1);
    raft.lost_log = .none;
    raft.leader_id = 1;

    // The client port refuses an alter, so "send writes to the leader"
    // would send it where it can't run.
    var vb: [64]u8 = undefined;
    const value = try table_run.op("namespace.alter").request.encodeInto(&vb, .{ .history_quota_mode = .none, .history_quota_bytes = null });
    const before = t.shard.forward_count;
    t.shard.runRequest(t.conn, .{ .header = proto.RequestHeader.init(.namespace_alter, 7), .namespace = "", .key = "orders", .value = value }, .admin);
    var buf: [512]u8 = undefined;
    var into: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &into);
    try expectAnswer(into[0], .unavailable, "this node is a replica; an admin command must go to a voter's admin socket");
    try std.testing.expectEqual(before, t.shard.forward_count);
}

test "Shard: a list page whose scan couldn't hold its names is refused, not cut short" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    const c = try TestClient.open(&shard);
    defer _ = std.c.close(c.pair[1]);

    const Short = struct {
        fn scan(_: *anyopaque, _: dispatcher_mod.WalkNamespace, _: []const u8, _: ?[]const u8, _: u32) dispatcher_mod.NameWalker.ScanResult {
            dispatcher_mod.noteScanShort();
            return .{ .items = &.{}, .next_cursor = null };
        }
        fn handle(_: *anyopaque, _: *anyopaque, _: proto.Request) void {}
    };
    shard.dispatcher.registerWalk(.stream_list, Short.handle, Short.scan);
    shard.dispatcher.setWalkContext(.stream_list, @ptrCast(&shard));

    const frame = try testRequest(.stream_list, 14, "", &.{ 0, 0, 0, 0 });
    defer std.testing.allocator.free(frame);
    _ = feedClient(c.pair[1], &shard, c.conn.fd, frame);
    var out: [1024]u8 = undefined;
    const resp = try nextAnswer(c, &shard, &out);
    try std.testing.expectEqual(@as(u64, 14), resp.header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), resp.header.status);
    try std.testing.expect(!dispatcher_mod.takeScanShort());
}

/// An append of `count` records to the default namespace's stream `name`,
/// at log index `index` and `ms`, applied through the streams machine.
fn testStreamAppend(p: *Partition, name: []const u8, index: u64, ms: u64, count: u32) !void {
    var vb: [512]u8 = undefined;
    var pb: [1024]u8 = undefined;
    const e = entry_mod.buildCommandEntry(.stream_append, entry_mod.Flags.NONE, 1, index, ms * std.time.ns_per_ms, .default, name, stream_mod.appendValueOf(&vb, count, 4), &pb).?;
    var out = persistence_mod.Result.start(&e);
    try contract_machine.applyEntry(&stream_machine.machine, &p.store, &p.apply_scratch, &e, &out);
    try std.testing.expect(out.refused() == null);
}

/// The default namespace's stream `name` created with this retention, as
/// an applied `stream_config` leaves it.
fn streamSettings(shard: *Shard, name: []const u8, age_s: u64, count: u64) !void {
    var value: [stream_machine.StreamConfig.SIZE]u8 = undefined;
    (stream_machine.StreamConfig{ .op = .create, .partition_count = 1, .retention_age_s = age_s, .retention_count = count }).encode(&value);
    var pb: [256]u8 = undefined;
    const e = entry_mod.buildCommandEntry(.stream_config, entry_mod.Flags.NONE, 1, 1, 1, .default, name, &value, &pb).?;
    var out = persistence_mod.Result.start(&e);
    const p = shard.defaultPartition();
    try contract_machine.applyEntry(&stream_machine.machine, &p.store, &p.apply_scratch, &e, &out);
    try std.testing.expect(out.refused() == null);
}

test "Shard: a stream create applied gives the stream its metrics series at once, before any append" {
    const pipe_fds = try @import("stdx").io.pipe();
