test "a stream's retention age counts in seconds when the sweeper trims by it" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    const stream = shard.stream_handler.stream;
    const h = stream_mod.streamKey(.default, "aged");
    try streamSettings(&shard, "aged", 5, 0);
    const now_ms: u64 = @intCast(@import("stdx").time.milliTimestamp());
    try testStreamAppend(shard.defaultPartition(), "aged", 1, now_ms - 10_000, 1);
    try testStreamAppend(shard.defaultPartition(), "aged", 2, now_ms - 1_000, 1);
    // Older than 5 seconds: the 10 s old record goes, the 1 s old one stays.
    try std.testing.expectEqual(@as(u64, 1), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(@as(u64, 1), stream.streamLogicalCount(h));
}

test "Shard: the retention duty removes the appends a trim left below the floor, whether or not the stream has a policy" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    const n = 3 * stream_machine.MAX_TRIM_APPENDS;
    const p = shard.defaultPartition();
    for (0..n) |i| try testStreamAppend(p, "big", i + 1, 1000 + i, 1);
    const key = stream_mod.streamKey(.default, "big");
    // A client's trim of every append but the last: whole at once, with
    // the most it may remove removed and the stream marked for the rest.
    try std.testing.expect(shard.stream_handler.persistTrim(key, .{ .id = .{ .timestamp_ms = 1000 + n - 2, .sequence = 0 } }));
    try std.testing.expect(shard.applyCommitted());
    const read: view_mod.ReadView = .{ .store = &p.store };
    const floor = stream_machine.floorOf((try read.get(stream_machine.Metas, &key)).?.v);
    try std.testing.expectEqual(n - 1 - stream_machine.MAX_TRIM_APPENDS, stream_machine.heldThrough(read, key, floor, n));
    try std.testing.expect((try read.get(stream_machine.Reclaim, &key)) != null);
    // One pass proposes the trims to the floor that clear the rest.
    try std.testing.expectEqual(@as(u64, 2), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(@as(usize, 0), stream_machine.heldThrough(read, key, floor, n));
    try std.testing.expect((try read.get(stream_machine.Reclaim, &key)) == null);
    try std.testing.expectEqual(@as(u64, 1), shard.stream_handler.stream.streamLogicalCount(key));
    // Nothing is left to propose.
    try std.testing.expectEqual(@as(u64, 0), Shard.streamRetentionTask(@ptrCast(&shard)));
}

test "Shard: the retention duty drains marked streams within one budget a pass, each in turn" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    // More marked streams than the budget, each one drain trim short.
    const streams = Shard.DRAIN_BUDGET + 4;
    const per = stream_machine.MAX_TRIM_APPENDS + 2;
    const p = shard.defaultPartition();
    var index: u64 = 1;
    var nb: [16]u8 = undefined;
    for (0..streams) |s| {
        const name = try std.fmt.bufPrint(&nb, "s{d:0>2}", .{s});
        for (0..per) |i| {
            try testStreamAppend(p, name, index, 1000 + i, 1);
            index += 1;
        }
        try std.testing.expect(shard.stream_handler.persistTrim(stream_mod.streamKey(.default, name), .{ .id = .{ .timestamp_ms = 1000 + per - 2, .sequence = 0 } }));
        try std.testing.expect(shard.applyCommitted());
    }
    try std.testing.expectEqual(@as(u64, streams), p.store.family(stream_machine.Reclaim.ID).count);
    // The budget, then the rest from where the first pass stopped.
    try std.testing.expectEqual(@as(u64, Shard.DRAIN_BUDGET), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(@as(u64, streams - Shard.DRAIN_BUDGET), p.store.family(stream_machine.Reclaim.ID).count);
    try std.testing.expectEqual(@as(u64, streams - Shard.DRAIN_BUDGET), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(@as(u64, 0), p.store.family(stream_machine.Reclaim.ID).count);
    try std.testing.expectEqual(@as(u64, 0), Shard.streamRetentionTask(@ptrCast(&shard)));
}

test "Shard: a forced delete answers at once; the retention duty removes its appends, then forgets the tombstone" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    const n = 2 * stream_machine.MAX_TRIM_APPENDS + 2;
    const p = shard.defaultPartition();
    for (0..n) |i| try testStreamAppend(p, "big", i + 1, 1000 + i, 1);
    _ = try persistence_mod.proposeEntry(&shard, .stream_delete, entry_mod.Flags.FORCE, "default", "big", "");
    try std.testing.expect(shard.applyCommitted());
    const key = stream_mod.streamKey(.default, "big");
    const read: view_mod.ReadView = .{ .store = &p.store };
    // Gone at once; its appends stay, unread, until the duty removes them.
    try std.testing.expect(stream_machine.metaOf(read, .default, "big") == null);
    try std.testing.expectEqual(@as(usize, n), stream_machine.heldThrough(read, key, stream_machine.StreamID.MAX, n + 1));
    // One pass: the cleans that remove them all.
    try std.testing.expectEqual(@as(u64, 3), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expectEqual(@as(usize, 0), stream_machine.heldThrough(read, key, stream_machine.StreamID.MAX, n + 1));
    // The next: the forget, as no group counts it.
    try std.testing.expectEqual(@as(u64, 1), Shard.streamRetentionTask(@ptrCast(&shard)));
    try std.testing.expect(shard.applyCommitted());
    try std.testing.expect(stream_machine.metaAt(read, key) == null);
    try std.testing.expectEqual(@as(u64, 0), p.store.family(stream_machine.Reclaim.ID).count);
    try std.testing.expectEqual(@as(u64, 0), Shard.streamRetentionTask(@ptrCast(&shard)));
}

// ── Silent loss and damage ──────────────────────────────────────────────

/// A lone shard's data directory holding one sealed segment per queue
/// enqueue, for the boot damage tests.
const DamageTest = struct {
    tmp: std.testing.TmpDir,
    data_dir: []const u8,
    segs: []const u8,
    pipe_fds: [2]i32,
    seal_every_flush: bool,

    const ENQUEUES = 4;

    fn init(self: *DamageTest) !void {
        self.tmp = std.testing.tmpDir(.{});
        self.data_dir = try testDataDir(&self.tmp);
        self.segs = try std.fmt.allocPrint(std.testing.allocator, "{s}/00000/segs", .{self.data_dir});
        self.pipe_fds = try @import("stdx").io.pipe();
        self.seal_every_flush = true;
        try self.write();
    }

    /// `init`, keeping its writes in one active segment, as a run does.
    fn initActive(self: *DamageTest) !void {
        try self.init();
        // Again from empty, appended rather than sealed per flush.
        try @import("stdx").fs.deleteTree(self.segs);
        try @import("stdx").fs.makePath(self.segs);
        self.seal_every_flush = false;
        try self.write();
    }

    fn write(self: *DamageTest) !void {
        var shard = try self.open();
        defer shard.deinit();
        for (0..ENQUEUES) |i| {
            _ = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'A' + @as(u8, @intCast(i))});
            try std.testing.expect(shard.applyCommitted());
            try shard.flushSegmentToDisk();
        }
    }

    fn deinit(self: *DamageTest) void {
        _ = std.c.close(self.pipe_fds[0]);
        _ = std.c.close(self.pipe_fds[1]);
        std.testing.allocator.free(self.segs);
        std.testing.allocator.free(self.data_dir);
        self.tmp.cleanup();
    }

    fn open(self: *DamageTest) !Shard {
        return self.openWith(.sync);
    }

    fn openWith(self: *DamageTest, durability: Durability) !Shard {
        var shard = try Shard.init(std.testing.allocator, 0, 4, self.pipe_fds[0], self.data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, durability, 1, .single, .{}, .{});
        shard.wireHandlerShardPtrs();
        // These tests damage one sealed segment among several: each flush
        // seals its own, unless a test keeps the active segment.
        if (self.seal_every_flush) shard.durable_log.?.max_segment_bytes = 1;
        return shard;
    }

    /// The path of the `n`th sealed segment, in index order (names sort so).
    fn segment(self: *DamageTest, n: usize, buf: []u8) ![]const u8 {
        var names: [16][64]u8 = undefined;
        var lens: [16]usize = undefined;
        var count: usize = 0;
        var dir = try @import("stdx").fs.openDir(self.segs, .{ .iterate = true });
        defer @import("stdx").fs.closeDir(dir);
        var iter = dir.iterate();
        while (try iter.next(@import("stdx").io.instance())) |de| {
            if (!std.mem.endsWith(u8, de.name, ".flseg")) continue;
            @memcpy(names[count][0..de.name.len], de.name);
            lens[count] = de.name.len;
            count += 1;
        }
        var order: [16]usize = undefined;
        for (0..count) |i| order[i] = i;
        const Ctx = struct {
            names: *const [16][64]u8,
            lens: *const [16]usize,
            fn less(c: @This(), a: usize, b: usize) bool {
                return std.mem.lessThan(u8, c.names[a][0..c.lens[a]], c.names[b][0..c.lens[b]]);
            }
        };
        std.mem.sort(usize, order[0..count], Ctx{ .names = &names, .lens = &lens }, Ctx.less);
        const i = order[n];
        return std.fmt.bufPrint(buf, "{s}/{s}", .{ self.segs, names[i][0..lens[i]] });
    }

    fn readFile(path: []const u8) ![]u8 {
        const f = try @import("stdx").fs.openFile(path, .{});
        defer @import("stdx").fs.closeFile(f);
        return @import("stdx").fs.readToEndAlloc(f, std.testing.allocator, 1 << 24);
    }

    fn writeFile(path: []const u8, bytes: []const u8) !void {
        const f = try @import("stdx").fs.createFile(path, .{});
        defer @import("stdx").fs.closeFile(f);
        try @import("stdx").fs.writeAll(f, bytes);
    }

    fn queued(shard: *Shard) u64 {
        return queue_handler_mod.countQueue(shard, .default, "q");
    }

    /// Reopen, and expect the shard offline for `path`, having applied the
    /// segments before the damage and nothing after.
    fn expectOffline(self: *DamageTest, path: silent_loss.Path, queued_before: u64) !void {
        var shard = try self.open();
        defer shard.deinit();
        const damage = shard.offline orelse return error.ShardNotOffline;
        try std.testing.expectEqual(path, damage.path);
        try std.testing.expectEqual(@as(u64, 1), shard.losses.total(path));
        try std.testing.expectEqual(queued_before, queued(&shard));
        var buf: [320]u8 = undefined;
        try std.testing.expect(std.mem.indexOf(u8, shard.offlineMessage(&buf), "is offline on this node") != null);
        // Nothing applies over the damage, and nothing proposes.
        try std.testing.expect(shard.raft_node.role != .leader);
        try std.testing.expect(shard.applyCommitted());
    }
};

/// Flip a byte in the active segment's newest mark.
fn tearNewestMark(path: []const u8) !void {
    const seg = @import("../storage/ual/segment.zig");
    const bytes = try DamageTest.readFile(path);
    defer std.testing.allocator.free(bytes);
    const hdr = try seg.SegmentHeader.parse(bytes[0..seg.HEADER_SIZE]);
    bytes[seg.MARK_OFFSETS[hdr.slot.?] + 20] ^= 0xff;
    try DamageTest.writeFile(path, bytes);
}

test "a restart that lost the active segment's newest mark finds every write past the older one" {
    var t: DamageTest = undefined;
    try t.initActive();
    defer t.deinit();
    var buf: [512]u8 = undefined;
    const path = try t.segment(0, &buf);
    try tearNewestMark(path);
    var shard = try t.open();
    defer shard.deinit();
    try std.testing.expect(shard.offline == null);
    _ = shard.applyCommitted();
    try std.testing.expectEqual(@as(u64, DamageTest.ENQUEUES), DamageTest.queued(&shard));
}

