test "Shard: a replica refuses a repair from its admin socket up front, naming the leader" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    const raft = t.shard.raft_node;
    // A replica: named in the config, not a voter, following node 1.
    raft.self_named = true;
    raft.timer_enabled = false;
    raft.role = .follower;
    raft.leader_id = 1;
    var buf: [256]u8 = undefined;
    const held = t.shard.forward_count;
    // A replica has no voter link to carry a repair to the leader, so it
    // refuses it up front, naming the leader, rather than holding a forward
    // the leader won't answer.
    const answer = (try t.repairSkip(.admin, 5, false, &buf)) orelse return error.TestExpectedRefusal;
    try expectAnswer(answer, .unavailable, "an admin command must go to a voter");
    try std.testing.expect(std.mem.indexOf(u8, answer.data, "node 1") != null); // names the leader
    try std.testing.expectEqual(held, t.shard.forward_count); // not forwarded
    try std.testing.expect(!t.conn.response_deferred); // answered here, not held
}

test "checkAppliers: a type a contract machine owns may have no other applier, and needs none" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    const Toy = struct {
        fn keys(_: *const entry_mod.Entry, _: *@import("../contract/view.zig").KeySet) error{OutOfMemory}!void {}
        fn apply(_: *@import("../contract/view.zig").View, _: *const entry_mod.Entry, _: *persistence_mod.Result) persistence_mod.ApplyError!void {}
        fn owning(comptime t: entry_mod.EntryType) contract_machine.Machine {
            return .{ .name = "toy", .entry_types = &.{t}, .families = &.{}, .keys = keys, .apply = apply };
        }
    };
    const listed_now = contract_machines.list;
    try checkAppliersWith(&listed_now, 0);
    // A type nothing else applies: the machine is its applier.
    try checkAppliersWith(&(listed_now ++ .{Toy.owning(.raft_snapshot)}), 0);
    // The Raft node's config, owned by a machine too: refused.
    try std.testing.expectError(error.EntryTypeHasTwoAppliers, checkAppliersWith(&(listed_now ++ .{Toy.owning(.raft_config)}), 0));
    // KV's types are its machine's: without it, they have no applier.
    try std.testing.expectError(error.EntryTypeHasNoApplier, checkAppliersWith(&.{}, 0));
}

test "applyEntryCore: a machine reads the streams every entry below its own left" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());

    const Reader = struct {
        var hash: stream_mod.StreamKey = @splat(0);
        var seen: [8]StreamID = undefined;
        var n: usize = 0;
        fn keys(_: *const entry_mod.Entry, _: *view_mod.KeySet) error{OutOfMemory}!void {}
        fn apply(view: *view_mod.View, _: *const entry_mod.Entry, _: *persistence_mod.Result) persistence_mod.ApplyError!void {
            n = (try view.streams()).idsAfter(hash, StreamID.MIN, &seen);
        }
        const machine: contract_machine.Machine = .{ .name = "reader", .entry_types = &.{.cg_create}, .families = &.{}, .keys = keys, .apply = apply };
    };
    Reader.hash = stream_mod.streamKey(.default, "s");

    var vb: [64]u8 = undefined;
    const v = stream_mod.appendValueOf(&vb, 1, 1);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    try std.testing.expect(shard.applyCommitted());

    // The next index, as the shard's own apply would reach it.
    const raft = shard.raft_node;
    const e = entry_mod.buildEntry(.cg_create, entry_mod.Flags.NONE, raft.current_term, raft.last_applied + 1, raft.applied_stamp + 1, "");
    var out: persistence_mod.Result = .{};
    out.reset(&e);
    const machines = contract_machines.list ++ .{Reader.machine};
    try std.testing.expect(applyEntryCoreWith(&machines, shard.defaultPartition(), shard.raft_node, &e, &out) == .applied);
    try std.testing.expectEqual(@as(usize, 2), Reader.n);
    try std.testing.expect(Reader.seen[0].eql(shard.stream_handler.stream.streamFirstId(Reader.hash)));
    try std.testing.expect(Reader.seen[1].eql(shard.stream_handler.stream.streamLastId(Reader.hash)));
}

test "applyEntryCore: a forced delete of a stream with groups moves their generation on; a refused one doesn't" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
    defer shard.deinit();
    shard.wireHandlerShardPtrs();
    try std.testing.expect(shard.applyCommitted());
    var vb: [64]u8 = undefined;
    const v = stream_mod.appendValueOf(&vb, 1, 1);
    _ = try persistence_mod.proposeEntry(&shard, .stream_append, entry_mod.Flags.NONE, "", "s", v);
    try std.testing.expect(shard.applyCommitted());

    const gm = @import("../stream/group_machine.zig");
    const p = shard.defaultPartition();
    var index = shard.raft_node.last_applied;
    var cb: [ge_mod.Create.max_size]u8 = undefined;
    const create = entry_mod.buildEntry(.group_create, entry_mod.Flags.NONE, shard.raft_node.current_term, index + 1, 1, try ge_mod.Create.encodeInto(&cb, .{ .ns = 1, .stream = "s", .group = "g", .lease_ms = 30_000, .max_attempts = 3 }));
    index += 1;
    var out: persistence_mod.Result = .{};
    out.reset(&create);
    try std.testing.expect(applyEntryCore(p, shard.raft_node, &create, &out) == .applied);

    const hash = stream_mod.streamKey(.default, "s");
    const genOf = struct {
        fn f(part: *Partition, h: stream_mod.StreamKey) u64 {
            var b: [13]u8 = undefined;
            _ = &b;
            return gm.streamViewOf(.{ .store = &part.store }, h).gen;
        }
    }.f;
    try std.testing.expectEqual(@as(u64, 0), genOf(p, hash));
    // Not empty, not forced: refused, and the group never hears of it.
    // Forced: applied, and the group's stream moves on a generation.
    for ([_]u16{ entry_mod.Flags.NONE, entry_mod.Flags.FORCE }, [_]u64{ 0, 1 }) |flags, gen| {
        var buf: [64]u8 = undefined;
        const cmd: entry_mod.CommandPayload = .{ .namespace_id = .default, .key_length = 1, .value_length = 0, .key = "s", .value = "" };
        index += 1;
        const del = entry_mod.buildEntry(.stream_delete, flags, shard.raft_node.current_term, index, 2, buf[0..cmd.serialize(&buf).?]);
        out.reset(&del);
        try std.testing.expect(applyEntryCore(p, shard.raft_node, &del, &out) == .applied);
        try std.testing.expectEqual(flags == entry_mod.Flags.NONE, out.refused() != null);
        try std.testing.expectEqual(gen, genOf(p, hash));
    }
}

test "applyEntryCore: a KV entry delivered twice applies once, and is a duplicate the second time" {
    var part = try Partition.init(std.testing.allocator, 0, 8192, 0);
    defer part.deinit();
    part.wireProjections();
    var buf: [64]u8 = undefined;
    const e = entry_mod.buildEntry(.kv_put, entry_mod.Flags.NONE, 1, 1, 0, try kv_entries.Put.encodeInto(&buf, .{ .key = TEST_KV_K, .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null }));
    for (0..2) |i| {
        var out: persistence_mod.Result = .{};
        out.reset(&e);
        const got = applyEntryCore(&part, null, &e, &out);
        if (i == 0) try std.testing.expect(got == .applied) else try std.testing.expect(got == .partition_reject and got.partition_reject == error.IndexNotIncreasing);
    }
    try std.testing.expectEqual(@as(u64, 1), part.kv.getIn(.default, "k").?.version);
}

// ─── The edge ────────────────────────────────────────────────────────────

/// kv.get of `key` in `namespace`, its body in `buf`.
fn edgeGet(buf: []u8, id: u64, namespace: []const u8, key: []const u8) proto.Request {
    const body = table_run.op("kv.get").request.encodeInto(buf, .{ .wait_ms = 0, .wait_for = .exists, .txn = null }) catch unreachable;
    return .{ .header = proto.RequestHeader.init(.kv_get, id), .namespace = namespace, .key = key, .value = body };
}

fn expectNoAnswer(c: TestClient, shard: *Shard) !void {
    shard.flushToClient(c.conn.fd);
    var out: [64]u8 = undefined;
    try std.testing.expect(std.c.read(c.pair[1], &out, out.len) <= 0);
}

/// The asks a follower sent its leader: their forward ids, in order.
fn edgeAsks(rn: *RaftNetwork, ids: []u32) ![]u32 {
    var n: usize = 0;
    for (rn.outbound.items) |o| {
        const payload = o.frame[transport.HEADER_SIZE..];
        const req = try proto.Request.parse(payload[FORWARD_PREFIX + FORWARD_FIELDS ..]);
        if (req.header.op_code != @backingInt(proto.OpCode.namespace_published)) continue;
        // An ask names no namespace id of its own.
        try std.testing.expectEqual(@as(u32, 0), std.mem.readInt(u32, payload[FORWARD_PREFIX..][0..4], .little));
        ids[n] = std.mem.readInt(u32, payload[0..4], .little);
        n += 1;
    }
    return ids[0..n];
}

/// The leader's answer to ask `id`: its table published to `index`.
fn answerAsk(shard: *Shard, id: u32, index: u64) !void {
    const Published = table_run.op("namespace.published").response;
    var abuf: [@sizeOf(proto.ResponseHeader) + Published.max_size]u8 = undefined;
    const answer = table_run.encodeAnswer(Published, &abuf, id, .{ .published_index = index }).?;
    var buf: [12 + abuf.len]u8 = undefined;
    std.mem.writeInt(u32, buf[0..4], id, .little);
    std.mem.writeInt(u64, buf[4..12], 0, .little);
    @memcpy(buf[12..][0..answer.len], answer);
    shard.takeForwardReply(.{ .source_node = 2, .group_id = 0, .msg_type = .forward_reply, .payload = buf[0 .. 12 + answer.len] });
}

const EdgeFollower = struct {
    t: FollowerTest,
    c: TestClient,

    fn init(f: *EdgeFollower) !void {
        try f.t.init();
        f.t.shard.raft_node.leader_id = 2;
        f.t.rn.linked_ids[0].store(2, .release);
        f.t.rn.linked_sessions[0].store(5, .release);
        f.c = try TestClient.open(&f.t.shard);
    }

    fn deinit(f: *EdgeFollower) void {
        for (f.t.rn.outbound.items) |o| std.testing.allocator.free(o.frame);
        f.t.rn.outbound.clearRetainingCapacity();
        _ = std.c.close(f.c.pair[1]);
        f.t.deinit();
    }
};

test "Shard: a read resolved before shard 0 published its namespace routes by the id the edge found, not by none" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const b = &two.shards[1];
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    var body: [64]u8 = undefined;
    // As `runRequest` resolves it before shard 0's thread publishes: none.
    var req = edgeGet(&body, 1, "xs", "k");
    req.ns_id = .invalid;
    const id: ns_table.Id = .of(ns_table.FIRST_ALLOCATED.int() + 3);
    try two.namespaces.publish(id, "xs", 1);
    // Published by the time the edge looks: let through, with that id.
    try std.testing.expect(!b.edgeMiss(c.conn, &req, .client));
    try std.testing.expectEqual(id, req.ns_id);
}

test "Shard: requests held at shard 0's edge until their namespace publishes run in the order they were sent, whatever slots they hold" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const a = &two.shards[0];
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var out: [2048]u8 = undefined;
    // Applied on shard 0, not yet published to the node's table.
    a.runRequest(c.conn, try ParkTest.request(.namespace_create, 1, "", "fresh", "", ""), .client);
    _ = a.applyCommitted();
    try std.testing.expect(two.namespaces.lookup("fresh") == null);
    var bodies: [3][64]u8 = undefined;
    for (&bodies, 0..) |*body, i| a.runRequest(c.conn, edgeGet(body, 10 + i, "fresh", "k"), .client);
    // Held, each in a slot; a freed slot reused would put a later request
    // in an earlier slot.
    var held: [3]usize = undefined;
    var n: usize = 0;
    for (&a.edge.waits, 0..) |*w, i| if (w.active and std.mem.eql(u8, w.name, "fresh")) {
        held[n] = i;
        n += 1;
    };
    try std.testing.expectEqual(@as(usize, 3), n);
    std.mem.swap(edge_mod.Wait, &a.edge.waits[held[0]], &a.edge.waits[held[2]]);
    for (0..4) |_| {
        _ = try a.tick(0);
        two.settle();
    }
    // The create's answer, then the three reads in the order sent.
    var answers: [4]proto.Response = undefined;
    try ParkTest.responses(a, c.conn, c.pair[1], &out, &answers);
    try std.testing.expectEqual(@as(u64, 1), answers[0].header.request_id);
    for (answers[1..], 10..) |r, id| try std.testing.expectEqual(@as(u64, id), r.header.request_id);
}

/// A first life of two shards under `data_dir`: namespace "xs" created,
/// and key "v" written under a key shard 1 owns by the namespace's id but
/// shard 0 would own by none, so a request routed by no id goes astray.
fn twoShardsWithXsKey(data_dir: []const u8, key_buf: *[8]u8) ![]const u8 {
    var out: [512]u8 = undefined;
    var two: TwoShards = undefined;
    try two.initAt(data_dir);
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const a = &two.shards[0];
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    a.runRequest(c.conn, try ParkTest.request(.namespace_create, 1, "", "xs", "", ""), .client);
    two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(c, a, &out)).header.status);
    const id = two.namespaces.lookup("xs").?;
    var key: []const u8 = "";
    var i: u8 = 0;
    while (key.len == 0) : (i += 1) {
        const k = try std.fmt.bufPrint(key_buf, "k{d}", .{i});
        if (a.router.hashToShard(node_router.routeNsKey(id, k)) == 1 and a.router.hashToShard(node_router.routeNsKey(.invalid, k)) == 0) key = k;
    }
    a.runRequest(c.conn, testReq(.kv_put, 2, "xs", key, "v", ""), .client);
    two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(c, a, &out)).header.status);
    for (&two.shards) |*s| try s.flushSegmentToDisk();
    return key;
}

/// The second life: both shards booted from `data_dir`, everything applied,
/// "xs" held by shard 0 and not yet in the node's table.
fn restartedBeforePublish(two: *TwoShards, data_dir: []const u8) !void {
    try two.initAt(data_dir);
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    for (&two.shards) |*s| _ = s.applyCommitted();
    try std.testing.expect(two.namespaces.lookup("xs") == null);
}

fn drainBoth(two: *TwoShards) void {
    for (0..4) |_| for (&two.shards) |*s| {
        _ = s.drainInbox();
    };
}

test "Shard: after a restart, a read through shard 0 of a key another shard owns waits for shard 0 to publish its namespace, then finds it" {
    var tmp = std.testing.tmpDir(.{});
