test "Shard: a workflow whose trigger, or a job whose source or stream sink, names a reserved stream is refused unauthorized and logs nothing" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
