    var out: [512]u8 = undefined;
    const workflows = [_][]const u8{
        "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1\",\"trigger\":{\"stream\":\"_flo:history\"},\"start\":{\"wait_for_signal\":{\"type\":\"go\"},\"transitions\":{\"success\":\"flo.Completed\"}}}",
        "{\"kind\":\"Workflow\",\"name\":\"wf\",\"version\":\"1\",\"trigger\":{\"stream\":\"_flo:history\",\"namespace\":\"other\"},\"start\":{\"wait_for_signal\":{\"type\":\"go\"},\"transitions\":{\"success\":\"flo.Completed\"}}}",
    };
    const jobs = [_][]const u8{
        "{\"kind\":\"Processing\",\"name\":\"j\",\"sources\":[{\"stream\":{\"name\":\"_flo:history\"}}],\"sinks\":[{\"stream\":{\"name\":\"out\"}}]}",
        "{\"kind\":\"Processing\",\"name\":\"j\",\"sources\":[{\"stream\":{\"name\":\"in\"}}],\"sinks\":[{\"stream\":{\"name\":\"_flo:history\"}}]}",
    };
    const last = shard.raft_node.log.lastIndex();
    var id: u64 = 0;
    for (workflows) |def| {
        id += 1;
        shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.workflow_create, id), .namespace = "default", .key = "wf", .value = def }, .client);
        try expectReserved(try nextAnswer(c, &shard, &out));
    }
    for (jobs) |def| {
        id += 1;
        shard.runRequest(c.conn, .{ .header = proto.RequestHeader.init(.processing_submit, id), .namespace = "default", .key = "", .value = def }, .client);
        try expectReserved(try nextAnswer(c, &shard, &out));
    }
    try std.testing.expectEqual(last, shard.raft_node.log.lastIndex());
