    try std.testing.expectEqual(raft_node_mod.Role.leader, r.role);
    try std.testing.expectEqual(term, r.current_term);

    try stepWindowClosed(&t.shard);
    try ParkTest.responses(&t.shard, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 2), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
}

test "Shard: a leader still applying earlier terms passes a bar without a snapshot and counts it; a follower at the bar takes its window" {
    var t: RaceTest = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;

    // Two writes proposed, then elected again before they commit: not ready
    // until it has applied them.
    try ParkTest.send(&t.shard, t.conn, .kv_put, 1, "a", "v");
    try ParkTest.send(&t.shard, t.conn, .kv_put, 2, "b", "v");
    const bar = r.log.lastIndex() - 1;
    t.shard.test_bar = bar;
    r.current_term += 1;
    r.ready_index = r.log.lastIndex();
    try std.testing.expect(t.shard.leaderApplying());
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    try ParkTest.ack(&t.shard);
    try std.testing.expect(r.last_applied > bar);
    try std.testing.expect(t.shard.snapshot_window == null);
    try std.testing.expectEqual(@as(u64, 1), t.shard.snapshot_skips_leader_not_ready);
    // Ready now, and past the bar: no snapshot is taken for it later.
    try std.testing.expect(!t.shard.leaderApplying());
    _ = try t.shard.tick(0);
    try std.testing.expect(t.shard.snapshot_window == null);
    // Counted where metrics and /status read it.
    var registry = MetricsRegistry.init(std.testing.allocator);
    defer registry.deinit();
    try registry.initShards(1);
    t.shard.setMetricsRegistry(&registry);
    t.shard.publishHealth();
    try std.testing.expectEqual(@as(u64, 1), t.shard.shard_metrics.?.snapshot().snapshot_skipped_leader_not_ready);
}

test "Shard: a follower reaching a bar suspends apply; one that stops applying drops its window" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const r = t.shard.raft_node;
    // Entries in the log, committed, applied as a follower would apply them.
    t.shard.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.role = .follower;
    try std.testing.expect(t.shard.applyCommitted());
    try std.testing.expectEqual(t.shard.test_bar, t.shard.snapshot_window.?.s);
    try std.testing.expectEqual(t.shard.test_bar, r.last_applied);
    try std.testing.expect(r.commit_index > r.last_applied);
    t.shard.replica.diverged = true;
    t.shard.stepSnapshotWindow();
    try std.testing.expect(t.shard.snapshot_window == null);
    t.shard.replica.diverged = false;
    r.role = .leader;
}

test "Shard: a processing sink whose shard is capped while apply is suspended holds its source, and writes every record once room comes back" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    const yaml =
        \\kind: Processing
        \\name: capped
        \\sources:
        \\  - name: src
        \\    stream: { name: in }
        \\sinks:
        \\  - name: out
        \\    stream: { name: out }
    ;
    sh.runRequest(t.conn, try ParkTest.request(.processing_submit, 1, proto.DEFAULT_NAMESPACE, "", yaml, ""), .client);
    _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(u32, 1), sh.processing_handler.jobCount());

    // More source records than the cap.
    const records = 1500;
    for (0..records) |k| {
        var pbuf: [16]u8 = undefined;
        _ = try sh.stream_handler.appendPayloadToStream("in", "default", try std.fmt.bufPrint(&pbuf, "rec-{d}", .{k}));
        if (k % 256 == 0) _ = sh.applyCommitted();
    }
    _ = sh.applyCommitted();
    try std.testing.expectEqual(r.commit_index, r.last_applied);

    // Apply suspends at the next entry; the pipeline then fills the cap.
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = sh.applyCommitted();
    try std.testing.expect(sh.snapshot_window != null);
    const from = r.log.lastIndex() + 1;
    const Tick = struct {
        fn pipelines(s: *Shard) void {
            var it = s.processing_handler.pipelines.valueIterator();
            while (it.next()) |p| p.last_poll_ms = ProcessingHandler.NEVER_MS;
            _ = s.processing_handler.tickPipelines(s);
        }
    };
    // One batch, then nothing more until it applies.
    for (0..40) |_| Tick.pipelines(sh);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(sh, .processing_sink_batch, from));
    try std.testing.expectEqual(@as(u64, 0), sh.processing_handler.sink_drops);

    // Resumed, every record reaches the sink exactly once, and none dropped.
    try stepWindowClosed(sh);
    for (0..400) |_| {
        Tick.pipelines(sh);
        _ = sh.applyCommitted();
        sh.tickChannels();
        _ = sh.drainInbox();
        _ = sh.applyCommitted();
        if (streamRecords(sh, "out", "default") >= records) break;
    }
    try std.testing.expectEqual(@as(usize, records), streamRecords(sh, "out", "default"));
    try std.testing.expectEqual(@as(u64, 0), sh.processing_handler.sink_drops);
}

/// A lone node suspended at a fresh test bar; returns the bar.
fn suspendAtTestBar(sh: *Shard) !u64 {
    const r = sh.raft_node;
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    _ = sh.applyCommitted();
    return sh.snapshot_window.?.s;
}

test "Shard: a window is dropped when its shard halts, goes offline, has its applied entries cut below the bar, or wins an election" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;

    _ = try suspendAtTestBar(sh);
    sh.halted = .{ .index = r.last_applied + 1, .term = r.current_term, .crc = 0 };
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    sh.halted = null;

    _ = try suspendAtTestBar(sh);
    sh.offline = silent_loss.Damage.init(.segment_unreadable, "segment {d} is unreadable", .{7});
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    sh.offline = null;

    // An async-durability rewind below the bar.
    const s = try suspendAtTestBar(sh);
    r.last_applied = s - 1;
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    r.last_applied = s;

    // Opened as a follower, then elected: dropped, counted, and apply goes on.
    _ = try suspendAtTestBarAsFollower(sh);
    // Elected in a new term, with its no-op committed behind the window:
    // not ready until that applies.
    r.role = .leader;
    r.current_term += 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.ready_index = r.log.lastIndex();
    r.commit_index = r.log.lastIndex();
    const skips = sh.snapshot_skips_leader_not_ready;
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    try std.testing.expectEqual(skips + 1, sh.snapshot_skips_leader_not_ready);
    try std.testing.expectEqual(r.commit_index, r.last_applied);

    // Led when the window opened, then elected again in a later term: not
    // ready under the new term, so dropped too.
    _ = try suspendAtTestBar(sh);
    try std.testing.expect(r.leaderReady());
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window != null);
    r.current_term += 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.ready_index = r.log.lastIndex();
    r.commit_index = r.log.lastIndex();
    try std.testing.expect(!r.leaderReady());
    sh.stepSnapshotWindow();
    try std.testing.expect(sh.snapshot_window == null);
    try std.testing.expectEqual(skips + 2, sh.snapshot_skips_leader_not_ready);
    try std.testing.expectEqual(r.commit_index, r.last_applied);
}

/// `suspendAtTestBar` on a node acting as a follower: its entries are
/// proposed as leader, then applied as a follower applies them.
fn suspendAtTestBarAsFollower(sh: *Shard) !u64 {
    const r = sh.raft_node;
    r.role = .leader;
    sh.test_bar = r.log.lastIndex() + 1;
    _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
    r.role = .follower;
    _ = sh.applyCommitted();
    return sh.snapshot_window.?.s;
}

test "Shard: alone with a committed entry it can't read, writes past the cap are refused before they're proposed, not left in a wrapped slot" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [4096]u8 = undefined;
    var one: [1]proto.Response = undefined;
    // Reads blocked: committed entries wait unapplied, retried later.
    sh.read_blocked = true;
    sh.read_retry_at_ms = Shard.nowMs() + 60_000;
    var id: u64 = 1;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(sh, t.conn, .kv_put, id, "k", "v");
    }
    try std.testing.expectEqual(@as(u32, @intCast(raft_node_mod.MAX_OUTSTANDING)), sh.pending_count);
    const last = r.log.lastIndex();
    try ParkTest.send(sh, t.conn, .kv_put, id, "k", "v");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.overloaded), one[0].header.status);
    try std.testing.expectEqual(proto.Ran.no, (try one[0].refused()).ran);
    try std.testing.expectEqual(last, r.log.lastIndex());
    sh.read_blocked = false;
    sh.read_retry_at_ms = 0;
    // Apply runs in budgeted passes.
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(u32, 0), sh.pending_count);
}

test "Shard: a duty with an entry in flight during a window isn't proposed again" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "flow", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "flow", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try std.testing.expectEqual(@as(u32, 1), sh.workflow_handler.to_step.count());

    // Suspended: the first step's entry is proposed once, however many
    // passes the duty takes before it applies.
    _ = try suspendAtTestBar(sh);
    const from = sh.raft_node.log.lastIndex() + 1;
    for (0..5) |_| sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(sh, .workflow_step, from));
    try stepWindowClosed(sh);
    for (0..5) |_| sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(@as(usize, 1), entriesOf(sh, .workflow_step, from));
}

test "Shard: a stream trigger whose shard is capped while apply is suspended keeps its cursor, and starts a run for every event once room comes back" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const triggered =
        \\{"kind":"Workflow","name":"on-events","version":"1.0.0","trigger":{"stream":"events"},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "on-events", triggered);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);

    const events = 1500;
    for (0..events) |k| {
        var pbuf: [16]u8 = undefined;
        _ = try sh.stream_handler.appendPayloadToStream("events", "default", try std.fmt.bufPrint(&pbuf, "ev-{d}", .{k}));
        if (k % 256 == 0) _ = sh.applyCommitted();
    }
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();

    _ = try suspendAtTestBar(sh);
    const Tick = struct {
        fn triggers(s: *Shard) void {
            s.workflow_handler.triggers_dirty = true;
            s.workflow_handler.tickStreamTriggers(s);
        }
    };
    // Ten events a tick: enough ticks to reach the cap while suspended.
    for (0..200) |_| Tick.triggers(sh);
    try std.testing.expectEqual(raft_node_mod.MAX_OUTSTANDING, r.log.lastIndex() - r.last_applied);

    try stepWindowClosed(sh);
    for (0..400) |_| {
        Tick.triggers(sh);
        passes = 0;
        while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
        if (sh.workflow_handler.runCount() >= events) break;
    }
    try std.testing.expectEqual(@as(usize, events), sh.workflow_handler.runCount());
}

test "Shard: a stream trigger's starts lost to a step-down are proposed again when the node leads again, one run per event" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const triggered =
        \\{"kind":"Workflow","name":"on-events","version":"1.0.0","trigger":{"stream":"events"},
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "on-events", triggered);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    const events = 5;
    for (0..events) |k| {
        var pbuf: [16]u8 = undefined;
        _ = try sh.stream_handler.appendPayloadToStream("events", "default", try std.fmt.bufPrint(&pbuf, "ev-{d}", .{k}));
    }
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    const before = r.log.lastIndex();
    const committed = r.commit_index;

    sh.workflow_handler.triggers_dirty = true;
    sh.workflow_handler.tickStreamTriggers(sh);
    try std.testing.expectEqual(before + events, r.log.lastIndex());
    // It steps down before they commit; the next term's log holds none of
    // them, and the same node leads it.
    r.commit_index = committed;
    r.log.truncateAfter(before);
    r.current_term += 1;

    sh.workflow_handler.triggers_dirty = true;
    sh.workflow_handler.tickStreamTriggers(sh);
    passes = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(usize, events), sh.workflow_handler.runCount());
    // Read again in the same term, nothing starts twice.
    sh.workflow_handler.triggers_dirty = true;
    sh.workflow_handler.tickStreamTriggers(sh);
    passes = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(usize, events), sh.workflow_handler.runCount());
}

test "Shard: a workflow step the log is too full to take leaves the run as it was, and is taken once there's room" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    const r = sh.raft_node;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    _ = try proposeAction(sh, .action_register, testRegister("act"));
    _ = sh.applyCommitted();
    const def =
        \\{"kind":"Workflow","name":"flow","version":"1.0.0",
        \\"start":{"run":"@actions/act","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "flow", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "flow", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    var key_buf: [64]u8 = undefined;
    @memcpy(key_buf[0..4], &ns_table.Id.default.bytes());
    @memcpy(key_buf[4..][0..one[0].data.len], one[0].data);
    const key = key_buf[0 .. 4 + one[0].data.len];

    // The log fills while apply is suspended: the step can't be logged, so
    // the run neither moves nor fails.
    _ = try suspendAtTestBar(sh);
    var id: u64 = 10;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(sh, t.conn, .kv_put, id, "filler", "v");
    }
    const full = r.log.lastIndex();
    sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(full, r.log.lastIndex());
    try std.testing.expectEqual(@as(u32, 0), sh.workflow_handler.stepping.count());
    try std.testing.expectEqual(@as(u64, 0), sh.workflow_handler.inspect(key).?.rev);

    // Room again: the step is logged, and the run waits on its call.
    try stepWindowClosed(sh);
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();
    const run = sh.workflow_handler.inspect(key).?;
    try std.testing.expect(run.pending_action_run_id_owned != null);
    try std.testing.expectEqual(WorkflowHandler.RunStatus.waiting, run.status);
    for (run.history.items) |e| try std.testing.expect(!std.mem.eql(u8, e.event_type_owned, "workflow_failed"));
}

test "Shard: a plan step the log is too full for records nothing, however often it's tried, and its start once there's room" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    _ = try proposeAction(sh, .action_register, testRegister("act"));
    _ = sh.applyCommitted();
    const def =
        \\{"kind":"Workflow","name":"planned","version":"1.0.0",
        \\"plans":{"p":{"executors":[{"name":"only","run":"@actions/act"}]}},
        \\"start":{"run":"@plan/p","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "planned", def);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 2, "planned", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    var key_buf: [64]u8 = undefined;
    @memcpy(key_buf[0..4], &ns_table.Id.default.bytes());
    @memcpy(key_buf[4..][0..one[0].data.len], one[0].data);
    const key = key_buf[0 .. 4 + one[0].data.len];

    // The log full: however often it's tried, nothing is logged.
    try fillCapSuspended(&t);
    var tries: u32 = 0;
    while (tries < 3) : (tries += 1) sh.workflow_handler.advanceStartedRuns(sh);
    try std.testing.expectEqual(@as(u64, 0), sh.workflow_handler.inspect(key).?.rev);

    // Room: one step, its plan's start said once, waiting on its call.
    try resumeAndApply(sh);
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();
    const run = sh.workflow_handler.inspect(key).?;
    try std.testing.expect(run.pending_action_run_id_owned != null);
    try std.testing.expect(!run.waiting_for_room);
    try std.testing.expectEqual(@as(usize, 1), historyCount(run, "plan_executor_start"));
    try std.testing.expectEqual(@as(usize, 0), historyCount(run, "step_waiting_for_room"));
}

fn historyCount(run: *const WorkflowHandler.RunRecord, event: []const u8) usize {
    var n: usize = 0;
    for (run.history.items) |e| {
        if (std.mem.eql(u8, e.event_type_owned, event)) n += 1;
    }
    return n;
}

/// Fills the log to its cap with parked client writes, apply suspended.
fn fillCapSuspended(t: *AsyncAlone) !void {
    const r = t.shard.raft_node;
    _ = try suspendAtTestBar(&t.shard);
    var id: u64 = 1_000_000;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING) : (id += 1) {
        try ParkTest.send(&t.shard, t.conn, .kv_put, id, "filler", "v");
    }
}

/// Resumes and applies everything committed.
fn resumeAndApply(sh: *Shard) !void {
    try stepWindowClosed(sh);
    const r = sh.raft_node;
    var passes: u32 = 0;
    while (r.last_applied < r.commit_index and passes < 100) : (passes += 1) _ = sh.applyCommitted();
}

test "Shard: a workflow step whose child's call the log is too full to take waits at its start, and starts the child once there's room" {
    var t: AsyncAlone = undefined;
    try t.init();
    defer t.deinit();
    const sh = &t.shard;
    var buf: [2048]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const child =
        \\{"kind":"Workflow","name":"child","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"never"},"transitions":{"success":"flo.Completed"}}}
    ;
    const parent =
        \\{"kind":"Workflow","name":"parent","version":"1.0.0",
        \\"start":{"run":"@workflow/child","transitions":{"success":"flo.Completed","failure":"flo.Failed"}}}
    ;
    try ParkTest.send(sh, t.conn, .workflow_create, 1, "child", child);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_create, 2, "parent", parent);
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try ParkTest.send(sh, t.conn, .workflow_start, 3, "parent", "");
    try ParkTest.responses(sh, t.conn, t.pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();

    var key_buf: [64]u8 = undefined;
    @memcpy(key_buf[0..4], &ns_table.Id.default.bytes());
    @memcpy(key_buf[4..][0..one[0].data.len], one[0].data);
    const key = key_buf[0 .. 4 + one[0].data.len];

    // The log full: whatever the parent's step reached, its child isn't
    // started yet.
    try fillCapSuspended(&t);
    sh.workflow_handler.advanceStartedRuns(sh);
    sh.workflow_handler.checkPendingActions(sh);
    try std.testing.expectEqual(@as(usize, 1), sh.workflow_handler.runCount());

    // Room again: the parent's step is logged with its child's call.
    try resumeAndApply(sh);
    sh.workflow_handler.advanceStartedRuns(sh);
    _ = sh.applyCommitted();
    try std.testing.expect(sh.workflow_handler.inspect(key).?.pending_action_run_id_owned != null);
    // Its call reaches the child's slot, here, and this leader starts it.
    for (0..4) |_| {
        _ = sh.applyCommitted();
        sh.tickChannels();
        _ = sh.drainInbox();
        _ = sh.applyCommitted();
        sh.workflow_handler.checkPendingActions(sh);
    }
    _ = sh.applyCommitted();
    try std.testing.expectEqual(@as(usize, 2), sh.workflow_handler.runCount());
}

test "Shard: two replicas applying the same log find the same bars, the state a snapshot would encode moving between them" {
    Partition.test_bar_min_bytes = 600;
    defer Partition.test_bar_min_bytes = null;
    const allocator = std.testing.allocator;
    // Stream appends carry the bytes; KV puts (each also kept in the key's
    // history) and action registers move the state between bars.
    const n = 300;
    var bufs: [n][400]u8 = undefined;
    var entries: [n]entry_mod.Entry = undefined;
    for (&entries, 0..) |*e, i| {
        const index = i + 1;
        const len = (i * 13) % 90;
        var value: [90]u8 = undefined;
        @memset(value[0..len], 'v');
        if (i % 6 == 1) {
            var key = TEST_KV_K.* ++ [_]u8{'0' + @as(u8, @intCast(i % 9))};
            e.* = entry_mod.buildEntry(.kv_put, entry_mod.Flags.NONE, 1, index, index, try kv_entries.Put.encodeInto(&bufs[i], .{ .key = &key, .value = value[0..len], .ttl_ms = null, .condition = .always, .cas_version = null }));
        } else if (i % 25 == 3) {
            var name_buf: [8]u8 = undefined;
            const name = try std.fmt.bufPrint(&name_buf, "a{d}", .{i});
            var reg = testRegister(name);
            reg.owner = value[0 .. len % 40];
            e.* = try ActionsHandler.for_tests.entry(.action_register, reg, 1, index, index, &bufs[i]);
        } else {
            @memset(bufs[i][0..400], 's');
            e.* = entry_mod.buildEntry(.stream_append, entry_mod.Flags.NONE, 1, index, index, bufs[i][0..400]);
        }
    }
    var bars: [2][n]u64 = undefined;
    var states: [2][n]u64 = undefined;
    var found: [2]usize = .{ 0, 0 };
    var final: [2]u64 = undefined;
    for (0..2) |r| {
        var part = try Partition.init(allocator, 0, 8192, 0);
        defer part.deinit();
        part.wireProjections();
        var last: u64 = 0;
        var since: u64 = 0;
        for (&entries) |*e| {
            var out: persistence_mod.Result = .{};
            out.reset(e);
            const before = part.store.encodedBytes();
            const res = applyEntryCore(&part, null, e, &out);
            try std.testing.expect(res == .applied);
            // A bar is the first index whose bytes since the last reach the
            // larger of the minimum and the state before it.
            since += entry_mod.HEADER_SIZE + e.payload.len;
            const threshold = @max(600, before);
            try std.testing.expectEqual(since >= threshold, part.last_bar != last);
            if (part.last_bar != last) {
                since = 0;
                last = part.last_bar;
                bars[r][found[r]] = last;
                // The threshold the bar met: the state before its entry.
                states[r][found[r]] = before;
                found[r] += 1;
            }
        }
        final[r] = part.store.encodedBytes();
    }
    try std.testing.expect(found[0] >= 3);
    try std.testing.expectEqualSlices(u64, bars[0][0..found[0]], bars[1][0..found[1]]);
    try std.testing.expectEqualSlices(u64, states[0][0..found[0]], states[1][0..found[1]]);
    try std.testing.expectEqual(final[0], final[1]);
    // The state grew past the minimum, so later bars fell by it.
    try std.testing.expect(final[0] > 600);
    try std.testing.expect(states[0][found[0] - 1] > 600);
    try std.testing.expect(states[0][found[0] - 1] > states[0][0]);
}

test "Shard: boot replay finds the same bars as live apply did, and the same bytes since the last" {
    Partition.test_bar_min_bytes = 500;
    defer Partition.test_bar_min_bytes = null;
    var t: DamageTest = undefined;
    try t.init();
    defer t.deinit();
    var live_last: u64 = 0;
    var live_bytes: u64 = 0;
    var live_applied: u64 = 0;
    {
        var shard = try t.open();
        defer shard.deinit();
        // Stream appends add log bytes but no family state, so the bars come
        // from the minimum; a few KV puts move the state between them.
        const payload = @as([200]u8, @splat('s'));
        for (0..40) |i| {
            _ = try shard.stream_handler.appendPayloadToStream("s", "default", &payload);
            if (i % 8 == 0) {
                var kbuf: [16]u8 = undefined;
                _ = try @import("../kv/handler.zig").KVHandler.testProposePut(&shard, try std.fmt.bufPrint(&kbuf, "k{d}", .{i}), "v");
            }
            _ = shard.applyCommitted();
        }
        const part = shard.defaultPartition();
        live_last = part.last_bar;
        live_bytes = part.bar_bytes;
        live_applied = shard.raft_node.last_applied;
        try std.testing.expect(live_last > 0);
        try shard.flushSegmentToDisk();
    }
    var shard = try t.open();
    defer shard.deinit();
    shard.applyDeferredTail();
    try std.testing.expectEqual(live_last, shard.defaultPartition().last_bar);
    // The reopened node applies entries of its own past what live did (its
    // term's no-op): the count is live's plus theirs.
    var extra: u64 = 0;
    var i = live_applied + 1;
    while (i <= shard.raft_node.last_applied) : (i += 1) {
        const e = shard.raft_node.log.getEntry(i).?;
        extra += entry_mod.HEADER_SIZE + e.payload.len;
    }
    try std.testing.expectEqual(live_bytes + extra, shard.defaultPartition().bar_bytes);
}

/// Writes a message to `a`'s outbox as a sender's apply does: staged on a
/// view, written in its commit.
fn sendFromApply(a: *Shard, slot: u16, etype: entry_mod.EntryType, payload: []const u8) !void {
    const p = a.defaultPartition();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var keys = contract_view.KeySet.init(arena.allocator());
    var view = contract_view.View.init(&p.store, arena.allocator(), &keys);
    try view.send(.user(.default), slot, @backingInt(etype), payload);
    try channels_mod.writeSends(&view, a.raft_node.last_applied);
    try view.commit();
}

test "Shard: a message to another shard's slot is applied there once, through its target's machine, and its outbox is trimmed" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    // A key shard 1 owns.
    var kbuf: [16]u8 = undefined;
    var ki: usize = 0;
    const key = while (true) : (ki += 1) {
        const k = try std.fmt.bufPrint(&kbuf, "k{d}", .{ki});
        if (a.router.hashToShard(node_router.routeNsKey(.default, k)) == 1) break k;
    };
    const slot: u16 = @intCast(node_router.slot(node_router.routeNsKey(.default, key)));
    var full: [32]u8 = undefined;
    const ns_key = try std.fmt.bufPrint(&full, "{s}{s}", .{ ns_table.DEFAULT.bytes(), key });
    var pbuf: [128]u8 = undefined;
    const put = try kv_entries.Put.encodeInto(&pbuf, .{ .key = ns_key, .value = "from-a", .ttl_ms = null, .condition = .always, .cas_version = null });
    try sendFromApply(a, slot, .kv_put, put);

    const values_before = b.defaultPartition().store.families[kv_machine.Values.ID].count;
    for (0..8) |_| {
        a.tickChannels();
        b.tickChannels();
        two.settle();
    }
    // Applied on shard 1, once, by the KV machine.
    try std.testing.expectEqualStrings("from-a", b.kv_handler.kv.getIn(.default, key).?.value);
    try std.testing.expectEqual(values_before + 1, b.defaultPartition().store.families[kv_machine.Values.ID].count);
    try std.testing.expectEqual(@as(u64, 1), channels_mod.inOf(.{ .store = &b.defaultPartition().store }, 0, .main).?.applied);
    // Shard 0's outbox is empty, its message durably acked.
    try std.testing.expectEqual(@as(u64, 0), a.defaultPartition().store.families[channels_mod.OutFam.ID].count);
    try std.testing.expectEqual(@as(u64, 1), channels_mod.metaOf(.{ .store = &a.defaultPartition().store }, 1, .main).acked);
    // Shard 1 took it in one inbound entry: more ticks take nothing again.
    const b_log = b.raft_node.log.lastIndex();
    for (0..4) |_| {
        a.tickChannels();
        b.tickChannels();
        two.settle();
    }
    try std.testing.expectEqual(b_log, b.raft_node.log.lastIndex());
}

