    try std.testing.expectEqual(scans[1], b.channel.counts.scans);
    try std.testing.expectEqual(@as(usize, 0), a.mailbox.inbox.pending());
    try std.testing.expectEqual(@as(usize, 0), b.mailbox.inbox.pending());
}

test "Shard: with no channel traffic a tick sends no frame and proposes nothing" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const logs = [2]u64{ two.shards[0].raft_node.log.lastIndex(), two.shards[1].raft_node.log.lastIndex() };
    for (0..100) |_| {
        for (&two.shards) |*s| s.tickChannels();
        for (&two.shards) |*s| try std.testing.expectEqual(@as(usize, 0), s.mailbox.inbox.pending());
    }
    for (&two.shards, logs) |*s, l| try std.testing.expectEqual(l, s.raft_node.log.lastIndex());
    // Nothing was allocated for batches.
    for (&two.shards) |*s| try std.testing.expectEqual(@as(usize, 0), s.channel.buf.len);
}

test "Shard: a channel's durable index is what fsynced under sync, what the last flush wrote under async, and what applied with no data directory" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    // No data directory: whatever applied, since nothing is kept anyway.
    {
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        _ = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'A'});
        try std.testing.expect(shard.applyCommitted());
        try std.testing.expectEqual(shard.raft_node.last_applied, shard.channelDurable());
    }
    for ([_]Durability{ .sync, .async_flush }) |durability| {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        const data_dir = try testDataDir(&tmp);
        defer std.testing.allocator.free(data_dir);
        var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, durability, 1, .single, .{ .self_counts_when_durable = durability == .sync }, .{});
        defer shard.deinit();
        shard.wireHandlerShardPtrs();
        try std.testing.expect(shard.applyCommitted());
        const booted = shard.channelDurable();
        _ = try queue_handler_mod.proposeEnqueue(&shard, "q", &[_]u8{'A'});
        try std.testing.expect(shard.applyCommitted());
        const last = shard.raft_node.log.lastIndex();
        switch (durability) {
            // Applied means fsynced first.
            .sync => try std.testing.expectEqual(last, shard.channelDurable()),
            // Applied, but on disk only once a flush writes it.
            .async_flush => {
                try std.testing.expectEqual(booted, shard.channelDurable());
                try std.testing.expect(booted < last);
                try shard.flushSegmentToDisk();
                try std.testing.expectEqual(last, shard.channelDurable());
            },
        }
    }
}

/// A stream append's command payload, as a client's append logs it: one
/// record, under the default namespace.
fn streamAppendCommand(buf: []u8, name: []const u8, record: []const u8) ![]const u8 {
    var batch: [4 + 4 + 2048 + 2]u8 = undefined;
    std.debug.assert(record.len <= 2048);
    std.mem.writeInt(u32, batch[0..4], 1, .little);
    std.mem.writeInt(u32, batch[4..8], @intCast(record.len), .little);
    @memcpy(batch[8..][0..record.len], record);
    std.mem.writeInt(u16, batch[8 + record.len ..][0..2], 0, .little);
    const value = try stream_mod.encodeAppendValue(std.testing.allocator, 0, batch[0 .. 10 + record.len]);
    defer std.testing.allocator.free(value);
    return (entry_mod.buildCommandEntry(.stream_append, 0, 1, 1, 0, .default, name, value, buf) orelse return error.NoSpaceLeft).payload;
}

/// Record `i` of a test stream: `size` bytes, its number first.
fn channelRecord(buf: []u8, i: usize, size: usize) []const u8 {
    @memset(buf[0..size], @intCast('a' + i % 26));
    std.mem.writeInt(u32, buf[0..4], @intCast(i), .little);
    return buf[0..size];
}

/// `n` records of stream "s" sent by `s` to its own slot over its own
/// channel, `per_inbound` to a batch, each batch applied as one inbound.
/// Stops once the last applies, before any trim, so its log holds the
/// inbounds and nothing that needs the outbox again.
fn appendByChannel(s: *Shard, n: usize, size: usize, per_inbound: usize, flush_each: bool) !void {
    var sent: u64 = 0;
    var i: usize = 0;
    while (i < n) {
        const batch = @min(per_inbound, n - i);
        for (0..batch) |_| {
            var rb: [2048]u8 = undefined;
            var pb: [4096]u8 = undefined;
            try sendFromApply(s, 0, .stream_append, try streamAppendCommand(&pb, "s", channelRecord(&rb, i, size)));
            i += 1;
        }
        sent += batch;
        var rounds: usize = 0;
        while (true) : (rounds += 1) {
            try std.testing.expect(rounds < 50);
            const in = channels_mod.inOf(.{ .store = &s.defaultPartition().store }, @intCast(s.id), .main);
            if (in != null and in.?.applied == sent) break;
            s.tickChannels();
            _ = s.drainInbox();
            try std.testing.expect(s.applyCommitted());
        }
        if (flush_each) try s.flushSegmentToDisk();
    }
}

/// Every record of stream "s", read as a pipeline reads, landing disk reads
/// as the shard's tick does; each checked against `channelRecord`.
fn expectChannelRecords(s: *Shard, n: usize, size: usize) !void {
    var after = StreamID.MIN;
    var got: usize = 0;
    var idle: usize = 0;
    while (got < n) {
        const r = s.stream_handler.readPayloadsForStreamIn("s", .default, after, 64);
        defer r.deinit(std.testing.allocator);
        for (r.payloads) |p| {
            var want: [2048]u8 = undefined;
            try std.testing.expectEqualSlices(u8, channelRecord(&want, got, size), p);
            got += 1;
        }
        after = r.last_id;
        if (r.payloads.len > 0) {
            idle = 0;
            continue;
        }
        idle += 1;
        try std.testing.expect(idle < 2_000);
        if (s.stream_disk) |d| _ = d.drain();
        @import("stdx").time.sleep(std.time.ns_per_ms);
    }
    try std.testing.expectEqual(n, got);
}

test "Shard: two stream appends in one channel inbound are two records, in order, located in that inbound" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
