    var sm: @import("../metrics/registry.zig").ShardMetrics = .{ .shard_id = 1 };
    b.shard_metrics = &sm;
    defer b.shard_metrics = null;
    b.publishHealth();
    try std.testing.expectEqual(@as(u64, 1), sm.channel_sink_refusals.getPtrConst(.condition_failed).load(.monotonic));
