/// `sendFromApply`, with the message's entry flags.
fn sendFromApplyFlagged(a: *Shard, slot: u16, etype: entry_mod.EntryType, flags: u16, payload: []const u8) !void {
    const p = a.defaultPartition();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var keys = contract_view.KeySet.init(arena.allocator());
    var view = contract_view.View.init(&p.store, arena.allocator(), &keys);
    try view.sendFlagged(.user(.default), slot, @backingInt(etype), flags, payload);
    try channels_mod.writeSends(&view, a.raft_node.last_applied);
    try view.commit();
}

test "Shard: a history read stops at its record bytes with a cursor mid-chunk, says there is more, and pages on without skipping or repeating" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const a = &two.shards[0];
    const he = @import("../protocol/history_entries.zig");
    const hp = @import("../stream/history_producer.zig");
    var nb: [16]u8 = undefined;
    var ni: usize = 0;
    const owner = while (true) : (ni += 1) {
        const n = try std.fmt.bufPrint(&nb, "act{d}", .{ni});
        if (a.router.hashToShard(node_router.routeNsKey(.default, n)) == 0) break n;
    };
    const slot: u16 = @intCast(node_router.nsKeySlot(.default, owner));
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const al = arena.allocator();
    // Chunks of three 30 KiB events: more than twice a page's bytes in all.
    const CHUNKS = 8;
    const PER = 3;
    const detail = try al.alloc(u8, 30 << 10);
    @memset(detail, 'd');
    for (0..CHUNKS) |c| {
        var records: std.ArrayListUnmanaged(u8) = .empty;
        for (0..PER) |k| {
            const rec: hp.HistRec.Value = .{ .seq = c * PER + k, .event = "action_delivered", .detail = detail, .extra = "", .at_ms = 1 };
            const rb = try al.alloc(u8, try hp.HistRec.encodedSize(rec));
            var w: schema.Writer = .{ .buf = rb };
            try hp.HistRec.encode(&w, rec);
            try records.appendSlice(al, w.written());
        }
        const buf = try al.alloc(u8, he.Chunk.max_size);
        const p = try he.Chunk.encodeInto(buf, .{ .ns = ns_table.DEFAULT.int(), .family = @backingInt(he.Family.action), .owner = owner, .run = "r1", .created_ns = 5, .first_seq = c * PER, .last_seq = c * PER + PER - 1, .final = c + 1 == CHUNKS, .completed_ms = 4242, .records = records.items });
        try sendFromApplyFlagged(a, slot, .history_chunk, entry_mod.Flags.HISTORY, p);
        pumpChannels(&two);
    }
    for (0..4) |_| pumpChannels(&two);
    const total = CHUNKS * PER;
    // The walk stops at its record bytes, short of every chunk.
    const walked = try a.stream_handler.readHistory(al, .action, .default, owner, "r1", 5, 4242, .{ .from = 1 }, history_read.MAX_PAGE + 1, history_read.READ_BYTES);
    try std.testing.expect(walked.pieces.len < CHUNKS);
    const src: history_read.Source = .{ .family = .action, .ns = .default, .owner = owner, .run = "r1", .created_ns = 5, .ended_ms = 4242, .flushed = total, .pending = "" };
    const rv: contract_view.ReadView = .{ .store = &a.defaultPartition().store };
    // From seq 1, mid its first chunk, a page at a time: each says there
    // is more until the last, and together they are seqs 1.. once each.
    var next: u64 = 1;
    var cursor: ?u64 = 1;
    var pages: usize = 0;
    while (cursor) |from| : (pages += 1) {
        const q: history_read.Query = .{ .limit = history_read.MAX_PAGE, .cursor = from };
        const page = switch (try history_read.read(al, a.stream_handler, rv, src, q.window(), q.limit, false)) {
            .page => |pg| pg,
            else => return error.TestUnexpectedResult,
        };
        try std.testing.expect(page.events.len > 0);
        for (page.events) |e| {
            try std.testing.expectEqual(next, e.seq);
            next += 1;
        }
        cursor = page.more;
        if (cursor != null) try std.testing.expectEqual(next, cursor.?);
    }
    try std.testing.expectEqual(@as(u64, total), next);
    try std.testing.expect(pages > 1);
}

test "Shard: a run's history, sent to its own shard as it goes and folded, reads back oldest first, live and after it ends" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    const a = &two.shards[0];
    const he = @import("../protocol/history_entries.zig");
    // An action shard 0 owns.
    var nb: [16]u8 = undefined;
    var ni: usize = 0;
    const owner = while (true) : (ni += 1) {
        const n = try std.fmt.bufPrint(&nb, "act{d}", .{ni});
        if (a.router.hashToShard(node_router.routeNsKey(.default, n)) == 0) break n;
    };
    const slot: u16 = @intCast(node_router.nsKeySlot(.default, owner));
    const CHUNKS = 20;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    for (0..CHUNKS) |i| {
        var rb: [16]u8 = undefined;
        var buf: [he.Chunk.max_size]u8 = undefined;
        const p = try he.Chunk.encodeInto(&buf, .{ .ns = ns_table.DEFAULT.int(), .family = @backingInt(he.Family.action), .owner = owner, .run = "r1", .created_ns = 5, .first_seq = i + 1, .last_seq = i + 1, .final = i + 1 == CHUNKS, .completed_ms = 4242, .records = try std.fmt.bufPrint(&rb, "chunk-{d:0>2}", .{i + 1}) });
        try sendFromApplyFlagged(a, slot, .history_chunk, entry_mod.Flags.HISTORY, p);
        pumpChannels(&two);
        // Live, halfway: what landed so far, in order.
        if (i + 1 == 10) {
            const live = try a.stream_handler.readHistory(arena.allocator(), .action, .default, owner, "r1", 5, null, .{}, 100, std.math.maxInt(usize));
            try std.testing.expect(!live.pending);
            try std.testing.expectEqual(@as(usize, 10), live.pieces.len);
            for (live.pieces, 1..) |piece, n| try std.testing.expectEqual(@as(u64, n), piece.first_seq);
        }
    }
    for (0..4) |_| pumpChannels(&two);
    const read = try a.stream_handler.readHistory(arena.allocator(), .action, .default, owner, "r1", 5, 4242, .{}, 100, std.math.maxInt(usize));
    try std.testing.expect(!read.pending);
    try std.testing.expectEqual(@as(usize, CHUNKS), read.pieces.len);
    for (read.pieces, 1..) |piece, n| {
        var want: [16]u8 = undefined;
        try std.testing.expect(!piece.lost);
        try std.testing.expectEqual(@as(u64, n), piece.first_seq);
        try std.testing.expectEqualStrings(try std.fmt.bufPrint(&want, "chunk-{d:0>2}", .{n}), piece.records);
    }
    // A limit stops the walk where it says.
    const some = try a.stream_handler.readHistory(arena.allocator(), .action, .default, owner, "r1", 5, 4242, .{}, 3, std.math.maxInt(usize));
    try std.testing.expectEqual(@as(usize, 3), some.pieces.len);
    try std.testing.expectEqual(@as(u64, 3), some.pieces[2].last_seq);
    // The ended run is one row.
    const hm = @import("../stream/history_machine.zig");
    try std.testing.expectEqual(@as(u64, 1), a.defaultPartition().store.family(hm.Actions.ID).count);
    // A row whose entry the log no longer holds, and one naming a message
    // its inbound doesn't carry, read as lost for their events: never
    // passed over.
    {
        const st = &a.defaultPartition().store;
        const al = arena.allocator();
        const gone = try hm.liveRowKey(al, .default, owner, "r3", 7, 1 << 40, 1);
        const no_message = try hm.liveRowKey(al, .default, owner, "r3", 7, read.pieces.len + 2, 60);
        var ks = contract_view.KeySet.init(al);
        try ks.add(hm.Actions.ID, "", gone);
        try ks.add(hm.Actions.ID, "", no_message);
        var view = contract_view.View.init(st, al, &ks);
        view.strict = false;
        var row = std.mem.zeroes(hm.Row.Value);
        row.owner = owner;
        row.kind = @backingInt(he.Kind.chunk);
        row.ual_index = 1 << 40;
        row.part = 1;
        row.first_seq = 1;
        row.last_seq = 4;
        try view.put(hm.Actions, gone, .{ .v = row });
        row.ual_index = a.raft_node.last_applied;
        row.part = 60;
        row.first_seq = 5;
        row.last_seq = 6;
        try view.put(hm.Actions, no_message, .{ .v = row });
        try view.commit();
        // And one pointing at another run's index: never read as this run's.
        var ended = try hm.rowsOf(.{ .store = st }, al, .action, .default, owner, "r1", 5, 4242);
        const theirs = ended.next().?;
        const borrowed = try hm.liveRowKey(al, .default, owner, "r4", 8, theirs.ual_index, theirs.part);
        var ks2 = contract_view.KeySet.init(al);
        try ks2.add(hm.Actions.ID, "", borrowed);
        var view2 = contract_view.View.init(st, al, &ks2);
        view2.strict = false;
        var stolen = std.mem.zeroes(hm.Row.Value);
        stolen.owner = owner;
        stolen.kind = theirs.kind;
        stolen.ual_index = theirs.ual_index;
        stolen.part = theirs.part;
        stolen.first_seq = 1;
        stolen.last_seq = 20;
        try view2.put(hm.Actions, borrowed, .{ .v = stolen });
        try view2.commit();
        const other = try a.stream_handler.readHistory(al, .action, .default, owner, "r4", 8, null, .{}, 10, std.math.maxInt(usize));
        try std.testing.expectEqual(@as(usize, 1), other.pieces.len);
        try std.testing.expect(other.pieces[0].lost);
        const lost = try a.stream_handler.readHistory(al, .action, .default, owner, "r3", 7, null, .{}, 10, std.math.maxInt(usize));
        try std.testing.expect(!lost.pending);
        try std.testing.expectEqual(@as(usize, 2), lost.pieces.len);
        for (lost.pieces) |piece| try std.testing.expect(piece.lost);
        const firsts = [_]u64{ lost.pieces[0].first_seq, lost.pieces[1].first_seq };
        try std.testing.expect(std.mem.indexOfScalar(u64, &firsts, 1) != null and std.mem.indexOfScalar(u64, &firsts, 5) != null);
    }
}

/// A queue name shard `owner` of two owns, in the default namespace, and
/// its slot.
fn queueOwnedBy(two: *TwoShards, owner: u16, buf: []u8) !struct { name: []const u8, slot: u16 } {
    var i: usize = 0;
    while (true) : (i += 1) {
        const name = try std.fmt.bufPrint(buf, "q{d}", .{i});
        const h = node_router.routeNsKey(.default, name);
        if (two.shards[0].router.hashToShard(h) == owner) return .{ .name = name, .slot = @intCast(node_router.slot(h)) };
    }
}

/// A sink's enqueue of `body` to `queue`, which holds one message at most.
/// A receiver stamps its own caps over these, so a test across shards sets
/// them there too.
fn oneSlotEnqueue(buf: []u8, queue: []const u8, body: []const u8) ![]const u8 {
    return qe_caps.Enqueue.encodeInto(buf, .{ .ns = ns_table.DEFAULT.int(), .queue = queue, .priority = 0, .delay_ms = 0, .payload = body, .max_messages = 1, .max_bytes = 1 << 20, .shard_held_bytes = 1 << 30 });
}

fn purgeQueue(s: *Shard, queue: []const u8) !void {
    var pb: [128]u8 = undefined;
    _ = try s.raft_node.propose(.queue_purge, entry_mod.Flags.NONE, try qe_caps.Purge.encodeInto(&pb, .{ .ns = ns_table.DEFAULT.int(), .queue = queue }));
    try std.testing.expect(s.applyCommitted());
}

/// Channels and unparks run, as the shards' ticks run them, until settled.
fn pumpChannels(two: *TwoShards) void {
    for (0..8) |_| {
        for (&two.shards) |*s| {
            s.unpark_ms = 0;
            s.tickChannels();
        }
        two.settle();
    }
}

/// The bodies queue `name` on `s` holds, in order.
fn queueBodies(s: *Shard, name: []const u8, out: *[8][]const u8) usize {
    const qm = @import("../queue/machine.zig");
    var n: usize = 0;
    const read: contract_view.ReadView = .{ .store = &s.defaultPartition().store };
    const hash = qm.hashOf(name);
    var kb: [32]u8 = undefined;
    var it = read.range(qm.Msgs, qm.storeKey(&kb, ns_table.DEFAULT, &hash));
    while (it.next() catch null) |m| {
        if (n == out.len) break;
        out[n] = m.value.v.payload;
        n += 1;
    }
    return n;
}

test "Shard: a sink's enqueues to a full queue on another shard park, a KV write on the same channel applies, and room lets them drain in order" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    // The receiver's caps are what a sink's enqueue applies under: one
    // message at most.
    b.queue_handler.caps.max_messages = 1;
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    var eb: [3][256]u8 = undefined;
    for ([_][]const u8{ "first", "second", "third" }, 0..) |body, i| {
        try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try oneSlotEnqueue(&eb[i], q.name, body));
    }
    // A KV write on the same channel, after them.
    var kbuf: [16]u8 = undefined;
    var ki: usize = 0;
    const key = while (true) : (ki += 1) {
        const k = try std.fmt.bufPrint(&kbuf, "k{d}", .{ki});
        if (a.router.hashToShard(node_router.routeNsKey(.default, k)) == 1) break k;
    };
    var full: [32]u8 = undefined;
    var pbuf: [128]u8 = undefined;
    const put = try kv_entries.Put.encodeInto(&pbuf, .{ .key = try std.fmt.bufPrint(&full, "{s}{s}", .{ ns_table.DEFAULT.bytes(), key }), .value = "v", .ttl_ms = null, .condition = .always, .cas_version = null });
    try sendFromApply(a, @intCast(node_router.slot(node_router.routeNsKey(.default, key))), .kv_put, put);
    pumpChannels(&two);

    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    // The sink's three on the sink lane, the KV write on the main lane.
    try std.testing.expectEqual(@as(u64, 3), channels_mod.inOf(read, 0, .sink).?.applied);
    try std.testing.expectEqual(@as(u64, 1), channels_mod.inOf(read, 0, .main).?.applied);
    try std.testing.expectEqualStrings("v", b.kv_handler.kv.getIn(.default, key).?.value);
    try std.testing.expectEqual(@as(u64, 2), channels_mod.shardParked(read).count);
    var bodies: [8][]const u8 = undefined;
    try std.testing.expectEqual(@as(usize, 1), queueBodies(b, q.name, &bodies));
    try std.testing.expectEqualStrings("first", bodies[0]);
    // Each is a user's, from its queue's namespace: the origin check passes
    // them, and the channel's own parking touches the shard's records.
    for (b.channel.sender_bugs) |by_reason| for (by_reason) |n| try std.testing.expectEqual(@as(u64, 0), n);
    // Seen: counted for the shard, in /status and its metrics.
    var sm: @import("../metrics/registry.zig").ShardMetrics = .{ .shard_id = 1 };
    b.shard_metrics = &sm;
    defer b.shard_metrics = null;
    b.publishHealth();
    try std.testing.expectEqual(@as(u64, 2), sm.channel_parked_messages.load(.monotonic));
    try std.testing.expectEqual(@as(u64, 1), sm.channel_parked_targets.load(.monotonic));
    // The sender's outbox is trimmed: parked, the messages are the
    // receiver's to keep.
    try std.testing.expectEqual(@as(u64, 3), channels_mod.metaOf(.{ .store = &a.defaultPartition().store }, 1, .sink).acked);
    try std.testing.expectEqual(@as(u64, 1), channels_mod.metaOf(.{ .store = &a.defaultPartition().store }, 1, .main).acked);

    // Room for one: the next parked message, and only it.
    try purgeQueue(b, q.name);
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 1), queueBodies(b, q.name, &bodies));
    try std.testing.expectEqualStrings("second", bodies[0]);
    try std.testing.expectEqual(@as(u64, 1), channels_mod.shardParked(read).count);
    try purgeQueue(b, q.name);
    pumpChannels(&two);
    try std.testing.expectEqual(@as(usize, 1), queueBodies(b, q.name, &bodies));
    try std.testing.expectEqualStrings("third", bodies[0]);
    try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
}

/// A sink's enqueue of `body` to `queue`, which holds `max` messages at most.
fn sinkEnqueue(buf: []u8, queue: []const u8, body: []const u8, max: u32) ![]const u8 {
    return qe_caps.Enqueue.encodeInto(buf, .{ .ns = ns_table.DEFAULT.int(), .queue = queue, .priority = 0, .delay_ms = 0, .payload = body, .max_messages = max, .max_bytes = 1 << 20, .shard_held_bytes = 1 << 30 });
}

test "Shard: an unpark that took a whole entry's worth is followed at once, not after the wait, so a fast sink's target drains" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    // Each enqueue keeps the caps it was sent with: no receiver's caps
    // stamped over them.
    b.channel.stamp = null;
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    // One fills the queue; the next, capped at one, parks; the rest, which
    // fit, park behind it.
    const n = 3 * @import("../protocol/channel_entries.zig").MAX_BATCH;
    var eb: [256]u8 = undefined;
    var nb: [16]u8 = undefined;
    try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, "fill", 1));
    try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, "capped", 1));
    for (0..n) |i| try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, try std.fmt.bufPrint(&nb, "m{d}", .{i}), 1 << 20));
    pumpChannels(&two);
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    try std.testing.expectEqual(@as(u64, n + 1), channels_mod.shardParked(read).count);
    try purgeQueue(b, q.name);
    // Ticks with the wait never over: only a full unpark's follow-up runs.
    const st = &b.defaultPartition().store;
    b.unpark_ms = 0;
    var ticks: usize = 0;
    while (channels_mod.shardParked(read).count > 0 and ticks < 8) : (ticks += 1) {
        b.tickUnpark(st);
        b.unpark_ms = std.math.maxInt(u64);
        two.settle();
    }
    try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
    try std.testing.expectEqual(@as(usize, 4), ticks);
}

/// Fills shard 1's queue and parks one capped at it, and `n` behind
/// that capped at `cap` messages each; then empties the queue unless `purge` is
/// false. Each enqueue keeps the caps it was sent with.
fn parkBehindFull(two: *TwoShards, qb: []u8, n: usize, cap: u32, purge: bool) !void {
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    b.channel.stamp = null;
    const q = try queueOwnedBy(two, 1, qb);
    var eb: [256]u8 = undefined;
    var nb: [16]u8 = undefined;
    try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, "fill", 1));
    try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, "capped", 1));
    for (0..n) |i| try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb, q.name, try std.fmt.bufPrint(&nb, "m{d}", .{i}), cap));
    pumpChannels(two);
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    try std.testing.expectEqual(@as(u64, n + 1), channels_mod.shardParked(read).count);
    if (purge) try purgeQueue(b, q.name);
}

test "Shard: a full unpark followed at once is due at once, so the loop doesn't sleep between entries" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    var qb: [16]u8 = undefined;
    const n = 3 * @import("../protocol/channel_entries.zig").MAX_BATCH;
    try parkBehindFull(&two, &qb, n, 1 << 20, true);
    // Nothing else keeps this shard up: the loop's sleep is the unpark's.
    b.quota_propose_refused = true;
    b.more_work = false;
    b.apply_behind = false;
    b.producers_due = false;
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    const st = &b.defaultPartition().store;
    b.unpark_ms = 0;
    var entries: usize = 0;
    while (channels_mod.shardParked(read).count > 0 and entries < 8) : (entries += 1) {
        try std.testing.expectEqual(Shard.UnparkDue.now, b.unparkDue(@import("stdx").time.monotonicMs()));
        try std.testing.expectEqual(@as(u32, 0), b.loopTimeoutMs(false));
        b.tickUnpark(st);
        // The wait never over: only a full unpark's follow-up is due.
        b.unpark_ms = std.math.maxInt(u64);
        two.settle();
    }
    try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
    try std.testing.expectEqual(@as(usize, 4), entries);
    // The last carried one message, not a full entry: the next waits.
    try std.testing.expectEqual(Shard.UnparkDue.none, b.unparkDue(@import("stdx").time.monotonicMs()));
}

test "Shard: a full unpark that lands fewer than it carried waits out the interval, so a slot freed at a time draws no full entry each" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    var qb: [16]u8 = undefined;
    const max = @import("../protocol/channel_entries.zig").MAX_BATCH;
    // Each capped at one: after the purge only the first fits.
    try parkBehindFull(&two, &qb, 2 * max, 1, true);
    b.quota_propose_refused = true;
    b.more_work = false;
    b.apply_behind = false;
    b.producers_due = false;
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    b.unpark_ms = 0;
    b.tickUnpark(&b.defaultPartition().store);
    try std.testing.expectEqual(@as(u32, max), b.unpark_carried);
    b.unpark_ms = std.math.maxInt(u64);
    two.settle();
    try std.testing.expectEqual(@as(u64, 2 * max), channels_mod.shardParked(read).count);
    try std.testing.expect(!b.unpark_full);
    try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = Shard.UNPARK_EVERY_MS }, b.unparkDue(@import("stdx").time.monotonicMs()));
    try std.testing.expectEqual(@as(u32, Shard.UNPARK_EVERY_MS), b.loopTimeoutMs(false));
}

test "Shard: no unpark is due where tick runs no channels, while one is in flight, or with nothing parked, however primed" {
    const Case = enum { not_ready, offline, halted, follower, in_flight, nothing_parked };
    for (std.enums.values(Case)) |case| {
        var two: TwoShards = undefined;
        try two.init();
        defer two.deinit();
        const b = &two.shards[1];
        var qb: [16]u8 = undefined;
        try parkBehindFull(&two, &qb, 2, 1 << 20, true);
        const raft = b.raft_node;
        switch (case) {
            .not_ready => raft.ready_index = raft.last_applied + 1,
            .offline => b.offline = silent_loss.Damage.init(.applier_failed, "test", .{}),
            .halted => haltForTest(b, raft.last_applied + 1),
            .follower => raft.role = .follower,
            .in_flight => {
                b.unpark_ms = 0;
                b.tickUnpark(&b.defaultPartition().store);
                try std.testing.expect(b.unpark_index > raft.last_applied);
            },
            .nothing_parked => two.settle(),
        }
        if (case == .nothing_parked) {
            // The parking's own pumps tried, with no room, just now.
            b.unpark_ms = 0;
            b.tickUnpark(&b.defaultPartition().store);
            two.settle();
            const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
            try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
        }
        // Primed as if a full unpark just applied, long ago.
        b.unpark_full = true;
        b.unpark_term = raft.current_term;
        b.unpark_ms = 0;
        try std.testing.expectEqual(Shard.UnparkDue.none, b.unparkDue(@import("stdx").time.monotonicMs() + 1_000_000));
        // And the loop sleeps its whole 100 ms for it, nothing else waiting.
        b.more_work = false;
        b.apply_behind = false;
        b.producers_due = false;
        b.producers_deadline_ms = null;
        b.quota.clean = .{ .epoch = b.namespace_handler.table.quotaEpoch(), .term = raft.current_term };
        try std.testing.expectEqual(@as(u32, 100), b.loopTimeoutMs(false));
        if (case == .halted) b.halted = null;
        if (case == .offline) b.offline = null;
        if (case == .follower) raft.role = .leader;
    }
}

test "Shard: an unpark try that fails still moves the deadline a whole interval out, so the loop doesn't wake every millisecond" {
    const Case = enum { refused, no_buffers, no_room };
    for (std.enums.values(Case)) |case| {
        var two: TwoShards = undefined;
        try two.init();
        defer two.deinit();
        const b = &two.shards[1];
        var qb: [16]u8 = undefined;
        // No room: the queue stays full.
        try parkBehindFull(&two, &qb, 2, 1, case != .no_room);
        const raft = b.raft_node;
        const allocator = b.channel.allocator;
        switch (case) {
            .refused => raft.writes_stopped = true,
            .no_buffers => {
                allocator.free(b.channel.buf);
                allocator.free(b.channel.msgs);
                b.channel.buf = &.{};
                b.channel.msgs = &.{};
                b.channel.allocator = std.testing.failing_allocator;
            },
            .no_room => {},
        }
        const last = raft.log.lastIndex();
        b.unpark_full = true;
        b.unpark_term = raft.current_term;
        b.unpark_ms = 0;
        try std.testing.expectEqual(Shard.UnparkDue.now, b.unparkDue(@import("stdx").time.monotonicMs()));
        const at = @import("stdx").time.monotonicMs();
        b.tickUnpark(&b.defaultPartition().store);
        try std.testing.expectEqual(last, raft.log.lastIndex());
        try std.testing.expect(!b.unpark_full);
        try std.testing.expect(b.unpark_ms >= at);
        try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = Shard.UNPARK_EVERY_MS }, b.unparkDue(b.unpark_ms));
        b.channel.allocator = allocator;
        raft.writes_stopped = false;
    }
}

test "Shard: a group read not proposed is said at once for each reason, then once per window for it, with the count unsaid" {
    var t: Shard.LineThrottle = .{};
    try std.testing.expectEqual(@as(?u64, 0), t.take("Overloaded", 1_000));
    for (0..5) |k| try std.testing.expectEqual(@as(?u64, null), t.take("Overloaded", 1_000 + 29_999 - k));
    // Another reason's first is said at once, though the first's window holds.
    try std.testing.expectEqual(@as(?u64, 0), t.take("WritesStopped", 2_000));
    try std.testing.expectEqual(@as(?u64, 5), t.take("Overloaded", 31_000));
    try std.testing.expectEqual(@as(?u64, null), t.take("Overloaded", 31_001));
    // More reasons than slots: the one said longest ago gives way.
    var nb: [8]u8 = undefined;
    for (0..9) |k| _ = t.take(try std.fmt.bufPrint(&nb, "E{d}", .{k}), 40_000 + k);
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    a.noteGroupReadUnproposedAt("g\nx", "s\x1b", error.Overloaded, 1_000);
    a.noteGroupReadUnproposedAt("g", "s", error.Overloaded, 1_001);
    try std.testing.expectEqual(@as(?u64, 1), a.group_read_lines.take("Overloaded", 31_001));
}

test "Shard: the unpark's wait is reckoned from elapsed time, at any unpark_ms, and the loop sleeps the earliest of it and the pipelines' deadline" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    var qb: [16]u8 = undefined;
    try parkBehindFull(&two, &qb, 2, 1, false);
    // A boot's: 0, at an uptime under the interval and past it.
    b.unpark_ms = 0;
    try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = 100 }, b.unparkDue(0));
    try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = 60 }, b.unparkDue(40));
    try std.testing.expectEqual(Shard.UnparkDue.now, b.unparkDue(100));
    // Ahead of now, as a test that holds the wait sets it: no overflow.
    b.unpark_ms = std.math.maxInt(u64);
    try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = 100 }, b.unparkDue(@import("stdx").time.monotonicMs()));
    try std.testing.expectEqual(Shard.UnparkDue{ .in_ms = 100 }, b.unparkDue(std.math.maxInt(u64)));
    // The loop reads each wait on its own writer's clock: the unpark's on
    // the shard's, which set `unpark_ms`; the pipelines' deadline on the
    // processing handler's, held here far ahead of the shard's. Read on the
    // wrong clock, either wait lands outside these bounds.
    const Clock = struct {
        var now: u64 = 0;
        fn read() u64 {
            return now;
        }
    };
    Clock.now = @import("stdx").time.monotonicMs() + 1_000_000_000;
    const h_now: i64 = @intCast(Clock.now);
    b.processing_handler.mono_ms = Clock.read;
    defer b.processing_handler.mono_ms = @import("stdx").time.monotonicMs;
    b.quota_propose_refused = true;
    b.more_work = false;
    b.apply_behind = false;
    b.producers_due = false;
    b.producers_deadline_ms = null;
    // Stamped 10 ms back just before each call: correct code fails only
    // on a 90 ms stall between two adjacent lines.
    b.unpark_ms = @import("stdx").time.monotonicMs() - 10;
    const slept = b.loopTimeoutMs(false);
    try std.testing.expect(slept >= 1 and slept <= 90);
    b.producers_deadline_ms = h_now + 20;
    b.unpark_ms = @import("stdx").time.monotonicMs() - 10;
    try std.testing.expect(b.loopTimeoutMs(false) <= 20);
    b.producers_deadline_ms = h_now + 500;
    b.unpark_ms = @import("stdx").time.monotonicMs() - 10;
    const later = b.loopTimeoutMs(false);
    try std.testing.expect(later >= 1 and later <= 90);
    const t: i64 = 1_000_000;
    try std.testing.expectEqual(@as(u32, 30), Shard.sleepMs(t + 50, t, .{ .in_ms = 30 }));
    try std.testing.expectEqual(@as(u32, 10), Shard.sleepMs(t + 10, t, .{ .in_ms = 30 }));
    try std.testing.expectEqual(@as(u32, 30), Shard.sleepMs(null, t, .{ .in_ms = 30 }));
    try std.testing.expectEqual(@as(u32, 100), Shard.sleepMs(null, t, .{ .in_ms = 500 }));
    try std.testing.expectEqual(@as(u32, 100), Shard.sleepMs(null, t, .none));
    try std.testing.expectEqual(@as(u32, 1), Shard.sleepMs(t - 5, t, .none));
}

test "Shard: only this leader's own full unpark, applied whole, makes the next due at once; a partial one, or one of another term at its index, does not" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const b = &two.shards[1];
    var qb: [16]u8 = undefined;
    // Two behind the capped one, all with room after the purge: one entry
    // that isn't full.
    try parkBehindFull(&two, &qb, 2, 1 << 20, true);
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    b.unpark_ms = 0;
    b.tickUnpark(&b.defaultPartition().store);
    try std.testing.expectEqual(@as(u32, 0), b.unpark_carried);
    two.settle();
    try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
    try std.testing.expect(!b.unpark_full);
    // A full one's apply, matched by index and term.
    var e = entry_mod.buildEntry(.channel_unpark, entry_mod.Flags.NONE, b.unpark_term + 1, b.unpark_index, 0, "");
    b.unpark_carried = 64;
    b.unparkApplied(&e, 64);
    try std.testing.expect(!b.unpark_full);
    e.header.term = b.unpark_term;
    b.unparkApplied(&e, 63);
    try std.testing.expect(!b.unpark_full);
    b.unparkApplied(&e, 64);
    try std.testing.expect(b.unpark_full);
}

test "Shard: a leader in a new term unparks again past an unpark its last term left unapplied, and each message lands once, in order" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    // Each enqueue keeps the caps it was sent with, to fill the queue
    // for the first two only: no receiver's caps stamped over them.
    b.channel.stamp = null;
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    var eb: [3][256]u8 = undefined;
    for ([_][]const u8{ "first", "second", "third" }, 0..) |body, i| {
        try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try sinkEnqueue(&eb[i], q.name, body, if (i < 2) 1 else 8));
    }
    pumpChannels(&two);
    const read: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    try std.testing.expectEqual(@as(u64, 2), channels_mod.shardParked(read).count);
    try purgeQueue(b, q.name);
    const st = &b.defaultPartition().store;
    const raft = b.raft_node;
    // Proposed, and not applied before the term moves on.
    b.unpark_ms = 0;
    b.tickUnpark(st);
    const first = raft.log.lastIndex();
    try std.testing.expect(first > raft.last_applied);
    raft.current_term += 1;
    // Ready, as the loop needs before it tries: the unpark is keyed on
    // the term, not on readiness.
    raft.ready_index = raft.last_applied;
    // The new term's leader doesn't wait on it: it proposes its own.
    b.unpark_ms = 0;
    b.tickUnpark(st);
    try std.testing.expectEqual(first + 1, raft.log.lastIndex());
    // Both apply; the second finds them unparked already and changes nothing.
    try std.testing.expect(b.applyCommitted());
    try std.testing.expectEqual(@as(u64, 0), channels_mod.shardParked(read).count);
    var bodies: [8][]const u8 = undefined;
    try std.testing.expectEqual(@as(usize, 2), queueBodies(b, q.name, &bodies));
    try std.testing.expectEqualStrings("second", bodies[0]);
    try std.testing.expectEqualStrings("third", bodies[1]);
}

test "Shard: parked messages are the same on a replica that applies the same log" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    const a = &two.shards[0];
    const b = &two.shards[1];
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    two.settle();
    // The receiver's caps are what a sink's enqueue applies under: one
    // message at most.
    b.queue_handler.caps.max_messages = 1;
    var qb: [16]u8 = undefined;
    const q = try queueOwnedBy(&two, 1, &qb);
    var eb: [3][256]u8 = undefined;
    for ([_][]const u8{ "first", "second", "third" }, 0..) |body, i| {
        try sendFromApplyFlagged(a, q.slot, .queue_enqueue, entry_mod.Flags.SINK, try oneSlotEnqueue(&eb[i], q.name, body));
    }
    pumpChannels(&two);
    try std.testing.expectEqual(@as(u64, 2), channels_mod.shardParked(.{ .store = &b.defaultPartition().store }).count);

    // A replica of shard 1, as a restart or a new leader holds it: the same
    // log, applied.
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var r = try Shard.init(std.testing.allocator, 1, 2, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .single, .{}, .{ .namespaces = two.namespaces });
    defer r.deinit();
    r.wireHandlerShardPtrs();
    var i: u64 = r.raft_node.last_applied + 1;
    while (i <= b.raft_node.last_applied) : (i += 1) {
        const e = b.raft_node.log.getEntry(i).?;
        var out = persistence_mod.Result.start(&e);
        try std.testing.expect(r.applyEntry(&e, &out));
    }
    const rread: contract_view.ReadView = .{ .store = &r.defaultPartition().store };
    try std.testing.expectEqual(@as(u64, 2), channels_mod.shardParked(rread).count);
    try std.testing.expectEqual(b.defaultPartition().store.encodedBytes(), r.defaultPartition().store.encodedBytes());
}

/// A run's abandon, as a leader proposes one no client waits on.
fn testHandBack(buf: []u8, run_id: []const u8) ![]const u8 {
    return action_entries.Release.encodeInto(buf, .{ .ns = ns_table.Id.default.int(), .action = "a", .run = run_id, .holder = "w", .request_key = null, .deliveries = 1, .token = .{ .term = 1, .index = 1 }, .expiry_ns = 0, .abandoned = true, .retry = true, .delay_ms = 0, .@"error" = "" });
}

/// Proposes no-ops, uncommitted until the peer acks, until the log has
/// `room` left before it refuses for want of it.
fn fillLog(sh: *Shard, room: u64) !void {
    const r = sh.raft_node;
    while (r.log.lastIndex() - r.last_applied < raft_node_mod.MAX_OUTSTANDING - room) _ = try r.propose(.raft_noop, entry_mod.Flags.NONE, "");
}

fn handBacks(sm: *const ShardMetrics, kind: ShardMetrics.HandBackKind, outcome: ShardMetrics.HandBackOutcome) u64 {
    return sm.handbacks[@backingInt(kind)][@backingInt(outcome)].load(.monotonic);
}

test "Shard: a run whose taker went away, handed back while the log is full, is kept and proposed once there's room, counting no failure" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;
    try t.setUp(&.{"r1"}, t.shard.raft_node.now());
    const run = ActionsHandler.for_tests.run(&t.shard, .default, "r1").?;
    try std.testing.expectEqual(action_machine.Status.leased, run.status);

    // The task an orphaned answer handed back, its message committed here.
    var eb: [256]u8 = undefined;
    const e = try ActionsHandler.for_tests.entry(.action_abandon, action_entries.Abandon.Value{ .ns = ns_table.DEFAULT.int(), .action = "act", .run = "r1", .holder = "w1", .deliveries = run.deliveries, .token = run.token }, 1, 1, 1, &eb);
    var applied = persistence_mod.Result.start(&e);
    try fillLog(&t.shard, 0);
    t.shard.actions_handler.afterApply(&t.shard, &e, &applied);
    try std.testing.expectEqual(@as(usize, 1), t.shard.handbacks.items.len);

    // Room again: proposed on the next pass, and it applies.
    try ParkTest.ack(&t.shard);
    t.shard.retryHandBacks();
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 1), handBacks(&sm, .action, .retried));
    try ParkTest.ack(&t.shard);
    const back = ActionsHandler.for_tests.run(&t.shard, .default, "r1").?;
    try std.testing.expectEqual(action_machine.Status.ready, back.status);
    try std.testing.expectEqual(action_machine.Ended.abandoned, back.ended);
    try std.testing.expectEqual(@as(u32, 0), back.failures);
}

test "Shard: kept hand-backs go oldest first; one the log has no room for stays, and the ones after it" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    const until = t.shard.raft_node.now() + 60 * std.time.ns_per_s;
    var b1: [512]u8 = undefined;
    var b2: [512]u8 = undefined;
    try fillLog(&t.shard, 0);
    t.shard.proposeHandBack(.action, .action_release, try testHandBack(&b1, "r1"), until);
    t.shard.proposeHandBack(.action, .action_release, try testHandBack(&b2, "r2"), until);
    try std.testing.expectEqual(@as(usize, 2), t.shard.handbacks.items.len);
    // Room for one.
    try ParkTest.ack(&t.shard);
    try fillLog(&t.shard, 1);
    t.shard.retryHandBacks();
    try std.testing.expectEqual(@as(usize, 1), t.shard.handbacks.items.len);
    try std.testing.expect(std.mem.indexOf(u8, t.shard.handbacks.items[0].payload, "r2") != null);
}

test "Shard: a kept hand-back is given up at its lease's end, or past the cap, each counted dropped" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;
    const raft = t.shard.raft_node;
    var buf: [512]u8 = undefined;
    const payload = try testHandBack(&buf, "r1");

    // Its lease already over: given up on the next pass, not proposed.
    try fillLog(&t.shard, 0);
    t.shard.proposeHandBack(.action, .action_release, payload, raft.now() -| 1);
    try std.testing.expectEqual(@as(usize, 1), t.shard.handbacks.items.len);
    try ParkTest.ack(&t.shard);
    const tip = raft.log.lastIndex();
    t.shard.retryHandBacks();
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(tip, raft.log.lastIndex());
    try std.testing.expectEqual(@as(u64, 1), handBacks(&sm, .action, .dropped));

    // Full: the one past the cap is given up at once.
    try fillLog(&t.shard, 0);
    const until = raft.now() + 60 * std.time.ns_per_s;
    for (0..Shard.HANDBACK_MAX + 1) |_| t.shard.proposeHandBack(.action, .action_release, payload, until);
    try std.testing.expectEqual(@as(usize, Shard.HANDBACK_MAX), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 2), handBacks(&sm, .action, .dropped));
}

test "Shard: a kept hand-back isn't sent by a later term's leader, or once this node follows, even before its step-down is handled" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;
    const raft = t.shard.raft_node;
    var buf: [512]u8 = undefined;
    const payload = try testHandBack(&buf, "r1");
    const until = raft.now() + 60 * std.time.ns_per_s;
    try fillLog(&t.shard, 0);
    t.shard.proposeHandBack(.action, .action_release, payload, until);
    try ParkTest.ack(&t.shard);

    // A later term, still leading: the one kept in the old term goes.
    raft.current_term += 1;
    const tip = raft.log.lastIndex();
    t.shard.retryHandBacks();
    raft.current_term -= 1;
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(tip, raft.log.lastIndex());

    // Following, the step-down not yet handled: it goes too.
    try fillLog(&t.shard, 0);
    t.shard.proposeHandBack(.action, .action_release, payload, until);
    try ParkTest.ack(&t.shard);
    raft.role = .follower;
    t.shard.retryHandBacks();
    raft.role = .leader;
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 2), handBacks(&sm, .action, .dropped));
}

test "Shard: a step-down, and a stop, give up every kept hand-back, each counted dropped" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;
    var buf: [512]u8 = undefined;
    const payload = try testHandBack(&buf, "r1");
    const until = t.shard.raft_node.now() + 60 * std.time.ns_per_s;
    try fillLog(&t.shard, 0);
    for (0..3) |_| t.shard.proposeHandBack(.action, .action_release, payload, until);
    t.shard.refuseUnrunRequests();
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 3), handBacks(&sm, .action, .dropped));
    for (0..2) |_| t.shard.proposeHandBack(.action, .action_release, payload, until);
    t.shard.stoppedLeading("stepped down");
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 5), handBacks(&sm, .action, .dropped));
}

test "Shard: a hand-back refused for good is given up at once, not kept" {
    var t: AdminTest = undefined;
    try t.init(3, .join);
    defer t.deinit();
    var sm = ShardMetrics{ .shard_id = 0 };
    t.shard.shard_metrics = &sm;
    defer t.shard.shard_metrics = null;
    // Not leading: a new leader holds the lease, and its expiry returns it.
    t.shard.raft_node.role = .follower;
    var buf: [512]u8 = undefined;
    t.shard.proposeHandBack(.action, .action_release, try testHandBack(&buf, "r1"), t.shard.raft_node.now() + std.time.ns_per_s);
    try std.testing.expectEqual(@as(usize, 0), t.shard.handbacks.items.len);
    try std.testing.expectEqual(@as(u64, 1), handBacks(&sm, .action, .dropped));
}

/// A test message's origin: the default namespace's user.
const TEST_USER: u8 = @backingInt(@import("../contract/view.zig").Origin.Kind.user);
const TEST_DEFAULT_NS: u32 = @import("../namespace/table.zig").DEFAULT.int();

/// A group's records applied straight to the shard's store, as their
/// entries would leave them: `n` records of "s", delivered to "w" at `stamp`.
fn groupDelivered(sh: *Shard, n: u64, stamp: u64) !void {
    const p = sh.defaultPartition();
    for (0..n) |i| try testStreamAppend(p, "s", i + 1, 1, 1);
    var pb: [ge_mod.Deliver.max_size]u8 = undefined;
    const body = try ge_mod.Deliver.encodeInto(&pb, .{ .ns = 1, .stream = "s", .group = "g", .count = @intCast(n), .max_bytes = 1 << 20, .holder = "w", .lease_ms = 30_000, .create = true, .ready = .{ .bytes = "", .count = 0 }, .through_ms = std.math.maxInt(u64), .through_seq = std.math.maxInt(u64), .max_held = qe_caps.DEFAULT_MAX_MESSAGES, .max_held_bytes = qe_caps.DEFAULT_MAX_BYTES, .shard_held_bytes = qe_caps.DEFAULT_SHARD_HELD_BYTES });
    try applyGroupEntry(sh, .group_deliver, body, 50, stamp);
}

fn applyGroupEntry(sh: *Shard, etype: entry_mod.EntryType, body: []const u8, index: u64, stamp: u64) !void {
    const p = sh.defaultPartition();
    const e = entry_mod.buildEntry(etype, entry_mod.Flags.NONE, 1, index, stamp, body);
    var out: persistence_mod.Result = .{};
    out.reset(&e);
    try contract_machine.applyEntry(&@import("../stream/group_machine.zig").machine, &p.store, &p.apply_scratch, &e, &out);
    try std.testing.expect(out.refused() == null);
}

/// The one answer a group operator request got, decoded by its op.
fn groupOpAnswer(comptime name: []const u8, t: *ClusterActionsTest, code: proto.OpCode, id: u64, body: []const u8) !table_run.op(name).response.Value {
    t.shard.runRequest(t.c.conn, .{ .header = proto.RequestHeader.init(code, id), .namespace = "default", .key = "s", .value = body }, .client);
    if (table_run.op(name).class == .write) try ParkTest.ack(&t.shard);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.c.conn, t.c.pair[1], &t.buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    var diag: schema.Diagnostic = .{};
    return table_run.op(name).response.decodeAll(one[0].data, &diag);
}

test "Shard: stream.group.steal takes a record idle at least min_idle_ms for its consumer, for lease_ms or the group's lease, and refuses one not idle" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    // Delivered five seconds ago, by the log's clock.
    try groupDelivered(&t.shard, 2, t.shard.raft_node.now() - 5 * std.time.ns_per_s);
    const Steal = table_run.op("stream.group.steal");
    var rb: [256]u8 = undefined;
    var w: schema.Writer = .{ .buf = &rb };
    // Appended at the same instant: ids 1-0 and 1-1.
    for (0..2) |seq| try stream_ops.Leased.encode(&w, .{ .ms = 1, .seq = seq, .deliveries = 1 });
    var body_buf: [Steal.request.max_size]u8 = undefined;
    // Read moments ago: not idle a minute.
    const busy = try groupOpAnswer("stream.group.steal", &t, .stream_group_steal, 1, try Steal.request.encodeInto(&body_buf, .{ .group = "g", .consumer = "rescue", .min_idle_ms = 60_000, .lease_ms = null, .records = .{ .bytes = rb[0..w.pos], .count = 2 } }));
    try std.testing.expectEqual(@as(u32, 0), busy.stolen.count);
    try std.testing.expectEqual(@as(u32, 2), busy.refused.count);
    var rit = busy.refused.iterator();
    try std.testing.expectEqual(queue_ops.Why.not_idle, (try rit.next()).?.why);

    const took = try groupOpAnswer("stream.group.steal", &t, .stream_group_steal, 2, try Steal.request.encodeInto(&body_buf, .{ .group = "g", .consumer = "rescue", .min_idle_ms = 1, .lease_ms = 10_000, .records = .{ .bytes = rb[0..w.pos], .count = 2 } }));
    try std.testing.expectEqual(@as(u32, 2), took.stolen.count);
    var sit = took.stolen.iterator();
    try std.testing.expectEqual(@as(u32, 2), (try sit.next()).?.deliveries);
    try std.testing.expectEqual(t.shard.raft_node.current_term, took.term);
    // For the lease it named, from its entry's stamp.
    const left = took.expires_at_ms - @as(i64, @intCast(t.shard.raft_node.now() / std.time.ns_per_ms));
    try std.testing.expect(left > 9_000 and left <= 10_000);
}

