test "Shard: stream.group.dlq_list pages a group's dead letters by limit and after; dlq_requeue and dlq_delete take records or all up to a limit, never both, and a dry_run deletes nothing" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    const now = t.shard.raft_node.now();
    try groupDelivered(&t.shard, 3, now);
    // All three nacked dead.
    var ib: [256]u8 = undefined;
    var iw: schema.Writer = .{ .buf = &ib };
    for (0..3) |seq| try ge_mod.Item.encode(&iw, .{ .ms = 1, .seq = seq, .deliveries = 1 });
    var rel: [ge_mod.Release.max_size]u8 = undefined;
    const body = try ge_mod.Release.encodeInto(&rel, .{ .ns = 1, .stream = "s", .group = "g", .holder = "w", .token = .{ .term = 1, .index = 50 }, .expiry_ns = now + 30 * std.time.ns_per_s, .items = .{ .bytes = ib[0..iw.pos], .count = 3 }, .delay_ms = 0, .dead = true, .@"error" = "boom", .ended = .failed });
    try applyGroupEntry(&t.shard, .group_release, body, 51, now + 1);

    const List = table_run.op("stream.group.dlq_list");
    var lb: [List.request.max_size]u8 = undefined;
    const first = try groupOpAnswer("stream.group.dlq_list", &t, .stream_group_dlq_list, 1, try List.request.encodeInto(&lb, .{ .group = "g", .limit = 2, .after = null }));
    try std.testing.expectEqual(@as(u32, 2), first.dead.count);
    const rest = try groupOpAnswer("stream.group.dlq_list", &t, .stream_group_dlq_list, 2, try List.request.encodeInto(&lb, .{ .group = "g", .limit = 2, .after = first.cursor.? }));
    try std.testing.expectEqual(@as(u32, 1), rest.dead.count);
    try std.testing.expect(rest.cursor == null);

    const Requeue = table_run.op("stream.group.dlq_requeue");
    var qb: [Requeue.request.max_size]u8 = undefined;
    var rr: [64]u8 = undefined;
    var rw: schema.Writer = .{ .buf = &rr };
    try stream_ops.RecordRef.encode(&rw, .{ .ms = 1, .seq = 0 });
    const rq = try groupOpAnswer("stream.group.dlq_requeue", &t, .stream_group_dlq_requeue, 3, try Requeue.request.encodeInto(&qb, .{ .group = "g", .records = .{ .bytes = rr[0..rw.pos], .count = 1 }, .all = false, .limit = 100 }));
    try std.testing.expectEqual(@as(u32, 1), rq.applied);
    // Records and all at once: refused, neither dropped.
    t.shard.runRequest(t.c.conn, .{ .header = proto.RequestHeader.init(.stream_group_dlq_requeue, 9), .namespace = "default", .key = "s", .value = try Requeue.request.encodeInto(&qb, .{ .group = "g", .records = .{ .bytes = rr[0..rw.pos], .count = 1 }, .all = true, .limit = 100 }) }, .client);
    var both: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.c.conn, t.c.pair[1], &t.buf, &both);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), both[0].header.status);

    const Delete = table_run.op("stream.group.dlq_delete");
    var db: [Delete.request.max_size]u8 = undefined;
    const dry = try groupOpAnswer("stream.group.dlq_delete", &t, .stream_group_dlq_delete, 4, try Delete.request.encodeInto(&db, .{ .group = "g", .records = null, .all = true, .limit = 100, .dry_run = true }));
    try std.testing.expectEqual(@as(u32, 2), dry.applied);
    // A limit of one takes one, and says more remain.
    const one = try groupOpAnswer("stream.group.dlq_delete", &t, .stream_group_dlq_delete, 5, try Delete.request.encodeInto(&db, .{ .group = "g", .records = null, .all = true, .limit = 1, .dry_run = false }));
    try std.testing.expectEqual(@as(u32, 1), one.applied);
    try std.testing.expect(one.more);
    const del = try groupOpAnswer("stream.group.dlq_delete", &t, .stream_group_dlq_delete, 6, try Delete.request.encodeInto(&db, .{ .group = "g", .records = null, .all = true, .limit = 100, .dry_run = false }));
    try std.testing.expectEqual(@as(u32, 1), del.applied);
    try std.testing.expect(!del.more);
    const empty = try groupOpAnswer("stream.group.dlq_list", &t, .stream_group_dlq_list, 7, try List.request.encodeInto(&lb, .{ .group = "g", .limit = 20, .after = null }));
    try std.testing.expectEqual(@as(u32, 0), empty.dead.count);
}

/// An action name and a workflow name in the default namespace whose slots
/// shards `action_on` and `workflow_on` own.
fn callNames(two: *TwoShards, action_on: u16, workflow_on: u16, ab: []u8, wb: []u8) !struct { action: []const u8, workflow: []const u8 } {
    const r = &two.shards[0].router;
    var i: usize = 0;
    const action = while (true) : (i += 1) {
        const n = try std.fmt.bufPrint(ab, "act{d}", .{i});
        if (r.slotToShard(node_router.nsKeySlot(.default, n)) == action_on) break n;
    };
    i = 0;
    const workflow = while (true) : (i += 1) {
        const n = try std.fmt.bufPrint(wb, "wf{d}", .{i});
        if (r.slotToShard(node_router.nsKeySlot(.default, n)) == workflow_on) break n;
    };
    return .{ .action = action, .workflow = workflow };
}

/// A step's call of `action`'s run `run` proposed on `s`, as the workflow
/// handler makes it: a run of `workflow` ("c-" and the callee's id) started,
/// then its step waiting on the call.
fn proposeCall(s: *Shard, action: []const u8, workflow: []const u8, run: []const u8, can_wait: bool) !void {
    return proposeCallOf(s, .action, action, workflow, run, can_wait);
}

fn proposeCallOf(s: *Shard, kind: action_entries.CallKind, target: []const u8, workflow: []const u8, run: []const u8, can_wait: bool) !void {
    const a = std.testing.allocator;
    var cb: [64]u8 = undefined;
    const caller = try std.fmt.bufPrint(&cb, "c-{s}", .{run});
    var kb: [80]u8 = undefined;
    @memcpy(kb[0..4], &ns_table.Id.default.bytes());
    @memcpy(kb[4..][0..caller.len], caller);
    const key = kb[0 .. 4 + caller.len];
    var vb: [96]u8 = undefined;
    const value = (@import("../workflow/runs_machine.zig").Start{ .workflow = workflow, .version = "1", .status = .running, .event = "", .idem = null, .input = "" }).encode(&vb).?;
    _ = try persistence_mod.proposeEntryIn(s, .workflow_start, entry_mod.Flags.NONE, .default, key, value);

    const call_buf = try a.alloc(u8, action_entries.Call.max_size);
    defer a.free(call_buf);
    const call = try action_entries.Call.encodeInto(call_buf, .{ .ns = ns_table.DEFAULT.int(), .kind = kind, .caller_run = caller, .caller_workflow = workflow, .step = "s", .target = target, .version = "", .run = run, .input = "{}", .can_wait = can_wait });
    const runs_machine = @import("../workflow/runs_machine.zig");
    // Applied, so the step names the run's incarnation.
    _ = s.applyCommitted();
    const step: runs_machine.Step.Value = .{
        .created_ns = runs_machine.runOf(.{ .store = &s.defaultPartition().store }, key).?.created_ns,
        .rev = 0,
        .step = "s",
        .events = .{ .bytes = "", .count = 0 },
        .outputs = .{ .bytes = "", .count = 0 },
        .wait = .call,
        .wait_kind = kind,
        .wait_slot = @intCast(node_router.nsKeySlot(.default, target)),
        .wait_on = run,
        .wait_due_ms = 0,
        .wait_timeout_to = "",
        .progress = "",
        .settles = "",
        .takes = .{ .bytes = "", .count = 0 },
        .caller_slot = calls_machine.callerSlot(.default, workflow),
        .workflow = workflow,
        .ends = 0,
        .has_output = false,
        .output = "",
        .call = call,
    };
    const step_buf = try a.alloc(u8, persistence_mod.MAX_PERSIST_PAYLOAD);
    defer a.free(step_buf);
    _ = try persistence_mod.proposeEntryIn(s, .workflow_step, entry_mod.Flags.NONE, .default, key, try runs_machine.Step.encodeInto(step_buf, step));
}

fn callIn(s: *Shard, workflow: []const u8, run: []const u8) ?calls_machine.Call.Value {
    return calls_machine.callOf(.{ .store = &s.defaultPartition().store }, .default, calls_machine.callerSlot(.default, workflow), run);
}

/// A worker on `b` takes `action`'s next run and completes it with `result`.
fn completeNext(two: *TwoShards, b: *Shard, action: []const u8, result: []const u8) !void {
    const c = try TestClient.open(b);
    defer _ = std.c.close(c.pair[1]);
    var aw: [64]u8 = undefined;
    var out: [4096]u8 = undefined;
    b.runRequest(c.conn, try ParkTest.request(.action_await, 31, proto.DEFAULT_NAMESPACE, "w", try ActionsHandler.for_tests.awaitBody(&aw, &.{action}, 0, null), ""), .client);
    two.settle();
    const task = (try ActionsHandler.for_tests.task((try nextAnswer(c, b, &out)).data)).?;
    var done: [512]u8 = undefined;
    b.runRequest(c.conn, try ParkTest.request(.action_complete, 32, proto.DEFAULT_NAMESPACE, task.run, try ActionsHandler.for_tests.completeBody(&done, task, "w", "", result), ""), .client);
    two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(c, b, &out)).header.status);
}

test "Shard: a step's call of an action on another shard is answered there, and its run's end comes back to the call" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const a = &two.shards[0];
    const b = &two.shards[1];
    var ab: [16]u8 = undefined;
    var wb: [16]u8 = undefined;
    const n = try callNames(&two, 1, 0, &ab, &wb);
    // Chosen as a step chooses it: in the action's slot, so the run's
    // reports route to its shard.
    var rb: [run_id_mod.MAX_ID_LEN]u8 = undefined;
    const rid = a.run_id_gen.next(.action, node_router.nsKeySlot(.default, n.action), a.raft_node.current_term, &rb);
    _ = try proposeAction(b, .action_register, testRegister(n.action));
    two.settle();
    try proposeCall(a, n.action, n.workflow, rid, false);
    two.settle();
    try std.testing.expectEqual(calls_machine.State.sent, callIn(a, n.workflow, rid).?.state);
    pumpChannels(&two);
    // Started there, under the call's run id, naming its caller; answered here.
    const run = ActionsHandler.for_tests.run(b, .default, rid).?;
    try std.testing.expectEqualStrings(n.workflow, run.caller_workflow.?);
    try std.testing.expectEqual(calls_machine.State.started, callIn(a, n.workflow, rid).?.state);
    // Its end comes back with what it returned.
    try completeNext(&two, b, n.action, "{\"ok\":1}");
    pumpChannels(&two);
    const c = callIn(a, n.workflow, rid).?;
    try std.testing.expectEqual(calls_machine.State.done, c.state);
    try std.testing.expectEqual(@backingInt(action_entries.DoneStatus.completed), c.status);
    try std.testing.expectEqualStrings("{\"ok\":1}", c.result);
    // Cleared, it goes.
    _ = try proposeAction(a, .step_call_clear, action_entries.CallClear.Value{ .ns = ns_table.DEFAULT.int(), .slot = calls_machine.callerSlot(.default, n.workflow), .run = rid });
    two.settle();
    try std.testing.expect(callIn(a, n.workflow, rid) == null);
}

test "Shard: a step's call whose start a repair skipped is refused, saying so, and its action never runs" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const a = &two.shards[0];
    const b = &two.shards[1];
    var ab: [16]u8 = undefined;
    var wb: [16]u8 = undefined;
    const n = try callNames(&two, 1, 0, &ab, &wb);
    var rb: [run_id_mod.MAX_ID_LEN]u8 = undefined;
    const rid = a.run_id_gen.next(.action, node_router.nsKeySlot(.default, n.action), a.raft_node.current_term, &rb);
    _ = try proposeAction(b, .action_register, testRegister(n.action));
    two.settle();
    try proposeCall(a, n.action, n.workflow, rid, false);
    two.settle();
    // The inbound carrying the start is skipped, as a committed repair has it.
    b.defaultPartition().store.inbound_skip = .all(4242);
    pumpChannels(&two);
    b.defaultPartition().store.inbound_skip = null;
    pumpChannels(&two);
    try std.testing.expect(ActionsHandler.for_tests.run(b, .default, rid) == null);
    const c = callIn(a, n.workflow, rid).?;
    try std.testing.expectEqual(calls_machine.State.refused, c.state);
    try std.testing.expect(std.mem.indexOf(u8, c.outcome, "skipped by repair (entry 4242") != null);
}

