    var wb: [16]u8 = undefined;
    const n = try callNames(&two, 1, 0, &ab, &wb);
    const task: action_ops_mod.Task.Value = .{ .run = "r-x", .namespace = "default", .deliveries = 1, .term = 1, .index = 5, .action = n.action, .created_at_ms = 0, .attempt = 1, .lease_ms = 5000, .caller_run = null, .caller_workflow = null, .input = "" };
    a.outbox_caps = .{ .other = .{ .shard = 0, .channel = 1 << 30 } };
    const before = a.raft_node.log.lastIndex();
    a.actions_handler.handBack(a, .default, "", task);
    try std.testing.expectEqual(before, a.raft_node.log.lastIndex());
    try std.testing.expectEqual(@as(u64, 1), handBacks(&sm, .action, .dropped));
    // With room it is logged and sent.
    a.outbox_caps = .{};
    a.actions_handler.handBack(a, .default, "", task);
    try std.testing.expectEqual(before + 1, a.raft_node.log.lastIndex());
}

test "actions: a called run's lease isn't ended on any attempt while its end has no room, and status says which shard it waits on" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    // Three attempts: the first lease's end would run it again.
    _ = try applyActionEntry(&t.shard, .action_register, testRegister("act"), 1, 1);
    var called = testInvoke("act", "r1");
    called.source = .workflow;
    called.caller_run = "wf-run";
    called.caller_workflow = "wf";
    _ = try applyActionEntry(&t.shard, .action_invoke, called, 2, 1);
    _ = try applyActionEntry(&t.shard, .action_deliver, action_entries.Deliver.Value{ .ns = ns_table.DEFAULT.int(), .action = "act", .run = "r1", .due_ns = 1, .holder = "w1", .request_key = null, .lease_ms = 5000 }, 10, 2);
    var metrics = MetricsRegistry.init(std.testing.allocator);
    defer metrics.deinit();
    t.shard.setMetricsRegistry(&metrics);
    const actions = t.shard.actions_handler;
    _ = actions.expireDue(&t.shard);
    actions.duty_since_ns = 0;
    t.shard.outbox_caps = .{ .other = .{ .shard = 0, .channel = 1 << 30 } };
    try std.testing.expectEqual(@as(u64, 0), actions.expireDue(&t.shard));
    try std.testing.expectEqual(action_machine.Status.leased, ActionsHandler.for_tests.run(&t.shard, .default, "r1").?.status);
    try std.testing.expectEqual(@as(u64, 1), metrics.workflow.action_expires_held.load(.monotonic));
    try std.testing.expect(actions.held_expires.count() == 1);
    // A client asking about it is told why.
    t.shard.runRequest(t.c.conn, .{ .header = proto.RequestHeader.init(.action_status, 40), .namespace = "", .key = "r1", .value = "" }, .client);
    var one: [1]proto.Response = undefined;
    try ParkTest.responses(&t.shard, t.c.conn, t.c.pair[1], &t.buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    var diag: schema.Diagnostic = .{};
    const st = try table_run.op("action.status").response.decodeAll(one[0].data, &diag);
    try std.testing.expectEqualStrings("its end waits for room on shard 0", st.held.?);
    // Room: its first lease ends, and it is ready again.
    t.shard.outbox_caps = .{};
    try std.testing.expectEqual(@as(u64, 1), actions.expireDue(&t.shard));
    try ParkTest.ack(&t.shard);
    const back = ActionsHandler.for_tests.run(&t.shard, .default, "r1").?;
    try std.testing.expectEqual(action_machine.Status.ready, back.status);
    try std.testing.expectEqual(@as(u32, 1), back.failures);
    try std.testing.expectEqual(@as(u64, 0), metrics.workflow.action_expires_held.load(.monotonic));
}

test "actions: more held leases than one expire pass looks at don't keep an ordinary lease behind them from ending" {
    var t: ClusterActionsTest = undefined;
    try t.init();
    defer t.deinit();
    var reg = testRegister("act");
    reg.max_attempts = 1;
    _ = try applyActionEntry(&t.shard, .action_register, reg, 1, 1);
    // More called runs than a pass looks at, their leases due first; then
    // a client's, due after them all.
    const held_n = ActionsHandler.EXPIRE_SCAN_MAX + 4;
    var idx: u64 = 2;
    var names: [held_n][8]u8 = undefined;
    for (&names, 0..) |*b, i| {
        const r = try std.fmt.bufPrint(b, "c{d}", .{i});
        var called = testInvoke("act", r);
        called.source = .workflow;
        called.caller_run = "wf-run";
        called.caller_workflow = "wf";
        _ = try applyActionEntry(&t.shard, .action_invoke, called, idx, 1);
        idx += 1;
        _ = try applyActionEntry(&t.shard, .action_deliver, action_entries.Deliver.Value{ .ns = ns_table.DEFAULT.int(), .action = "act", .run = r, .due_ns = 1, .holder = "w1", .request_key = null, .lease_ms = 5000 }, idx, 2);
        idx += 1;
    }
    _ = try applyActionEntry(&t.shard, .action_invoke, testInvoke("act", "plain"), idx, 1);
    idx += 1;
    _ = try applyActionEntry(&t.shard, .action_deliver, action_entries.Deliver.Value{ .ns = ns_table.DEFAULT.int(), .action = "act", .run = "plain", .due_ns = 1, .holder = "w2", .request_key = null, .lease_ms = 5000 }, idx, 3);
    var metrics = MetricsRegistry.init(std.testing.allocator);
    defer metrics.deinit();
    t.shard.setMetricsRegistry(&metrics);
    const actions = t.shard.actions_handler;
    _ = actions.expireDue(&t.shard);
    actions.duty_since_ns = 0;
    // No room for any called run's end.
    t.shard.outbox_caps = .{ .other = .{ .shard = 0, .channel = 1 << 30 } };
    var passes: usize = 0;
    while (passes < 4 and ActionsHandler.for_tests.run(&t.shard, .default, "plain").?.status == .leased) : (passes += 1) {
        _ = actions.expireDue(&t.shard);
        try ParkTest.ack(&t.shard);
    }
    try std.testing.expectEqual(action_machine.Status.timed_out, ActionsHandler.for_tests.run(&t.shard, .default, "plain").?.status);
    // Every held one is still leased, and, once the walk has gone round,
    // counted.
    _ = actions.expireDue(&t.shard);
    try std.testing.expectEqual(@as(u64, held_n), metrics.workflow.action_expires_held.load(.monotonic));
    for (&names, 0..) |*b, i| try std.testing.expectEqual(action_machine.Status.leased, ActionsHandler.for_tests.run(&t.shard, .default, try std.fmt.bufPrint(b, "c{d}", .{i})).?.status);
}

/// A workflow name in the default namespace whose slot shard `on` owns.
fn workflowOn(two: *TwoShards, on: u16, prefix: []const u8, buf: []u8) ![]const u8 {
    var i: usize = 0;
    while (true) : (i += 1) {
        const n = try std.fmt.bufPrint(buf, "{s}{d}", .{ prefix, i });
        if (two.shards[0].router.slotToShard(node_router.nsKeySlot(.default, n)) == on) return n;
    }
}

/// Every shard's workflow duty and channels, six turns.
fn turnWorkflows(two: *TwoShards) void {
    for (0..6) |_| {
        for (&two.shards) |*s| {
            s.workflow_handler.advanceStartedRuns(s);
            s.workflow_handler.checkPendingActions(s);
        }
        two.settle();
        pumpChannels(two);
    }
}

fn createWorkflow(two: *TwoShards, s: *Shard, c: TestClient, id: u64, yaml: []const u8, name: []const u8) !void {
    var out: [512]u8 = undefined;
    s.runRequest(c.conn, try ParkTest.request(.workflow_create, id, proto.DEFAULT_NAMESPACE, name, yaml, ""), .client);
    two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(c, s, &out)).header.status);
}

test "Shard: a workflow started by a client carries its leader's term in its run id, and a later term's start the later term" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const a = &two.shards[0];
    var wb: [16]u8 = undefined;
    const wf = try workflowOn(&two, 0, "wf", &wb);
    const c = try TestClient.open(a);
    defer _ = std.c.close(c.pair[1]);
    var yb: [512]u8 = undefined;
    try createWorkflow(&two, a, c, 1, try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"start\":{{\"wait_for_signal\":{{\"type\":\"go\"}},\"transitions\":{{\"success\":\"flo.Completed\"}}}}}}", .{wf}), wf);
    var ids: [2][run_id_mod.MAX_ID_LEN]u8 = undefined;
    var lens: [2]usize = undefined;
    for (0..2) |i| {
        if (i == 1) {
            // Leader again in a later term.
            const raft = a.raft_node;
            raft.current_term += 7;
            raft.ready_index = raft.last_applied;
        }
        var out: [512]u8 = undefined;
        a.runRequest(c.conn, try ParkTest.request(.workflow_start, 2 + i, proto.DEFAULT_NAMESPACE, wf, "", ""), .client);
        two.settle();
        const started = try nextAnswer(c, a, &out);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), started.header.status);
        @memcpy(ids[i][0..started.data.len], started.data);
        lens[i] = started.data.len;
        var tb: [20]u8 = undefined;
        const tail = try std.fmt.bufPrint(&tb, "-{x}", .{a.raft_node.current_term});
        try std.testing.expect(std.mem.endsWith(u8, ids[i][0..lens[i]], tail));
    }
    try std.testing.expect(!std.mem.eql(u8, ids[0][0..lens[0]], ids[1][0..lens[1]]));
}

test "Shard: a channel carries a parent's child workflow to its shard and the child's end back, and the parent resumes" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const a = &two.shards[0];
    const b = &two.shards[1];
    var pb: [16]u8 = undefined;
    var kb: [16]u8 = undefined;
    var ab: [16]u8 = undefined;
    var wb: [16]u8 = undefined;
    const parent_wf = try workflowOn(&two, 0, "par", &pb);
    const kid_wf = try workflowOn(&two, 1, "kid", &kb);
    const n = try callNames(&two, 1, 1, &ab, &wb);
    _ = try proposeAction(b, .action_register, testRegister(n.action));
    two.settle();
    const ca = try TestClient.open(a);
    defer _ = std.c.close(ca.pair[1]);
    const cb = try TestClient.open(b);
    defer _ = std.c.close(cb.pair[1]);
    var yb: [512]u8 = undefined;
    try createWorkflow(&two, b, cb, 1, try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"start\":{{\"run\":\"@actions/{s}\",\"transitions\":{{\"success\":\"flo.Completed\",\"failure\":\"flo.Failed\"}}}}}}", .{ kid_wf, n.action }), kid_wf);
    try createWorkflow(&two, a, ca, 2, try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"start\":{{\"run\":\"@workflow/{s}\",\"transitions\":{{\"success\":\"flo.Completed\",\"failure\":\"flo.Failed\"}}}}}}", .{ parent_wf, kid_wf }), parent_wf);
    var out: [512]u8 = undefined;
    a.runRequest(ca.conn, try ParkTest.request(.workflow_start, 3, proto.DEFAULT_NAMESPACE, parent_wf, "", ""), .client);
    two.settle();
    const started = try nextAnswer(ca, a, &out);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), started.header.status);
    var rid_buf: [64]u8 = undefined;
    const parent_run = rid_buf[0..started.data.len];
    @memcpy(parent_run, started.data);
    turnWorkflows(&two);
    // The child runs on b, under the id the parent's call chose; its step's
    // action waits for a worker there.
    try std.testing.expectEqual(@as(usize, 1), b.workflow_handler.runCount());
    try completeNext(&two, b, n.action, "{}");
    turnWorkflows(&two);
    var pkb: [64]u8 = undefined;
    @memcpy(pkb[0..4], &ns_table.Id.default.bytes());
    @memcpy(pkb[4..][0..parent_run.len], parent_run);
    const parent = a.workflow_handler.inspect(pkb[0 .. 4 + parent_run.len]) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(WorkflowHandler.RunStatus.completed, parent.status);
    var heard = false;
    for (parent.history.items) |evt| {
        if (std.mem.eql(u8, evt.event_type_owned, "child_completed")) heard = true;
    }
    try std.testing.expect(heard);
}

test "Shard: a child's end waits while its own parent's outbox is full, and another child's, bound elsewhere, doesn't" {
    var two: TwoShards = undefined;
    try two.init();
    defer two.deinit();
    for (&two.shards) |*s| s.wireHandlerShardPtrs();
    const b = &two.shards[1];
    var kb: [16]u8 = undefined;
    const kid_wf = try workflowOn(&two, 1, "kid", &kb);
    const cb = try TestClient.open(b);
    defer _ = std.c.close(cb.pair[1]);
    var yb: [512]u8 = undefined;
    try createWorkflow(&two, b, cb, 1, try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"start\":{{\"wait_for_signal\":{{\"type\":\"go\"}},\"transitions\":{{\"success\":\"flo.Completed\"}}}}}}", .{kid_wf}), kid_wf);
    // Two children here: one whose parent's workflow is on shard 0, one on
    // this shard.
    var p0: [16]u8 = undefined;
    var p1: [16]u8 = undefined;
    const far = try workflowOn(&two, 0, "pa", &p0);
    const near = try workflowOn(&two, 1, "pb", &p1);
    for ([_][]const u8{ far, near }, [_][]const u8{ "kid-far", "kid-near" }) |parent_wf, kid| {
        _ = try proposeAction(b, .child_start, action_entries.ChildStart.Value{ .ns = ns_table.DEFAULT.int(), .parent_slot = calls_machine.callerSlot(.default, parent_wf), .parent_run = "p-run", .parent_workflow = parent_wf, .workflow = kid_wf, .version = "", .run = kid, .input = "{}" });
    }
    two.settle();
    b.workflow_handler.checkPendingActions(b);
    two.settle();
    try std.testing.expectEqual(@as(usize, 2), b.workflow_handler.runCount());
    // Their starts' replies wait in the outboxes: shard 1 takes its own, and
    // shard 0 never answers, so its outbox stays full at one byte a channel.
    for (0..4) |_| {
        b.tickChannels();
        _ = b.drainInbox();
        two.shards[1].channel.peers[1].lanes[0].last_trim_ms = 0;
        _ = b.applyCommitted();
    }
    b.outbox_caps = .{ .other = .{ .shard = 1 << 30, .channel = 1 } };
    const rd: contract_view.ReadView = .{ .store = &b.defaultPartition().store };
    try std.testing.expect(channels_mod.metaOf(rd, 0, .main).bytes > 0);
    try std.testing.expectEqual(@as(u64, 0), channels_mod.metaOf(rd, 1, .main).bytes);
    const wf = b.workflow_handler;
    for ([_][]const u8{ "kid-far", "kid-near" }) |kid| {
        const key = wf.nsKey(.default, kid).?;
        defer std.testing.allocator.free(key);
        wf.endRunForTests(b, key, .completed, "flo.Completed");
    }
    _ = b.applyCommitted();
    for ([_][]const u8{ "kid-far", "kid-near" }, [_]WorkflowHandler.RunStatus{ .running, .completed }) |kid, want| {
        const key = wf.nsKey(.default, kid).?;
        defer std.testing.allocator.free(key);
        try std.testing.expectEqual(want, wf.inspect(key).?.status);
    }
}

