/// Adds `name` to the names a function binds from the shard list.
fn bindName(names: *[16][]const u8, n: *usize, name: []const u8) !void {
    if (n.* == names.len) {
        std.debug.print("more than {d} names bound from " ++ "peer_" ++ "shards in one function; grow the test's list\n", .{names.len});
        return error.TestUnexpectedResult;
    }
    names[n.*] = name;
    n.* += 1;
}

/// Whether `line` holds `name` as a whole word.
fn hasWord(line: []const u8, name: []const u8) bool {
    var at: usize = 0;
    while (std.mem.indexOfPos(u8, line, at, name)) |i| : (at = i + 1) {
        const before_ok = i == 0 or !(std.ascii.isAlphanumeric(line[i - 1]) or line[i - 1] == '_' or line[i - 1] == '.');
        const after = i + name.len;
        if (before_ok and (after == line.len or !(std.ascii.isAlphanumeric(line[after]) or line[after] == '_'))) return true;
    }
    return false;
}

/// Whether `line` uses `name` as a value: indexed or a field read, and not
/// as part of a longer name.
fn usesName(line: []const u8, name: []const u8) bool {
    var at: usize = 0;
    while (std.mem.indexOfPos(u8, line, at, name)) |i| : (at = i + 1) {
        const before_ok = i == 0 or !(std.ascii.isAlphanumeric(line[i - 1]) or line[i - 1] == '_' or line[i - 1] == '.');
        const after = i + name.len;
        if (before_ok and after < line.len and (line[after] == '[' or line[after] == '.')) return true;
    }
    return false;
}

test "no shard's thread reaches another shard's handler through peer_shards" {
    // Another shard's state is read by asking it (its mailbox), never
    // through its pointer: these lines only count shards or read the
    // offline flag. A new line naming the field is reviewed here, and no
    // name bound from one (a capture, a `const`/`var` holding it or a name
    // bound from it, a loop over one) reaches a `*_handler` in the function
    // that binds it. Not caught: a bound name passed to another function,
    // which reads a handler there. Split so this test's own text doesn't
    // match.
    const field = "peer_" ++ "shards";
    const allowed = [_][]const u8{
        field ++ ": ?[]*Shard,",
        "." ++ field ++ " = null,",
        "if (self." ++ field ++ " == null or s.shard_id == self.id or s.shard_id >= mailboxes.len) break :blk null;",
        "const shards = if (self." ++ field ++ ") |p| p.len else 1;",
        "const peers = self." ++ field ++ " orelse {",
        "return if (self." ++ field ++ ") |p| p.len else 1;",
        "const shards = self." ++ field ++ " orelse return if (self.offline != null) self else null;",
        "s." ++ field ++ " = &self.peers;",
        "shard." ++ field ++ " = null;",
    };
    const sources = [_][]const u8{
        @embedFile("shard.zig"),
        @embedFile("../actions/handler.zig"),
        @embedFile("../kv/handler.zig"),
        @embedFile("../namespace/handler.zig"),
        @embedFile("../processing/handler.zig"),
        @embedFile("../queue/handler.zig"),
        @embedFile("../stream/group_handler.zig"),
        @embedFile("../stream/handler.zig"),
        @embedFile("../ts/handler.zig"),
        @embedFile("../worker/handler.zig"),
        @embedFile("../workflow/handler.zig"),
    };
    for (sources) |src| {
        var names: [16][]const u8 = undefined;
        var n: usize = 0;
        var in_test = false;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |line| {
            if (std.mem.startsWith(u8, line, "test \"")) in_test = true;
            if (in_test) {
                if (std.mem.eql(u8, line, "}")) in_test = false;
                continue;
            }
            // A function's end: the names it bound are gone.
            if (std.mem.eql(u8, line, "    }") or std.mem.eql(u8, line, "}")) n = 0;
            const t = std.mem.trim(u8, line, " ");
            if (std.mem.startsWith(u8, t, "//")) continue;
            if (std.mem.indexOf(u8, t, field) != null) {
                for (allowed) |a| {
                    if (std.mem.eql(u8, t, a)) break;
                } else {
                    std.debug.print("a new use of peer_shards: {s}\n", .{t});
                    return error.TestUnexpectedResult;
                }
            }
            // A line binds: one naming the field, a loop over a bound name,
            // or a `const`/`var` whose value holds one. It binds its
            // declared name and its captures.
            const decl: ?[]const u8 = for ([_][]const u8{ "const ", "var " }) |kw| {
                if (!std.mem.startsWith(u8, t, kw)) continue;
                const end = std.mem.indexOfAnyPos(u8, t, kw.len, " :") orelse t.len;
                break t[kw.len..end];
            } else null;
            const value = if (std.mem.indexOfScalar(u8, t, '=')) |eq| t[eq + 1 ..] else "";
            var bind = std.mem.indexOf(u8, t, field) != null;
            for (names[0..n]) |nm| {
                if (std.mem.indexOf(u8, t, "for (") != null and hasWord(t, nm)) bind = true;
                if (decl != null and hasWord(value, nm)) bind = true;
            }
            if (bind) {
                if (decl) |d| try bindName(&names, &n, d);
                var at: usize = 0;
                while (std.mem.indexOfScalarPos(u8, t, at, '|')) |a| {
                    const b = std.mem.indexOfScalarPos(u8, t, a + 1, '|') orelse break;
                    try bindName(&names, &n, std.mem.trimStart(u8, t[a + 1 .. b], "*"));
                    at = b + 1;
                }
            }
            if (std.mem.indexOf(u8, t, "_handler") == null) continue;
            for (names[0..n]) |nm| {
                if (usesName(t, nm)) {
                    std.debug.print("another shard's handler, through {s}: {s}\n", .{ nm, t });
                    return error.TestUnexpectedResult;
                }
            }
        }
    }
}

/// A workflow on shard 0 whose trigger reads a stream shard 1 owns.
const TriggerPair = struct {
    two: TwoShards = undefined,
    c: TestClient = undefined,
    wb: [16]u8 = undefined,
    sb: [16]u8 = undefined,
    wf: []const u8 = "",
    stream: []const u8 = "",
    key: []const u8 = "",

    fn init(t: *TriggerPair) !void {
        try t.two.init();
        for (&t.two.shards) |*s| s.wireHandlerShardPtrs();
        const a = &t.two.shards[0];
        t.wf = try workflowOn(&t.two, 0, "wf", &t.wb);
        t.stream = try workflowOn(&t.two, 1, "ev", &t.sb);
        t.c = try TestClient.open(a);
        var yb: [512]u8 = undefined;
        try createWorkflow(&t.two, a, t.c, 1, try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"trigger\":{{\"stream\":\"{s}\"}},\"start\":{{\"wait_for_signal\":{{\"type\":\"never\"}},\"transitions\":{{\"success\":\"flo.Completed\"}}}}}}", .{ t.wf, t.stream }), t.wf);
        t.key = a.workflow_handler.nsKey(.default, t.wf).?;
    }

    fn deinit(t: *TriggerPair) void {
        std.testing.allocator.free(t.key);
        _ = std.c.close(t.c.pair[1]);
        t.two.deinit();
    }

    fn append(t: *TriggerPair, n: usize) !void {
        const b = &t.two.shards[1];
        for (0..n) |k| {
            var pb: [16]u8 = undefined;
            _ = try b.stream_handler.appendPayloadToStream(t.stream, "default", try std.fmt.bufPrint(&pb, "{{\"k\":{d}}}", .{k}));
        }
        t.two.settle();
    }

    /// One poll of every trigger (forced, as an append's wake forces it),
    /// without delivering what it asks.
    fn ask(t: *TriggerPair) void {
        const a = &t.two.shards[0];
        a.workflow_handler.triggers_dirty = true;
        a.workflow_handler.tickStreamTriggers(a);
    }

    fn round(t: *TriggerPair) void {
        t.ask();
        t.two.settle();
    }

    fn trigger(t: *TriggerPair) *WorkflowHandler.StreamTriggerState {
        return t.two.shards[0].workflow_handler.stream_triggers.getPtr(t.key).?;
    }

    fn runs(t: *TriggerPair) usize {
        return t.two.shards[0].workflow_handler.runCount();
    }

    /// Where the trigger reads on from, as its logged place has it.
    fn cursor(t: *TriggerPair) StreamID {
        return t.two.shards[0].workflow_handler.triggerCursor(t.key, .default);
    }

    /// The trigger's logged place.
    fn place(t: *TriggerPair) @import("../workflow/runs_machine.zig").PerDef.Value {
        const h = t.two.shards[0].workflow_handler;
        return @import("../workflow/runs_machine.zig").perDefOf(h.defsRead(), t.key) orelse @import("../workflow/runs_machine.zig").PER_DEF_NONE;
    }

    fn lastId(t: *TriggerPair) !StreamID {
        const sh = t.two.shards[1].stream_handler;
        const r = sh.readPayloadsForStreamIn(t.stream, .default, .{ .timestamp_ms = 0, .sequence = 0 }, 100);
        defer r.deinit(sh.allocator);
        return r.last_id;
    }
};

test "Shard: a trigger over a stream another shard owns asks that shard, and starts a run per event from its page" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
    const last = try t.lastId();
    try std.testing.expect(t.cursor().eql(last));
    // The place names the stream the page read.
    try std.testing.expectEqualStrings(t.stream, t.place().trig_stream);
    try std.testing.expectEqual(t.trigger().stream_made_ns.?, t.place().trig_made);
    try std.testing.expectEqual(@as(u64, 0), t.trigger().read_seq);
    // Nothing new: the next page starts nothing and leaves the cursor.
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
}

test "Shard: an owner that doesn't serve reads says so, the trigger's cursor stays, and the next ask reads" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    // The owner leads but hasn't applied what earlier terms committed.
    const r = t.two.shards[1].raft_node;
    r.ready_index = r.last_applied + 1000;
    t.round();
    try std.testing.expectEqual(@as(usize, 0), t.runs());
    try std.testing.expectEqual(@as(u64, 0), t.cursor().timestamp_ms);
    // Answered, so asked again at once, not after the deadline; and the
    // refusal told it nothing about the stream.
    try std.testing.expectEqual(@as(u64, 0), t.trigger().read_seq);
    try std.testing.expectEqual(@as(?u64, null), t.trigger().stream_made_ns);
    r.ready_index = r.last_applied;
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
}

test "Shard: a trigger's page is dropped after a term change, a moved cursor or a disable, and read again from the cursor" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    const a = &t.two.shards[0];
    // A term change while the read is out.
    t.ask();
    a.raft_node.current_term += 1;
    a.raft_node.ready_index = a.raft_node.last_applied;
    t.two.settle();
    try std.testing.expectEqual(@as(usize, 0), t.runs());
    // The cursor moved while the read was out (this leader read on, say):
    // the page answers a read from elsewhere.
    const sh = t.two.shards[1].stream_handler;
    const read = sh.readPayloadsForStreamIn(t.stream, .default, .{ .timestamp_ms = 0, .sequence = 0 }, 1);
    const first = read.ids[0];
    read.deinit(sh.allocator);
    t.ask();
    // Read past without a start (an append it couldn't read): the chain
    // stays at the place logged, none.
    t.trigger().proposed = .{ .at = first, .term = a.raft_node.current_term, .chain = .{ .timestamp_ms = 0, .sequence = 0 } };
    t.two.settle();
    try std.testing.expectEqual(@as(usize, 0), t.runs());
    // Read again from where the cursor is: the two events after it.
    t.round();
    try std.testing.expectEqual(@as(usize, 2), t.runs());
    // Disabled while a read is out: its page starts nothing.
    try t.append(1);
    t.ask();
    var out: [512]u8 = undefined;
    a.runRequest(t.c.conn, try ParkTest.request(.workflow_disable, 9, proto.DEFAULT_NAMESPACE, t.wf, "", ""), .client);
    t.two.settle();
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), (try nextAnswer(t.c, a, &out)).header.status);
    try std.testing.expectEqual(@as(usize, 2), t.runs());
}

test "Shard: a trigger's starts that don't follow the place logged are refused, and its next read starts every event, none passed over" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    const a = &t.two.shards[0];
    const sh = t.two.shards[1].stream_handler;
    const read = sh.readPayloadsForStreamIn(t.stream, .default, .{ .timestamp_ms = 0, .sequence = 0 }, 1);
    const first = read.ids[0];
    read.deinit(sh.allocator);
    // A leader that believes it started the first event: its next starts
    // say they follow it, and the place logged is none.
    t.trigger().proposed = .{ .at = first, .term = a.raft_node.current_term, .chain = first };
    t.round();
    try std.testing.expectEqual(@as(usize, 0), t.runs());
    try std.testing.expect(t.trigger().proposed == null);
    // Read again from the place logged: all three, in order.
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
    try std.testing.expect(t.place().trig_ts == (try t.lastId()).timestamp_ms and t.place().trig_seq == (try t.lastId()).sequence);
}

test "Shard: a trigger whose starts its shard's memory share refuses at random, some part way through a read, starts every event once, none passed over" {
    const settings = @import("../settings/machine.zig");
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const store = &t.two.shards[0].defaultPartition().store;
    for ([_]u64{ 1, 2, 3, 4, 5, 6, 7, 8 }) |seed| {
        errdefer std.debug.print("trigger refusal test failed at seed {d}\n", .{seed});
        var prng = std.Random.DefaultPrng.init(seed);
        const r = prng.random();
        const before = t.runs();
        var appended: usize = 0;
        var refusals: usize = 0;
        var resyncs: usize = 0;
        for (0..30) |_| {
            // Events of many sizes: a large one's start refused, a small
            // one's after it fits.
            if (r.uintLessThan(u8, 3) == 0) {
                const b = &t.two.shards[1];
                for (0..1 + r.uintLessThan(usize, 4)) |_| {
                    var xs: [1800]u8 = @splat('x');
                    var pb: [2048]u8 = undefined;
                    const pad = r.uintLessThan(usize, xs.len);
                    _ = try b.stream_handler.appendPayloadToStream(t.stream, "default", try std.fmt.bufPrint(&pb, "{{\"p\":\"{s}\"}}", .{xs[0..pad]}));
                    appended += 1;
                }
                t.two.settle();
            }
            // Unbound, at the use, or a little past it, so a read's starts
            // are refused part way through.
            const use = pool.useOf(store);
            try settings.bindForTest(store, switch (r.uintLessThan(u8, 3)) {
                0 => std.math.maxInt(u64),
                1 => use,
                else => use + r.uintLessThan(u64, 3000),
            });
            // Its wait out, as if time passed.
            t.trigger().hold.until_ms = 0;
            const resync = t.trigger().resync_index;
            t.round();
            if (t.trigger().resync_index != resync) resyncs += 1;
            if (t.trigger().hold.refusals > 0) refusals += 1;
        }
        // The share refused some of the starts, part way through a read.
        try std.testing.expect(refusals > 0 and resyncs > 0);
        try settings.bindForTest(store, std.math.maxInt(u64));
        for (0..8) |_| {
            t.trigger().hold.until_ms = 0;
            t.round();
        }
        try std.testing.expectEqual(before + appended, t.runs());
        // Its place is the stream's last event: nothing is read past it.
        const sh = t.two.shards[1].stream_handler;
        const past = sh.readPayloadsForStreamIn(t.stream, .default, .{ .timestamp_ms = t.place().trig_ts, .sequence = t.place().trig_seq }, 10);
        defer past.deinit(sh.allocator);
        try std.testing.expectEqual(@as(usize, 0), past.payloads.len);
    }
}

test "Shard: a halted leader holds no trigger at its memory share: the halt holds it" {
    const settings = @import("../settings/machine.zig");
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const a = &t.two.shards[0];
    const store = &a.defaultPartition().store;
    try settings.bindForTest(store, pool.useOf(store));
    t.ask();
    a.workflow_handler.tickSchedules(a);
    try std.testing.expectEqual(@as(u64, 1), a.workflow_handler.memory_held);
    a.halted = .{ .index = 1, .term = a.raft_node.current_term, .crc = 0 };
    defer a.halted = null;
    a.runProducers();
    try std.testing.expectEqual(@as(u64, 0), a.workflow_handler.memory_held);
    try std.testing.expectEqual(@as(?u64, null), t.trigger().hold.share);
}

test "Shard: a halted leader holds no trigger at its namespace's quota either: the halt holds it, whichever hold was up" {
    const hq = @import("../budget/history_quota.zig");
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const a = &t.two.shards[0];
    const store = &a.defaultPartition().store;
    try hq.setForTest(store, .default, 1 << 30, 1 << 30);
    t.ask();
    a.workflow_handler.tickSchedules(a);
    try std.testing.expectEqual(@as(u64, 1), a.workflow_handler.quota_held);
    try std.testing.expectEqual(@as(u64, 0), a.workflow_handler.memory_held);
    a.halted = .{ .index = 1, .term = a.raft_node.current_term, .crc = 0 };
    defer a.halted = null;
    // Only the quota's hold is up: dropped all the same.
    a.runProducers();
    try std.testing.expectEqual(@as(u64, 0), a.workflow_handler.quota_held);
    try std.testing.expectEqual(@as(?u64, null), t.trigger().quota_hold.share);
}

test "Shard: a trigger held at its namespace's quota is cleared, uncounted and unsaid, once its workflow is disabled" {
    const hq = @import("../budget/history_quota.zig");
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const a = &t.two.shards[0];
    try hq.setForTest(&a.defaultPartition().store, .default, 1 << 30, 1 << 30);
    t.ask();
    a.workflow_handler.tickSchedules(a);
    try std.testing.expectEqual(@as(u64, 1), a.workflow_handler.quota_held);
    try std.testing.expect(t.trigger().quota_hold.said);
    var out: persistence_mod.Result = .{};
    try a.workflow_handler.replayEnabled(t.key, &.{0}, @import("stdx").time.milliTimestamp(), &out);
    // Asked at its next poll.
    a.workflow_handler.triggers_dirty = true;
    a.workflow_handler.tickStreamTriggers(a);
    a.workflow_handler.tickSchedules(a);
    try std.testing.expectEqual(@as(u64, 0), a.workflow_handler.quota_held);
    try std.testing.expectEqual(@as(?u64, null), t.trigger().quota_hold.share);
    try std.testing.expect(!t.trigger().quota_hold.said);
}

test "Shard: a trigger's first start in a new term follows the place logged, so it lands without a resync" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
    // A new term: what this leader read before is forgotten, and its first
    // start names the place logged, three events in.
    t.two.shards[0].raft_node.current_term += 1;
    try t.append(2);
    t.round();
    try std.testing.expectEqual(@as(usize, 5), t.runs());
    try std.testing.expectEqual(@as(u64, 0), t.trigger().resync_index);
}

test "Shard: a trigger moved to another stream while its first read is out takes nothing from that read's page" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(3);
    const a = &t.two.shards[0];
    // The read of the first stream is out when the definition moves.
    t.ask();
    var nb: [16]u8 = undefined;
    const moved = try workflowOn(&t.two, 1, "fx", &nb);
    _ = try t.two.shards[1].stream_handler.appendPayloadToStream(moved, "default", "{}");
    var yb: [512]u8 = undefined;
    const yaml = try std.fmt.bufPrint(&yb, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"2.0.0\",\"trigger\":{{\"stream\":\"{s}\"}},\"start\":{{\"wait_for_signal\":{{\"type\":\"never\"}},\"transitions\":{{\"success\":\"flo.Completed\"}}}}}}", .{ t.wf, moved });
    a.runRequest(t.c.conn, try ParkTest.request(.workflow_create, 2, proto.DEFAULT_NAMESPACE, t.wf, yaml, ""), .client);
    try ParkTest.ack(a);
    // Its first read of the new stream goes out before the old page comes.
    t.ask();
    t.two.settle();
    // The old page started nothing.
    try std.testing.expectEqual(@as(usize, 0), t.runs());
    // The new stream's one event does, and the place is the new stream's
    // alone.
    t.round();
    try std.testing.expectEqual(@as(usize, 1), t.runs());
    try std.testing.expectEqualStrings(moved, t.place().trig_stream);
    try std.testing.expectEqual(t.trigger().stream_made_ns.?, t.place().trig_made);
}

test "Shard: a trigger's page answering its read, but naming another stream or namespace, is not taken" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const a = &t.two.shards[0];
    const alloc = std.testing.allocator;
    const Case = struct { source: []const u8, ns: u32, runs: usize };
    for ([_]Case{
        .{ .source = "elsewhere", .ns = ns_table.Id.default.int(), .runs = 0 },
        .{ .source = t.stream, .ns = 99, .runs = 0 },
        // The page this read asked for: taken.
        .{ .source = t.stream, .ns = ns_table.Id.default.int(), .runs = 1 },
    }) |c| {
        // A read of the trigger's stream is out, and a page comes with its
        // number and term.
        const trig = t.trigger();
        trig.next_read_seq += 1;
        trig.read_seq = trig.next_read_seq;
        trig.read_term = a.raft_node.current_term;
        trig.read_ns = .default;
        var b: source_page_mod.Page.Builder = .{ .made_ns = 1, .ns = c.ns };
        defer b.deinit(alloc);
        try b.begin(alloc, .{ .term = trig.read_term, .seq = trig.read_seq, .kind = .stream, .asker = .trigger, .key = t.key, .namespace = "default", .source = c.source, .from_a = 0, .from_b = 0, .limit = 10 });
        try b.record(alloc, 1, 0, "{}");
        const bytes = try b.finish(alloc, 1, 0, 0);
        defer alloc.free(bytes);
        a.workflow_handler.takeTriggerPage(a, source_page_mod.Page.decode(bytes).?);
        t.two.settle();
        try std.testing.expectEqual(c.runs, t.runs());
    }
}

test "Shard: a trigger whose stream is deleted and made again reads the new one from its start" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(2);
    t.round();
    try std.testing.expectEqual(@as(usize, 2), t.runs());
    const made0 = t.trigger().stream_made_ns.?;
    const b = &t.two.shards[1];
    _ = try persistence_mod.proposeEntryIn(b, .stream_delete, entry_mod.Flags.FORCE, .default, t.stream, "");
    t.two.settle();
    try t.append(1);
    // The page names another stream: the cursor starts over, and the next
    // read takes the new stream's event.
    t.round();
    try std.testing.expect(t.trigger().stream_made_ns.? != made0);
    try std.testing.expectEqual(@as(u64, 0), t.cursor().timestamp_ms);
    try std.testing.expectEqual(@as(u64, 0), t.cursor().sequence);
    try std.testing.expectEqual(@as(usize, 2), t.runs());
    t.round();
    try std.testing.expectEqual(@as(usize, 3), t.runs());
}

test "Shard: a trigger's page from a replica behind a remake of its stream is dropped, and the cursor kept" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    try t.append(2);
    t.round();
    try std.testing.expectEqual(@as(usize, 2), t.runs());
    const placed = t.place();
    // The trigger has read a stream made later than the one the owner
    // holds: as after it moved to a node whose replica hasn't applied a
    // delete and remake yet.
    const newer = t.trigger().stream_made_ns.? + 1;
    t.trigger().stream_made_ns = newer;
    try t.append(1);
    t.round();
    try std.testing.expectEqual(@as(usize, 2), t.runs());
    try std.testing.expectEqual(placed.trig_ts, t.place().trig_ts);
    try std.testing.expectEqual(placed.trig_seq, t.place().trig_seq);
    try std.testing.expectEqual(placed.trig_made, t.place().trig_made);
    try std.testing.expectEqual(newer, t.trigger().stream_made_ns.?);
}

test "Shard: a trigger on another shard's stream polls at its interval, unforced, by its own clock" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    const Clock = struct {
        var ms: u64 = 500;
        fn now() u64 {
            return ms;
        }
    };
    const a = &t.two.shards[0];
    const wf = a.workflow_handler;
    wf.mono_ms = Clock.now;
    try t.append(1);
    t.round();
    try std.testing.expectEqual(@as(usize, 1), t.runs());
    try std.testing.expectEqual(@as(i64, 500), t.trigger().last_poll_ms);
    try t.append(1);
    const seq = t.trigger().read_seq;
    const every: u64 = t.trigger().poll_interval_ms;
    // Not yet its interval: no ask.
    Clock.ms = 500 + every - 1;
    wf.triggers_dirty = false;
    wf.tickStreamTriggers(a);
    try std.testing.expectEqual(seq, t.trigger().read_seq);
    // Its interval: asked, though nothing forced it.
    Clock.ms = 500 + every;
    wf.triggers_dirty = false;
    wf.tickStreamTriggers(a);
    try std.testing.expect(t.trigger().read_seq != seq);
    try std.testing.expectEqual(@as(i64, @intCast(500 + every)), t.trigger().last_poll_ms);
    t.two.settle();
    try std.testing.expectEqual(@as(usize, 2), t.runs());
}

test "Shard: a trigger's read with no answer is asked again after the deadline, not before" {
    var t: TriggerPair = .{};
    try t.init();
    defer t.deinit();
    // The trigger's clock, near 0 as just after boot: the deadline runs
    // on it, not the wall clock.
    const Clock = struct {
        var ms: u64 = 500;
        fn now() u64 {
            return ms;
        }
    };
    const wf = t.two.shards[0].workflow_handler;
    wf.mono_ms = Clock.now;
    try t.append(1);
    t.ask();
    const seq = t.trigger().read_seq;
    try std.testing.expect(seq != 0);
    try std.testing.expectEqual(@as(i64, 500), t.trigger().read_sent_ms);
    // The ask is lost: the owner never sees it.
    const b = &t.two.shards[1];
    var lost: [8]InboxMessage = undefined;
    for (lost[0..b.mailbox.inbox.drain(&lost)]) |msg| {
        const bytes = Shard.inboxPayload(msg);
        if (bytes.len > 0) b.allocator.free(bytes);
    }
    Clock.ms = 500 + WorkflowHandler.TRIGGER_READ_DEADLINE_MS - 1;
    t.ask();
    try std.testing.expectEqual(seq, t.trigger().read_seq);
    Clock.ms = 500 + WorkflowHandler.TRIGGER_READ_DEADLINE_MS;
    t.ask();
    try std.testing.expect(t.trigger().read_seq != seq);
    t.two.settle();
    try std.testing.expectEqual(@as(usize, 1), t.runs());
}

test "Shard: a guarded node's vouch comes back with its guard at boot, exactly; an unguarded node's isn't read; a cut one refuses the start" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const data_dir = try testDataDir(&tmp);
    defer std.testing.allocator.free(data_dir);
    const shard_dir = try std.fmt.allocPrint(std.testing.allocator, "{s}/00000", .{data_dir});
    defer std.testing.allocator.free(shard_dir);
    try @import("stdx").fs.makePath(shard_dir);
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    const cfg = membership.Config.ofVoters(&.{ 1, 3 }).withJoiner(2, true);
    const vouch: hard_state_mod.Vouch = .{ .config = cfg, .index = 3355, .term = 19 };

    // Guarded, part way through catching up: the vouch it held, no more.
    try hard_state_mod.save(shard_dir, .{ .node_id = 2, .term = 20, .voted_for = 0, .lost_log = true, .vouch = vouch });
    {
        var s = try Shard.init(std.testing.allocator, 0, 2, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 2, .join, .{}, .{});
        defer s.deinit();
        try std.testing.expect(s.raft_node.lost_log != .none);
        try std.testing.expectEqual(@as(u64, 3355), s.raft_node.vouch.index);
        try std.testing.expectEqual(@as(u64, 19), s.raft_node.vouch.term);
        var ids: [membership.MAX_MEMBERS]u32 = undefined;
        try std.testing.expectEqualSlices(u32, &.{ 1, 3 }, s.raft_node.vouch.config.voterIds(&ids));
        try std.testing.expect(s.raft_node.vouch.config.names(2));
    }
    // Not guarded: whatever vouch the file holds counts for nothing.
    try hard_state_mod.save(shard_dir, .{ .node_id = 2, .term = 20, .voted_for = 0, .lost_log = false, .vouch = vouch });
    {
        var s = try Shard.init(std.testing.allocator, 0, 2, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 2, .join, .{}, .{});
        defer s.deinit();
        try std.testing.expectEqual(@as(u64, 0), s.raft_node.vouch.index);
    }
    // Cut inside the vouch: refused, never read as a vouch or a fresh start.
    try hard_state_mod.save(shard_dir, .{ .node_id = 2, .term = 20, .voted_for = 0, .lost_log = true, .vouch = vouch });
    const path = try std.fmt.allocPrint(std.testing.allocator, "{s}/{s}", .{ shard_dir, hard_state_mod.FILENAME });
    defer std.testing.allocator.free(path);
    var buf: [hard_state_mod.MAX_SIZE]u8 = undefined;
    const full = (try @import("stdx").fs.readFileAlloc(std.testing.allocator, path, hard_state_mod.MAX_SIZE));
    defer std.testing.allocator.free(full);
    @memcpy(buf[0..full.len], full);
    const f = try @import("stdx").fs.createFile(path, .{});
    try @import("stdx").fs.writeAll(f, buf[0 .. full.len - 5]);
    @import("stdx").fs.closeFile(f);
    try std.testing.expectError(error.Truncated, Shard.init(std.testing.allocator, 0, 2, pipe_fds[0], data_dir, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 2, .join, .{}, .{}));
}

test "Shard: a workflow run's history read waits while its chunks are on the history lane, and is answered once they land" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [16 * 1024]u8 = undefined;
    var one: [1]proto.Response = undefined;

    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 1, "a", "gate", def, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    const named = [_]u8{ 0, 0, 0, 1, 2, 0, 'r', '1' };
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 2, "a", "gate", &named, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    // Signals it doesn't wait on, each event about a kilobyte: a chunk is
    // sent, and stays on the lane until the channel ticks.
    var sig: [2 + 1000]u8 = undefined;
    std.mem.writeInt(u16, sig[0..2], 1000, .little);
    @memset(sig[2..], 'x');
    for (0..4) |i| {
        shard.runRequest(conn, try ParkTest.request(.workflow_signal, 3 + i, "a", "r1", &sig, ""), .client);
        try ParkTest.ack(&shard);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    }
    const ns = shard.namespaceId("a");
    var kb: [64]u8 = undefined;
    const rec = @import("../workflow/runs_machine.zig").runOf(.{ .store = &shard.defaultPartition().store }, contract_view.idKey(&kb, ns, "r1") catch unreachable).?;
    try std.testing.expect(rec.hist_flushed > 0);

    // Held, not answered short.
    var lb: [history_read.Request.max_size]u8 = undefined;
    const limit = try history_read.Request.encodeInto(&lb, .{ .limit = 100, .cursor = null, .newest_first = false });
    shard.runRequest(conn, try ParkTest.request(.workflow_history, 9, "a", "r1", limit, ""), .client);
    try std.testing.expectEqual(@as(u16, 1), shard.waiter_pool.countByKind(.history_read));
    // Its chunk lands: answered, whole.
    try ParkTest.deliverOwn(&shard);
    try std.testing.expectEqual(@as(u16, 0), shard.waiter_pool.countByKind(.history_read));
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u64, 9), one[0].header.request_id);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    var hd: schema.Diagnostic = .{};
    try std.testing.expectEqual(@as(u32, 5), (try history_read.Response.decodeAll(one[0].data, &hd)).events.count);
    // Asked again, it answers at once.
    shard.runRequest(conn, try ParkTest.request(.workflow_history, 10, "a", "r1", limit, ""), .client);
    try std.testing.expectEqual(@as(u16, 0), shard.waiter_pool.countByKind(.history_read));
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@as(u32, 5), (try history_read.Response.decodeAll(one[0].data, &hd)).events.count);
}

test "Shard: a workflow run's delete is refused while it runs; once it ended, its status and history answer not found and its id starts a new run" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [16 * 1024]u8 = undefined;
    var one: [1]proto.Response = undefined;
    const def =
        \\{"kind":"Workflow","name":"gate","version":"1.0.0",
        \\"start":{"wait_for_signal":{"type":"go"},"transitions":{"success":"flo.Completed"}}}
    ;
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 1, "a", "gate", def, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    const named = [_]u8{ 0, 0, 0, 1, 2, 0, 'r', '1' };
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 2, "a", "gate", &named, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);

    // Live: refused, nothing proposed.
    const last = shard.raft_node.log.lastIndex();
    shard.runRequest(conn, try ParkTest.request(.workflow_run_delete, 3, "a", "r1", "", ""), .client);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), one[0].header.status);
    try std.testing.expectEqual(proto.Reason.run_live, (try one[0].refused()).reason);
    try std.testing.expectEqual(last, shard.raft_node.log.lastIndex());

    shard.runRequest(conn, try ParkTest.request(.workflow_cancel, 4, "a", "r1", "", ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    shard.runRequest(conn, try ParkTest.request(.workflow_run_delete, 5, "a", "r1", "", ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
    try ParkTest.deliverOwn(&shard);

    var lb: [history_read.Request.max_size]u8 = undefined;
    const limit = try history_read.Request.encodeInto(&lb, .{ .limit = 100, .cursor = null, .newest_first = false });
    for ([_]struct { op: proto.OpCode, value: []const u8 }{ .{ .op = .workflow_status, .value = "" }, .{ .op = .workflow_history, .value = limit }, .{ .op = .workflow_run_delete, .value = "" } }, 0..) |q, i| {
        shard.runRequest(conn, try ParkTest.request(q.op, 6 + i, "a", "r1", q.value, ""), .client);
        try ParkTest.ack(&shard);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        try std.testing.expectEqual(@backingInt(proto.StatusCode.not_found), one[0].header.status);
    }
    // The id starts a new run.
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 20, "a", "gate", &named, ""), .client);
    try ParkTest.ack(&shard);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
    try std.testing.expectEqual(@backingInt(proto.StatusCode.ok), one[0].header.status);
}

test "Shard: a run list's cursor no run can be at is refused bad_request, at the client's op and at a shard's page" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [16 * 1024]u8 = undefined;
    var one: [1]proto.Response = undefined;
    // A stamp before 1970, an id longer than a run's, a cursor cut short.
    const long: [597]u8 = @splat('r');
    var cursors: [3][8 + 597]u8 = undefined;
    std.mem.writeInt(i64, cursors[0][0..8], -1, .little);
    @memcpy(cursors[0][8..9], "r");
    std.mem.writeInt(i64, cursors[1][0..8], 1, .little);
    @memcpy(cursors[1][8..][0..597], &long);
    var good: [9]u8 = undefined;
    std.mem.writeInt(i64, good[0..8], 1, .little);
    good[8] = 'r';
    // The last is the control: a cursor a run can be at is answered.
    const asked = [_][]const u8{ cursors[0][0..9], cursors[1][0 .. 8 + 597], cursors[1][0..5], &good };
    for (asked, 0..) |c, i| {
        // [limit][status_len][cursor_len][cursor][search_len]
        var vb: [4 + 2 + 2 + 8 + 597 + 2]u8 = undefined;
        var w: std.Io.Writer = .fixed(&vb);
        try w.writeInt(u32, 10, .little);
        try w.writeInt(u16, 0, .little);
        try w.writeInt(u16, @intCast(c.len), .little);
        try w.writeAll(c);
        try w.writeInt(u16, 0, .little);
        shard.runRequest(conn, try ParkTest.request(.workflow_list_runs, 1 + i, "default", "wf", w.buffered(), ""), .client);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        const want: proto.StatusCode = if (i == asked.len - 1) .ok else .bad_request;
        try std.testing.expectEqual(@backingInt(want), one[0].header.status);
    }
    // A shard's page, asked by another shard. Only a stamp before 1970 is
    // sent here: `RunAt`'s schema bounds the id at 596 bytes, so a longer
    // one can't be encoded, and one cut short is refused by the schema's
    // decode like any table op's. The control is answered.
    const Page = table_run.op("system.runs_page").request;
    var pb: [Page.max_size]u8 = undefined;
    for ([_]i64{ -1, 1 }, 0..) |stamp, i| {
        const ask = try Page.encodeInto(&pb, .{ .status = "", .search = "", .after = .{ .created_at = stamp, .run_id = "r" }, .limit = 10, .room = 1 << 16 });
        shard.runRequest(conn, try ParkTest.request(.system_runs_page, 9 + i, "default", "", ask, ""), .shard);
        try ParkTest.responses(&shard, conn, pair[1], &buf, &one);
        const want: proto.StatusCode = if (stamp < 0) .bad_request else .ok;
        try std.testing.expectEqual(@backingInt(want), one[0].header.status);
    }
}

test "Shard: a workflow named longer than its runs' history may name is refused at create and at start, before anything is proposed" {
    const pipe_fds = try @import("stdx").io.pipe();
    defer _ = std.c.close(pipe_fds[0]);
    defer _ = std.c.close(pipe_fds[1]);
    var rn = try RaftNetwork.init(std.testing.allocator, 1, 0, 9000, .{ 127, 0, 0, 1 }, "s");
    defer rn.deinit();
    var shard = try Shard.init(std.testing.allocator, 0, 1, pipe_fds[0], null, Partition.DEFAULT_UAL_CAPACITY, 0, 0, .async_flush, 1, .bootstrap, .{}, .{});
    defer shard.deinit();
    shard.raft_network = &rn;
    shard.wireHandlerShardPtrs();
    try ParkTest.joinPeer(&shard);
    var pair: [2]std.posix.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), std.c.socketpair(std.c.AF.UNIX, std.c.SOCK.STREAM, 0, &pair));
    defer _ = std.c.close(pair[1]);
    const conn = try shard.addConnection(pair[0]);
    var buf: [4096]u8 = undefined;
    var two: [2]proto.Response = undefined;
    const max = @import("../protocol/history_entries.zig").MAX_OWNER;
    var name: [max + 1]u8 = undefined;
    @memset(&name, 'n');
    var db: [max + 256]u8 = undefined;
    const def = try std.fmt.bufPrint(&db, "{{\"kind\":\"Workflow\",\"name\":\"{s}\",\"version\":\"1.0.0\",\"start\":{{\"wait_for_signal\":{{\"type\":\"go\"}},\"transitions\":{{\"success\":\"flo.Completed\"}}}}}}", .{&name});
    const before = shard.raft_node.log.lastIndex();
    shard.runRequest(conn, try ParkTest.request(.workflow_create, 1, proto.DEFAULT_NAMESPACE, &name, def, ""), .client);
    const start = [_]u8{ 0, 0, 0, 0 };
    shard.runRequest(conn, try ParkTest.request(.workflow_start, 2, proto.DEFAULT_NAMESPACE, &name, &start, ""), .client);
    try ParkTest.responses(&shard, conn, pair[1], &buf, &two);
    for (two) |r| {
        try std.testing.expectEqual(@backingInt(proto.StatusCode.bad_request), r.header.status);
        try std.testing.expect(std.mem.startsWith(u8, (try r.refused()).message, "a workflow name is at most 256 bytes"));
    }
    try std.testing.expectEqual(before, shard.raft_node.log.lastIndex());
}
